/* 自动生成，请勿直接编辑。源文件：data/*.json，重新生成：node tools/build-data.js */
window.EXAM_PAPERS = [{"id":"gk-2023","title":"2023年国家公务员录用考试《行政职业能力测验》（副省级·模拟卷）","region":"全国","examType":"国考","subject":"行测","year":2023,"duration":120,"totalScore":100,"note":"本卷为依据历年真题题型结构编写的原创模拟题，非官方真题原文，仅供练习。","sections":[{"name":"言语理解与表达","material":null,"questions":[{"id":"gk-2023-01","stem":"城市更新并非要把老建筑________，而是在保留其历史信息的前提下，为它们注入适应现代生活的新功能。若一味推倒重来，割断的不仅是砖瓦，更是居民与城市之间那份难以________的情感联系。\n依次填入横线处的词语，最恰当的一组是：","options":["推陈出新 割裂","一扫而空 重建","连根拔起 割舍","改头换面 弥合"],"answer":2,"explain":"第一空由后文\"推倒重来\"提示，应体现彻底清除、不留根基之意，\"连根拔起\"最契合语境；第二空与\"情感联系\"搭配，\"难以割舍\"为固定表述，指情感上舍不得。其他选项或语义过轻，或与\"难以\"搭配后语意相反。"},{"id":"gk-2023-02","stem":"转型时期，企业若满足于既有成绩而________，就难以保持持续创新的能力。唯有对市场变化保持敏感，做好________的准备，才能在竞争中把握主动。\n依次填入横线处的词语，最恰当的一组是：","options":["固步自封 居安思危","墨守成规 无动于衷","按部就班 未雨绸缪","安于现状 望风而逃"],"answer":0,"explain":"第一空与\"满足于既有成绩\"\"难以持续创新\"照应，\"固步自封\"指守着老一套不求进步，最贴切；第二空与\"对市场变化保持敏感\"呼应，\"居安思危\"指在安定环境中想到可能的危险。B、D两项第二空与文意不符，C项第一空未突出拒绝进步之意。"},{"id":"gk-2023-03","stem":"将以下5个句子重新排列，语序最恰当的一项是：\n①文明交流互鉴是推动人类社会发展进步的重要动力\n②不同文明各有优长，也各有局限\n③只有在交流互鉴中取长补短，才能不断焕发新的生机\n④历史上，凡是开放包容的时期，文明往往繁荣昌盛\n⑤而封闭自守则常常导致停滞与衰落","options":["②①③④⑤","①③④⑤②","④⑤①③②","②④⑤①③"],"answer":0,"explain":"②先提出各文明各有优长与局限这一前提，①据此概括交流互鉴的重要意义，③承接①说明取长补短方能焕发生机，④⑤以历史上开放与封闭的正反事例作例证。全段遵循\"前提—观点—论证\"的顺序，②①③④⑤最为连贯。"},{"id":"gk-2023-04","stem":"人工智能生成内容给版权制度带来新的挑战：现有法律以人类作者为中心构建权利归属规则，而机器参与创作使得\"作者\"难以认定。然而，修法往往滞后于技术演进，若一味等待制度完善，大量侵权内容可能已在传播中损害原创者利益。因此，通过数字水印、内容标识等技术手段先行实现溯源与识别，是当前更为现实的路径。\n这段文字意在强调：","options":["法律修改滞后是版权保护不力的根本原因","人工智能生成内容使作者认定变得困难","技术手段可先行缓解人工智能生成内容的版权难题","数字水印是识别原创作品的唯一有效方式"],"answer":2,"explain":"文段先摆出\"作者\"难以认定的难题，再用\"因此\"引出结论：修法滞后，借助技术手段先行实现溯源与识别是更现实的路径，落脚点在技术先行。A项将修法滞后绝对化为根本原因，B项是问题本身而非对策，D项\"唯一\"表述过于绝对。"},{"id":"gk-2023-05","stem":"古籍数字化让珍本善本得以化身千百，读者足不出户便可阅览。但数字化并非简单扫描：版本的选择、残损页的补配、异体字的处理，都直接影响文本的可靠性。如果只追求数量而忽视校勘，数字资源库反而可能成为错误传播的温床。\n这段文字主要说明：","options":["古籍数字化使珍本善本得到更好保护","古籍数字化必须以保证文本质量为前提","古籍数字资源库的建设规模亟待扩大","异体字处理是古籍整理中最难的环节"],"answer":1,"explain":"\"但\"转折之后是重点：数字化不是简单扫描，若只追求数量而忽视校勘，反而会传播错误，可见核心在于强调质量应先于数量。A项仅出现在转折之前，属非重点；C项与文意相反；D项夸大了异体字处理在整体中的地位。"}]},{"name":"数量关系","material":null,"questions":[{"id":"gk-2023-06","stem":"甲、乙两车同时从同一地点出发，沿同一路线同向匀速行驶，甲车速度比乙车快20千米/小时。行驶2小时后，甲车行驶的路程是乙车的1.5倍。问乙车的速度是多少？","options":["30千米/小时","40千米/小时","50千米/小时","60千米/小时"],"answer":1,"explain":"两车行驶时间相同，路程比等于速度比，甲车路程为乙车的1.5倍，即甲车速度为乙车的1.5倍。设乙车速度为v，列式v+20=1.5v，解得v=40千米/小时。代入验证：2小时内乙车行80千米、甲车行120千米，120÷80=1.5，符合题意。"},{"id":"gk-2023-07","stem":"一项工程，甲队单独完成需要30天，乙队单独完成需要45天。甲队先单独工作5天后乙队加入，两队合作完成剩余工程。问从开工到完工共用了多少天？","options":["16天","18天","20天","22天"],"answer":2,"explain":"设总工程量为90（30与45的最小公倍数），甲队效率为3、乙队效率为2。甲队先做5天完成15，剩余75由两队合作，每天完成5，需75÷5=15天，总用时5+15=20天。也可用分数验证：1−5/30=5/6，除以1/18恰为15天。"},{"id":"gk-2023-08","stem":"某商品按成本加价50%定价，商家按定价销售一部分后，将剩余商品打八折促销，结果全部售出，总体利润率仍为35%。问打折售出的商品占全部商品的比例是多少？（同款商品成本相同，销量按件计）","options":["30%","40%","50%","60%"],"answer":2,"explain":"设成本为100元、共10件，则定价150元、八折价120元。设打折售出n件，由总销售额等于总成本加利润，列式150(10−n)+120n=1000×1.35=1350，即1500−30n=1350，解得n=5，占比5÷10=50%。"}]},{"name":"判断推理","material":null,"questions":[{"id":"gk-2023-09","stem":"观察下列数列的排列规律：4，7，13，25，？。按此规律，问号处应填入的数字是：","options":["37","43","49","51"],"answer":2,"explain":"相邻两项之差依次为3、6、12，构成公比为2的等比数列，故下一个差为24，问号处为25+24=49。也可看作后一项等于前一项的2倍再减1：4×2−1=7，7×2−1=13，13×2−1=25，故问号处为25×2−1=49。两种角度结果一致，规律唯一。"},{"id":"gk-2023-10","stem":"行政许可，是指行政机关根据公民、法人或者其他组织的申请，经依法审查，准予其从事特定活动的行为。\n根据上述定义，下列属于行政许可的是：","options":["市场监管局对某商场的商品质量进行抽样检查","交通管理部门向申请人核发机动车驾驶证","税务局对未按期申报的企业加收滞纳金","公安机关对打架斗殴的人员给予行政拘留处罚"],"answer":1,"explain":"行政许可须同时具备\"依申请\"\"依法审查\"\"准予从事特定活动\"三个要件。核发驾驶证系依当事人申请、经审查后准予其驾驶，符合定义。A项属行政检查，C项属征收滞纳金，D项属行政处罚，均非准予从事特定活动。"},{"id":"gk-2023-11","stem":"沉没成本，是指已经发生且无法收回的支出，理性决策者不应让其影响当前与未来的选择。\n根据上述定义，下列体现受沉没成本影响的是：","options":["小李花高价买了电影票，看了一半发现是烂片，为不浪费票钱坚持看完","小王比较三家酒店的报价后，选择了性价比最高的一家","小张每月固定存下一笔钱，以备将来购房之需","小赵在购买电脑时放弃已看中的型号，转而购买降价的新款"],"answer":0,"explain":"沉没成本的关键在于\"已发生、无法收回，却仍影响决策\"。小李的票钱已无法收回，继续看下去只会追加时间损失，却因\"不浪费票钱\"坚持看完，正是被沉没成本左右。B、D是权衡现价与收益的理性选择，C为储蓄规划，均不符合定义。"},{"id":"gk-2023-12","stem":"法律：道德 相当于：","options":["医生：护士","河流：湖泊","标尺：天平","城市：乡村"],"answer":2,"explain":"法律与道德同属社会规范，二者功能相近，只是保证实施的力量不同：一靠国家强制力，一靠社会舆论与信念。标尺与天平同属计量工具，功能相近而测量原理不同，与之关系最相似。医生与护士是不同职业的并列，河流与湖泊是不同水体形态的并列，城市与乡村是不同聚落形态的并列，三者都只是同类事物并列，未体现“功能相近而原理不同”，排除。"},{"id":"gk-2023-13","stem":"某研究机构调查发现，员工平均每周加班时长越长的公司，其人均产出反而越低。据此有专家认为，加班会降低员工的工作效率。\n以下哪项如果为真，最能削弱上述结论？","options":["部分员工加班是自愿行为，与公司制度要求无关","上述调查覆盖的公司数量较少，样本代表性有限","人均产出受设备水平、管理水平等多种因素影响","往往是业务量超出正常负荷、效率本就偏低的公司才长期安排加班"],"answer":3,"explain":"题干由\"加班时长与人均产出负相关\"推出\"加班导致效率下降\"的因果关系。D项指出可能是效率低、负荷重的公司才更多安排加班，即因果倒置，直接切断论证链条，削弱力度最强。A、B、C或只涉及个别情形与样本，或泛泛提及他因，力度均较弱。"},{"id":"gk-2023-14","stem":"某品牌宣称其新款手机充电速度\"行业第一\"，依据是实验室测得该机型从零电量充至50%仅需12分钟，而多款主流机型完成同样充电量需要15分钟以上。\n以下哪项如果为真，最能质疑该结论？","options":["该品牌的宣传海报设计精美，投放范围较广","参与对比的机型电池容量普遍大于该新款手机","该款手机在其他方面的性能表现较为一般","部分消费者对该品牌的售后服务并不满意"],"answer":1,"explain":"比较充电速度快慢须控制电池容量这一关键变量：容量越大，充至相同电量百分比所需的电量越多，耗时自然更长。B项表明对比机型容量普遍更大，说明该比较并不公平，直接质疑\"行业第一\"的结论。A、C、D与充电速度的比较无关。"}]},{"name":"资料分析","material":"某市文化产业发展情况（模拟数据）：\n年份\t文化产业增加值（亿元）\t增加值同比增速（%）\t从业人员（万人）\n2019年\t300\t—\t15.0\n2020年\t360\t20.0\t18.0\n2021年\t450\t25.0\t22.5\n2022年\t540\t20.0\t27.0","questions":[{"id":"gk-2023-15","stem":"根据资料，2021年该市文化产业增加值比2019年增长了：","options":["45%","50%","55%","60%"],"answer":1,"explain":"2021年增加值为450亿元，2019年为300亿元，增长率为(450−300)÷300=50%。也可用两年增速连乘验证：1.20×1.25=1.50，即两年累计增长50%，与直接计算结果一致。"},{"id":"gk-2023-16","stem":"根据资料，2021年和2022年两年合计，该市文化产业从业人员人均创造增加值约为：","options":["18万元/人","20万元/人","22万元/人","24万元/人"],"answer":1,"explain":"求多年人均指标须用总量相除，不能把各年人均值简单平均：(450+540)÷(22.5+27)=990÷49.5=20万元/人。各年单独计算亦均为20万元/人，说明该市文化产业人均产出保持稳定，故两年合计为20万元/人。"},{"id":"gk-2023-17","stem":"根据资料，下列说法正确的是：","options":["2022年该市文化产业增加值同比增速超过25%","2022年该市文化产业从业人员人均创造增加值达到20万元/人","2021年该市文化产业从业人员人均创造增加值达30万元/人","2021年该市文化产业增加值超过500亿元"],"answer":1,"explain":"2022年从业人员为27万人、增加值为540亿元，人均创造增加值540÷27＝20万元/人，B项正确。2022年增加值增速为20%，未超过25%，A错；2021年人均为450÷22.5＝20万元，C错；2021年增加值为450亿元，未超过500亿元，D错。"}]},{"name":"常识判断","material":null,"questions":[{"id":"gk-2023-18","stem":"根据《中华人民共和国民法典》，下列关于居住权的说法正确的是：","options":["居住权可以自由转让给他人","居住权可以继承","设立居住权应当采用书面形式并办理登记","当事人不得无偿设立居住权"],"answer":2,"explain":"民法典规定，设立居住权应当采用书面形式订立居住权合同，并向登记机构申请居住权登记，居住权自登记时设立，C项正确。居住权不得转让、继承，故A、B错误；居住权原则上无偿设立，当事人另有约定的除外，D项表述过于绝对。"},{"id":"gk-2023-19","stem":"某区市场监管局以甲超市销售过期食品为由，对其作出罚款两万元的处罚决定。甲超市不服，欲寻求救济。根据《中华人民共和国行政复议法》及相关规定，下列说法正确的是：","options":["甲超市只能向区市场监管局本身申请复议","甲超市可以申请行政复议，也可以直接向人民法院提起行政诉讼","甲超市必须先申请行政复议，对复议决定不服才能起诉","甲超市只能提起行政诉讼，不能申请行政复议"],"answer":1,"explain":"对行政处罚不服不属于法律规定的复议前置情形，当事人既可以申请行政复议，也可以直接向人民法院提起行政诉讼，由当事人自行选择，B项正确。A项，依《行政复议法》规定，对区市场监管局这类政府工作部门的行政行为不服，应由本级人民政府管辖，而非向该机关自身申请复议；C项混淆了复议前置的适用范围；D项剥夺了当事人申请复议的权利。"},{"id":"gk-2023-20","stem":"《中华人民共和国宪法》是我国的根本法。下列关于宪法的说法正确的是：","options":["宪法只规定公民的基本权利，不规定国家机关的组织与职权","宪法的修改由全国人民代表大会常务委员会以全体组成人员的三分之二以上多数通过","宪法具有最高的法律效力，一切法律、行政法规和地方性法规都不得同宪法相抵触","宪法的制定和修改程序与普通法律完全相同"],"answer":2,"explain":"宪法具有最高法律效力，一切法律、行政法规、地方性法规都不得同宪法相抵触。宪法既规定公民基本权利，也规定国家机构组织与职权，A错；宪法修改须由全国人民代表大会以全体代表的三分之二以上多数通过，B错；其制定修改程序比普通法律更严格，D错。"}]},{"name":"政治理论","material":null,"questions":[{"id":"gk-2023-21","stem":"马克思主义认为，物质决定意识，意识对物质具有能动的反作用。下列关于物质与意识辩证关系的说法正确的是：","options":["意识的内容和形式都来源于人脑，是主观自生的","物质决定意识，因此意识在任何情况下都不能影响物质","意识具有能动作用，正确的意识能够指导人们有效地改造客观世界","只要充分发挥主观能动性，就能够改变事物发展的客观规律"],"answer":2,"explain":"意识是对客观存在的主观映象，其内容来自客观世界而非主观自生，A错；物质决定意识，但意识具有能动的反作用，B否认了意识的能动作用；D夸大了主观能动性，认为可以改变客观规律，属唯心主义。C正确指出了正确意识的指导作用。"},{"id":"gk-2023-22","stem":"“不积跬步，无以至千里；不积小流，无以成江海。”这句话所蕴含的哲学道理是：","options":["事物的发展是量变与质变的统一，量的积累达到一定程度必然引起质变","事物发展的道路是曲折的，前途是光明的","矛盾双方在一定条件下可以相互转化","认识来源于实践并随着实践的发展而不断深化"],"answer":0,"explain":"“跬步”“小流”强调量的点滴积累，“至千里”“成江海”则是积累到一定程度引起的质变，体现量变是质变的必要准备、质变是量变的必然结果，A正确。B讲发展道路，C讲矛盾转化，D讲认识论，均与“积累”这一主旨不符。"},{"id":"gk-2023-23","stem":"一种认识是否正确，不能由主观的夸张来决定，而只能由社会实践来检验。这是因为：","options":["实践是认识的来源，也是认识的最终目的","真理是客观的，不以任何人的意志为转移","实践是主观见之于客观的物质性活动，能把主观认识同客观实际联系起来加以比较","多数人赞同和接受的认识就是真理"],"answer":2,"explain":"实践具有直接现实性，是联结主观与客观的桥梁，能把认识拿到客观实际中去对照验证，因而成为检验认识真理性的唯一标准，C正确。A说的是认识的来源和目的，与“为什么能检验”不对应；B虽正确但未说明理由；D以多数人意见作标准，属主观标准。"}]}]},{"id":"gk-2024","title":"2024年国家公务员录用考试《行政职业能力测验》（副省级·模拟卷）","region":"全国","examType":"国考","subject":"行测","year":2024,"duration":120,"totalScore":100,"note":"本卷为依据历年真题题型结构编写的原创模拟题，非官方真题原文，仅供练习。","sections":[{"name":"言语理解与表达","material":null,"questions":[{"id":"gk-2024-01","stem":"城市更新不是简单的“推倒重来”，而是要在保留历史肌理的基础上____功能、优化布局，这就要求决策者摒弃____的做法，以绣花功夫精细化推进。\n依次填入横线部分最恰当的一项是：","options":["改变 / 因循守旧","削弱 / 急功近利","完善 / 大拆大建","突破 / 一蹴而就"],"answer":2,"explain":"第一空与“优化布局”并列，“完善功能”搭配最恰当，“削弱”“突破”均不能与功能搭配；第二空须与开头的“推倒重来”和后文“绣花功夫精细化”形成对照，“大拆大建”正指粗放式拆建。因循守旧侧重保守，急功近利侧重动机，一蹴而就侧重速度，均不合。"},{"id":"gk-2024-02","stem":"在信息过载的时代，真正稀缺的不是获取信息的渠道，而是____信息的能力。唯有学会筛选、质疑与整合，才能避免在海量资讯中____。\n依次填入横线部分最恰当的一项是：","options":["记忆 / 不知所措","甄别 / 迷失方向","传播 / 随波逐流","储存 / 人云亦云"],"answer":1,"explain":"第一空需与“筛选、质疑与整合”呼应，“甄别信息”即辨别真伪优劣，最为贴切；第二空“在海量资讯中迷失方向”与“信息过载”构成因果。记忆、传播、储存均未体现辨别之意，“人云亦云”与“在海量资讯中”这一状语搭配不当。"},{"id":"gk-2024-03","stem":"算法推荐极大降低了我们获取信息的成本，但它也在悄然重塑我们看待世界的方式。当一个人长期只接触与自己偏好一致的内容时，会逐渐形成认知上的“回音壁”：相似的观点被不断强化，不同的声音则被过滤在外。更值得警惕的是，这种筛选往往在用户毫无察觉的情况下完成，人们甚至会把算法推送的结果当作自己独立思考的结论。\n这段文字主要说明的是：","options":["算法推荐提高了人们获取信息的效率","算法推送的内容往往与用户的偏好高度一致","算法推荐可能在不被察觉中窄化人的认知","独立思考能力与算法推荐之间存在根本冲突"],"answer":2,"explain":"文段先让步承认算法推荐降低成本，随后用“但”转入重点：偏好一致的内容形成认知“回音壁”，且这一筛选在用户毫无察觉中完成，主旨落在算法推荐对认知的隐性窄化。提高效率属转折前的次要信息，偏好一致只是现象描述，“根本冲突”则属过度推断。"},{"id":"gk-2024-04","stem":"保护历史建筑，并不意味着把它们变成与日常生活隔绝的标本。一座老厂房如果只被围起来供人远观，它的价值反而会随着时间流逝而不断贬值。真正有效的保护，是让建筑继续承担某种功能——可以改造成社区图书馆、创客空间或市集，让人们在日常使用中感知它的存在。使用本身，就是最好的保护。\n这段文字意在强调：","options":["历史建筑的价值会随时间流逝而不断贬值","历史建筑保护的关键在于持续的功能使用","社区图书馆是改造旧厂房的最佳方式","保护历史建筑需要大量资金投入"],"answer":1,"explain":"文段先否定“围起来远观”的保护方式，再给出正面主张：让建筑继续承担功能，在日常使用中实现保护，末句“使用本身，就是最好的保护”点明主旨。价值贬值只是论据，“最佳方式”表述过于绝对，资金投入在文中并未提及。"},{"id":"gk-2024-05","stem":"将以下5个句子重新排列，语序最恰当的一项是：\n①这种被反复验证的价值，往往需要读者在反复阅读中才能体会\n②经典之所以被称为经典，正在于它们触及了人类共同的精神困境\n③因此，阅读经典从来不是一件轻松的事\n④它们历经时间的淘洗而留存，本身就说明了某种价值\n⑤但恰恰是这种不轻松，赋予了它无可替代的意义","options":["④②③①⑤","③⑤②④①","②①④③⑤","②④①③⑤"],"answer":3,"explain":"②提出经典话题，④以“它们”承接并指出其价值，①的“这种价值”指代④，③由“因此”得出阅读经典并不轻松，⑤再以“但”转折强调其意义，逻辑连贯。④含代词不能作首句，③以“因此”开头亦不能领起全段。"}]},{"name":"数量关系","material":null,"questions":[{"id":"gk-2024-06","stem":"甲、乙两人合作完成一项工程需要12天。若甲先单独做6天，再由乙单独做15天，恰好完成全部工程。问乙单独完成这项工程需要多少天？","options":["12天","15天","16天","18天"],"answer":3,"explain":"设甲、乙效率分别为a、b，由合作12天完成得a＋b＝1/12；再由6a＋15b＝1代入解得b＝1/18，即乙单独完成需18天。也可这样想：甲做6天后乙再做15天，相当于两人先合作6天完成一半，余下一半由乙独做9天完成。"},{"id":"gk-2024-07","stem":"甲、乙两车同时从A地出发匀速驶向B地。甲车速度比乙车快20%，甲车到达B地后立即原路返回，在距B地30公里处与乙车相遇。问A、B两地相距多少公里？","options":["240公里","280公里","330公里","360公里"],"answer":2,"explain":"相遇时两车行驶时间相同，路程之比等于速度之比。设两地相距D公里，则(D＋30)∶(D－30)＝1.2∶1，即D＋30＝1.2D－36，解得D＝330。验证：甲共行360公里，乙共行300公里，比值恰为1.2，与速度比一致。"},{"id":"gk-2024-08","stem":"某单位要从5名男职工和4名女职工中选出4人组成调研小组，要求小组中至少有1名女职工。问共有多少种不同的选法？","options":["105种","116种","121种","126种"],"answer":2,"explain":"从9人中任选4人共有C(9,4)＝126种；不满足“至少有1名女职工”的情况是4人全为男职工，有C(5,4)＝5种。故符合条件的选法为126－5＝121种。遇到“至少一个”的条件，通常用总数减去对立情况更为简便。"}]},{"name":"判断推理","material":null,"questions":[{"id":"gk-2024-09","stem":"一组图形的外轮廓依次为正三角形、正方形、正五边形、正六边形、正七边形，每个图形内部都画出了连接不相邻顶点的全部对角线。若这一序列的规律持续成立，则第六个图形（外轮廓为正八边形）内部的对角线共有多少条？","options":["16条","20条","24条","28条"],"answer":1,"explain":"n边形的对角线总数为n(n－3)/2。三角形、四边形、五边形、六边形、七边形的对角线依次为0、2、5、9、14条，与前五个图形一致。第六个图形为正八边形，对角线共8×(8－3)÷2＝20条。"},{"id":"gk-2024-10","stem":"语义饱和是指人长时间注视或反复念诵某个词语后，会突然觉得该词语变得陌生、失去意义的现象。\n根据上述定义，下列属于语义饱和的是：","options":["小李在国外生活多年，回国后一时想不起某些汉语词汇该怎么说","小张反复抄写“诚信”一词二十遍后，忽然觉得这两个字看起来很陌生，像是第一次见到","小王反复朗读一首古诗，很快就把整首诗背了下来","小赵看到反复播放的广告，起初觉得厌烦，后来渐渐习以为常"],"answer":1,"explain":"语义饱和的关键有二：长时间注视或反复念诵同一词语，以及该词语突然变得陌生、失去意义。反复抄写后觉得字变陌生完全符合定义。想不起词汇属于提取困难，背诵成功与对广告习惯化都没有出现“意义丧失”这一结果。"},{"id":"gk-2024-11","stem":"框架效应是指人们对同一信息，因表述方式不同（如采用收益表述或损失表述）而作出不同决策的现象。\n根据上述定义，下列属于框架效应的是：","options":["消费者在打折季购买了大量并不需要的商品","投资者在股价下跌时不愿卖出，期待价格回升","医生告诉病人“手术后有九成把握存活”时，病人更愿意接受手术；而被告知“手术有一成死亡风险”时，病人则倾向于拒绝","员工在得到领导表扬后工作更加努力"],"answer":2,"explain":"框架效应的核心是同一信息因表述方式不同而导致不同决策。存活率与死亡率两种表述实质完全相同，病人的选择却相反，符合定义。打折季多买属于冲动消费，持股不卖属于处置效应，受表扬更努力属于正强化，均不涉及信息的表述框架。"},{"id":"gk-2024-12","stem":"囫囵吞枣∶不求甚解","options":["兢兢业业∶恪尽职守","雪中送炭∶锦上添花","画蛇添足∶画龙点睛","门可罗雀∶车水马龙"],"answer":0,"explain":"题干两词为近义关系，均形容学习不深入、不求彻底理解。兢兢业业与恪尽职守都表示做事认真、尽心尽责，构成近义。雪中送炭与锦上添花是不同情境下给予帮助，画蛇添足与画龙点睛、门可罗雀与车水马龙则均为反义关系。"},{"id":"gk-2024-13","stem":"某研究团队对2000名成年人进行了为期五年的跟踪调查，发现每周进行三次以上有氧运动的人，患高血压的比例明显低于不运动的人。据此，研究者认为规律的有氧运动能够降低高血压的患病风险。\n以下哪项如果为真，最能削弱上述结论？","options":["有氧运动的形式多样，包括跑步、游泳、骑行等","坚持规律运动的人原本血压大多正常，且在饮食上更为清淡","高血压的发病与遗传因素也有一定关系","部分不运动的人因工作繁忙，难以抽出时间锻炼"],"answer":1,"explain":"结论认为规律运动降低高血压风险。若坚持运动者原本血压正常且饮食更清淡，则其患病比例低可能源于体质与饮食差异，而非运动本身，属于典型的他因削弱与自我选择偏倚。运动形式、遗传因素、没时间锻炼均不能有效削弱该结论。"},{"id":"gk-2024-14","stem":"某市近年来大力推广垃圾分类，但调查显示，居民对垃圾分类的准确投放率仍不足六成。有专家指出，投放准确率低的主要原因并非居民缺乏分类知识，而是分类垃圾桶的设置位置不合理、标识不清晰。\n以下哪项如果为真，最能支持专家的观点？","options":["部分居民认为垃圾分类过于繁琐，不愿意花时间分类","该市部分小区的垃圾清运车未做到分类运输，存在混装现象","邻市推广垃圾分类的时间与本市大致相同","该市垃圾分类知识普及率已达九成以上，多数居民能准确说出常见垃圾的类别"],"answer":3,"explain":"专家观点是准确率低的原因在于垃圾桶位置与标识，而非居民缺乏知识。若知识普及率已达九成以上、多数居民能准确识别类别，就排除了“缺乏知识”这一替代解释，直接支持专家观点。其余选项或提出他因，或与论证无关。"}]},{"name":"资料分析","material":"某工业园区管委会发布的年度运行情况（本卷为模拟数据）显示：\n①2023年园区规模以上企业实现营业收入60亿元，比上年增长20%；\n②其中，电子信息产业营业收入24亿元，比上年增长50%；\n③智能制造产业营业收入27亿元，比上年增长12.5%；\n④园区营业收入除上述两大产业外，其余均来自环保产业；\n⑤2023年园区新增入驻企业30家，年末企业总数达到200家。","questions":[{"id":"gk-2024-15","stem":"2022年该园区电子信息产业营业收入占全年营业收入的比重约为：","options":["25%","32%","40%","48%"],"answer":1,"explain":"2022年园区营业收入为60÷(1＋20%)＝50亿元，电子信息产业为24÷(1＋50%)＝16亿元，故2022年其占比为16÷50＝32%。求基期比重时分子分母须同为基期数值，若用2023年数据会得到40%，这是常见陷阱。"},{"id":"gk-2024-16","stem":"与2022年相比，2023年该园区环保产业营业收入的变化情况是：","options":["增长12%","增长10%","下降10%","下降20%"],"answer":2,"explain":"2023年环保产业营业收入为60－24－27＝9亿元；2022年园区总营业收入为50亿元，环保产业为50－16－24＝10亿元。由9÷10－1＝－10%可知同比下降10%。“其余均来自环保产业”是求出该项数据的关键，不能直接用总增速判断。"},{"id":"gk-2024-17","stem":"2023年该园区户均营业收入约为多少万元？","options":["1500万元","2400万元","3000万元","3600万元"],"answer":2,"explain":"2023年园区营业收入60亿元，年末企业200家，户均营业收入为60÷200＝0.3亿元，即3000万元。注意单位换算，0.3亿元等于3000万元；若误用“新增企业30家”作分母，会得到2亿元这一明显错误的结果。"}]},{"name":"常识判断","material":null,"questions":[{"id":"gk-2024-18","stem":"根据我国宪法的规定，下列表述正确的是：","options":["国务院总理由全国人民代表大会选举产生","全国人民代表大会有权改变或者撤销全国人民代表大会常务委员会不适当的决定","县级以上地方各级人民代表大会每届任期四年","人民法院、人民检察院对同级人民政府负责"],"answer":1,"explain":"宪法规定，全国人民代表大会有权改变或者撤销全国人大常委会不适当的决定。国务院总理由国家主席提名、全国人大决定，并非选举产生；地方各级人民代表大会每届任期五年；人民法院、人民检察院对产生它的人民代表大会及其常委会负责，不对同级政府负责。"},{"id":"gk-2024-19","stem":"根据我国《民法典》的规定，下列表述正确的是：","options":["10周岁的小刚独自购买一瓶2元的矿泉水，该行为无效","因受到欺诈而订立的合同，无论何种情形均自始无效","限制民事行为能力人实施的所有民事法律行为，均需其法定代理人同意或追认","7周岁的小明独自将家中价值5000元的平板电脑赠与他人，该行为无效"],"answer":3,"explain":"不满八周岁的未成年人为无民事行为能力人，其独立实施的民事法律行为无效，故7周岁的小明赠与平板电脑的行为无效，D项正确。10周岁为限制民事行为能力人，购买2元矿泉水与其年龄、智力相适应，行为有效，A错；受欺诈订立的合同属可撤销而非当然无效，B错；限制民事行为能力人实施的纯获利益的民事法律行为无需法定代理人同意或追认，C错。"},{"id":"gk-2024-20","stem":"下列关于日常生活中的科学常识，表述正确的是：","options":["夏天在室内洒水降温，主要是利用了水的比热容较大的特性","用久了的白炽灯泡内壁变黑，是因为钨丝发生了升华和凝固","冬天玻璃窗上的冰花结在玻璃的外表面","高压锅能提高锅内气压，使水的沸点升高，从而加快食物成熟"],"answer":3,"explain":"高压锅密封使锅内气压升高，水的沸点随之升高，食物更易熟透。洒水降温靠的是水蒸发吸热，而非比热容大；灯泡内壁变黑是钨丝先升华后凝华；冰花是室内水蒸气在玻璃内表面凝华形成的，其余三项均表述有误。"}]},{"name":"政治理论","material":null,"questions":[{"id":"gk-2024-21","stem":"社会意识是社会存在的反映，但又具有相对独立性。下列现象最能体现社会意识相对独立性的是：","options":["随着生产力水平的提高，人们的物质生活水平不断改善","经济相对落后的地区，在思想文化领域也可能取得突出成就","法律等社会意识形式随着经济基础的变化而变化","社会意识的内容归根到底来源于社会存在"],"answer":1,"explain":"社会意识的相对独立性表现为它与社会存在的发展变化不完全同步，可能落后或超前于社会存在。经济相对落后的地区在思想文化领域取得突出成就，正说明二者并非亦步亦趋。A、D强调社会存在决定社会意识，C体现社会意识随经济基础变化，均不属相对独立性。"},{"id":"gk-2024-22","stem":"坚持以人民为中心的发展思想，是新时代坚持和发展中国特色社会主义的重要内容。下列做法最能体现这一思想的是：","options":["某地为追求经济增速，引进高污染项目而忽视群众的健康诉求","某市在老旧小区改造中广泛征求居民意见，优先解决加装电梯、无障碍通道等急难愁盼问题","某单位为完成考核指标，层层加码向基层摊派任务","某企业为提高利润，长期拖欠职工工资和社会保险费用"],"answer":1,"explain":"以人民为中心要求发展为了人民、发展依靠人民、发展成果由人民共享。B项倾听居民意见、解决急难愁盼问题，正是把人民利益放在首位的体现。A、C、D分别以经济增速、考核指标和企业利润牺牲群众利益，与以人民为中心的要求背道而驰。"},{"id":"gk-2024-23","stem":"关于中国特色社会主义，下列说法正确的是：","options":["中国特色社会主义最本质的特征是生产资料公有制","中国共产党的领导是中国特色社会主义最本质的特征，也是中国特色社会主义制度的最大优势","中国特色社会主义就是照搬其他社会主义国家的建设模式","中国特色社会主义进入新时代后，社会主要矛盾已变为人民日益增长的物质文化需要同落后的社会生产之间的矛盾"],"answer":1,"explain":"党的领导是中国特色社会主义最本质的特征，也是中国特色社会主义制度的最大优势，B正确。A把经济制度与本质特征相混淆；C违背了独立自主探索本国发展道路的要求；D表述的是已经转化的旧提法，与新时代我国社会主要矛盾的实际不符。"}]}]},{"id":"gk-2025","title":"2025年国家公务员录用考试《行政职业能力测验》（副省级·模拟卷）","region":"全国","examType":"国考","subject":"行测","year":2025,"duration":120,"totalScore":100,"note":"本卷为依据历年真题题型结构编写的原创模拟题，非官方真题原文，仅供练习。","sections":[{"name":"言语理解与表达","material":null,"questions":[{"id":"gk-2025-01","stem":"近年来，一些城市在老旧小区改造中不再简单地刷墙、铺路，而是把居民请进设计过程：晾衣杆的高度、楼道扶手的位置、小区花园里种什么花，都由居民商量着定。改造完成后，居民主动维护公共设施的意愿明显提高，一些原本难以推动的事项也变得顺畅。这说明，城市更新不只是物质空间的翻新，更是社区关系的重建。\n这段文字意在说明：","options":["老旧小区改造应当优先满足居民的物质需求","城市更新需要重视居民参与和社区关系的重建","居民主动维护公共设施是改造成功的唯一标准","刷墙、铺路等传统改造方式已经不再适用"],"answer":1,"explain":"文段先介绍改造中居民全过程参与的具体做法，末句以“这说明”收束，强调城市更新不只是物质空间翻新，更是社区关系的重建。B项是对主旨的准确概括；A项只停留在物质层面，C项“唯一标准”绝对化，D项并非文段观点。"},{"id":"gk-2025-02","stem":"在信息随手可得的时代，人们获取知识的成本大大降低，但真正的理解反而变得稀缺。一条条结论被快速接收、快速转发，却很少有人追问它从何而来、在什么条件下成立。知识如果只以结论的形式存在，就无法在新的情境中被调用。教育要做的，或许不是把更多结论塞给学生，而是让他们经历得出结论的过程。\n这段文字意在强调：","options":["信息时代人们获取知识的成本已大大降低","应当减少对网络信息的接收和转发","教育应重视引导学生经历得出结论的过程","结论性的知识在新的情境中毫无价值"],"answer":2,"explain":"文段先指出现象：结论易得而理解稀缺；末句用“不是……而是……”亮明意图，即让学生经历得出结论的过程。C项与之吻合。A项只是背景铺垫，B项无从得出，D项“毫无价值”表述过于绝对。"},{"id":"gk-2025-03","stem":"将下列句子重新排列，语序最恰当的一项是：\n① 这种“慢”并非效率低下，而是一种必要的沉淀\n② 与此形成对照的是，许多传统手艺的传承都强调“慢工出细活”\n③ 在追求速度的今天，人们习惯于用最短的时间完成最多的事情\n④ 正是在一遍遍重复与打磨中，手艺人的经验才逐渐内化为身体记忆\n⑤ 因此，面对需要长期积累的技艺，我们需要重新理解“快”与“慢”的关系","options":["③②①④⑤","②③①⑤④","③①②⑤④","②①③④⑤"],"answer":0,"explain":"③先提出“追求速度”的时代背景，②以“与此形成对照”转入传统手艺之“慢”，①中“这种慢”承接②，④的“一遍遍重复与打磨”进一步解释①中的“沉淀”，⑤用“因此”作总结。故顺序为③②①④⑤。"},{"id":"gk-2025-04","stem":"提升公共服务的精细化水平，不能________，而要从群众的实际需求出发，把工作做到具体场景中去；唯有如此，政策才能避免________，真正落地见效。\n依次填入横线处的词语，最恰当的一组是：","options":["一蹴而就 朝令夕改","大而化之 悬在空中","面面俱到 半途而废","墨守成规 因人而异"],"answer":1,"explain":"第一空与后文“从实际需求出发、做到具体场景”构成反义对应，应选表示笼统粗糙、不细致的“大而化之”；第二空与“真正落地见效”呼应，“悬在空中”指政策停留在纸面不落实。两组词均契合语境。"},{"id":"gk-2025-05","stem":"任何一种文明的成长，都离不开与其他文明的交流互鉴。封闭自守看似安全，实则会使自身失去活力，最终________。\n填入横线处最恰当的一项是：","options":["一败涂地","无足轻重","停滞不前","望尘莫及"],"answer":2,"explain":"空缺处与前文“失去活力”构成因果顺承，强调文明发展陷入停顿，“停滞不前”最为贴切。“一败涂地”多指失败惨重，语义过重；“无足轻重”指地位不重要，“望尘莫及”指远远落后，均与语境不符。"}]},{"name":"数量关系","material":null,"questions":[{"id":"gk-2025-06","stem":"一项工程，甲队单独完成需要12天，乙队单独完成需要18天。现两队合作4天后，剩余部分由乙队单独完成，则乙队还需要多少天？","options":["6天","8天","9天","10天"],"answer":1,"explain":"设工作总量为36，则甲效率为3、乙效率为2。合作4天完成(3+2)×4=20，剩余16，由乙单独完成需16÷2=8天。故选B。"},{"id":"gk-2025-07","stem":"甲、乙两车分别从A、B两地同时出发相向而行，第一次相遇时距A地60千米。两车到达对方出发地后均立即原路返回，第二次相遇时距B地30千米。则A、B两地相距多少千米？","options":["120千米","150千米","180千米","210千米"],"answer":1,"explain":"第一次相遇时甲车行了60千米；第二次相遇时两车合走3个全程，故甲车共行60×3=180千米。此时相遇点距B地30千米，即从A地量起为全程加30千米，故全程为180-30=150千米。"},{"id":"gk-2025-08","stem":"甲、乙等5人随机排成一排照相，甲与乙恰好不相邻的概率是：","options":["2/5","1/2","3/5","7/10"],"answer":2,"explain":"5人任意排列共5!=120种。甲、乙相邻时把二人捆绑为一个整体，有2×4!=48种；则不相邻有120-48=72种，所求概率为72÷120=3/5。故选C。"}]},{"name":"判断推理","material":null,"questions":[{"id":"gk-2025-09","stem":"题干给出的一组图形均由若干条长度不等、互不相交的线段组成，从左到右各图形中线段的数量依次为2、3、4、5。按此规律，问号处的图形应由多少条线段组成？","options":["由4条线段组成的图形","由5条线段组成的图形","由6条线段组成的图形","由7条线段组成的图形"],"answer":2,"explain":"题干图形只有一个变化要素，即线段数量，依次为2、3、4、5，构成公差为1的等差数列，因此问号处图形应由6条线段组成，只有C项符合该规律。"},{"id":"gk-2025-10","stem":"沉没成本是指已经发生且无法收回的支出，理性决策应当把它排除在决策依据之外。\n根据上述定义，下列属于沉没成本的是：","options":["小李为已经取消的资格考试购买了教材，书款不能退还","小王预订了可以免费取消的酒店房间，尚未付款","某公司每月需要支付的办公场地租金","小张计划购车，正在比较各银行的车贷利率"],"answer":0,"explain":"沉没成本的关键是“已发生且不可收回”。A项教材费已支付又不能退还，符合定义。B项可免费取消、尚未付款，C项属于尚未发生的固定支出，D项尚未发生任何购车支出，均不符合。"},{"id":"gk-2025-11","stem":"不当得利是指没有合法根据取得利益，致使他人受损失的事实。\n根据上述定义，下列构成不当得利的是：","options":["乙按租赁合同的约定向承租人收取租金","丙接受了朋友赠送的生日礼物","甲在银行取款时，因柜员操作失误多收了5000元且未返还","丁在路边拾得他人遗失物后主动交给公安机关"],"answer":2,"explain":"不当得利要求“没有合法根据”“取得利益”“他人受损失”同时具备。甲因柜员失误多收款且无合法根据，构成不当得利。乙有合同依据，丙有赠与依据，丁并未取得利益，均不构成。"},{"id":"gk-2025-12","stem":"作家∶钢笔∶写作","options":["医生∶患者∶诊治","厨师∶菜刀∶烹饪","园丁∶花草∶修剪","律师∶法律∶辩护"],"answer":1,"explain":"题干为“主体∶工具∶行为”的对应关系，作家使用钢笔进行写作。厨师使用菜刀进行烹饪与之完全一致。医生面对的是对象，园丁修剪的是对象，法律是律师辩护的依据而非工具，均不符合。"},{"id":"gk-2025-13","stem":"某研究发现，经常喝茶的人患某类心血管疾病的比例明显低于不喝茶的人，据此研究人员认为，喝茶有助于预防该类心血管疾病。\n以下哪项如果为真，最能削弱上述结论？","options":["茶叶中含有多种有益于心血管健康的成分","常喝茶的人往往同时更注意饮食清淡并坚持锻炼","该项研究的样本量较大，跟踪调查的时间也较长","不喝茶的人中也有相当一部分人身体健康"],"answer":1,"explain":"题干由两类人群患病比例不同推出喝茶的预防作用，属对比推理。B项说明常喝茶者在饮食、锻炼等生活方式上同时更健康，可能存在其他原因导致患病比例低，属“另有他因”的削弱。A、C项加强，D项无关。"},{"id":"gk-2025-14","stem":"为缓解城市交通拥堵，某市拟在主干道增设公交专用道。有专家指出，此举会压缩社会车辆的通行空间，可能使拥堵加剧；支持者则认为，公交专用道能提高公交车运行效率，吸引更多人改乘公交，从而减少道路上的车辆总量，最终缓解拥堵。\n以下哪项如果为真，最能支持支持者的观点？","options":["该市公交车的平均运行速度长期低于社会车辆","一些已设公交专用道的城市，主干道社会车辆通行速度有所下降","该市主干道沿线居民大多拥有私家车，出行以自驾为主","该市多数主干道公交客流量大，专用道可使公交车准点率显著提高，具备吸引自驾者改乘公交的条件"],"answer":3,"explain":"支持者的推理关键在于：专用道能否吸引自驾者改乘公交，从而减少车辆总量。D项说明公交客流量大且准点率可显著提高，具备吸引转移的条件，直接支持该推理。A、B、C项均削弱或不利于该观点。"}]},{"name":"资料分析","material":"2024年，某市实现地区生产总值8000亿元，比上年增长6.0%。其中，第一产业增加值400亿元，增长3.0%；第二产业增加值3200亿元，增长5.0%；第三产业增加值4400亿元，增长7.0%。\n2024年，该市规模以上工业增加值同比增长7.5%，增速比上年提高1.5个百分点；全年固定资产投资3000亿元，比上年增长8.0%。\n2024年末，该市常住人口500万人，比上年末增加10万人。","questions":[{"id":"gk-2025-15","stem":"2024年，该市第三产业增加值占地区生产总值的比重约为：","options":["45%","50%","55%","60%"],"answer":2,"explain":"根据材料，2024年该市地区生产总值为8000亿元，第三产业增加值为4400亿元，所求比重为4400÷8000=55%。故选C。"},{"id":"gk-2025-16","stem":"2023年，该市规模以上工业增加值同比增长约：","options":["9.0%","6.0%","5.0%","7.5%"],"answer":1,"explain":"材料给出2024年该市规模以上工业增加值同比增长7.5%，且增速比上年提高1.5个百分点，则2023年的增速为7.5%-1.5%=6.0%。故选B。"},{"id":"gk-2025-17","stem":"2024年，该市常住人口比上年末约增长：","options":["约1.5%","约2.0%","约5.0%","约2.5%"],"answer":1,"explain":"2024年末该市常住人口500万人，比上年末增加10万人，则2023年末为500-10=490万人。增长率为10÷490≈2.04%，最接近2.0%。故选B。"}]},{"name":"常识判断","material":null,"questions":[{"id":"gk-2025-18","stem":"根据我国宪法规定，下列关于公民基本权利的说法正确的是：","options":["公民的通信自由和通信秘密不受任何限制","公民的住宅不受侵犯，禁止非法搜查或者非法侵入公民的住宅","公民年满十八周岁后即自动取得选举权，且必须参加投票","公民对国家机关及其工作人员的违法失职行为只能向人民法院提起诉讼"],"answer":1,"explain":"宪法规定公民的住宅不受侵犯，禁止非法搜查或者非法侵入公民的住宅，B项正确。通信自由和通信秘密受法律保护，但可依法定程序检查；选举权还须未被剥夺政治权利，投票可以放弃；对违法失职行为公民有权申诉、控告、检举。"},{"id":"gk-2025-19","stem":"根据《中华人民共和国民法典》，下列关于自然人民事权利能力和民事行为能力的说法正确的是：","options":["自然人的民事权利能力始于出生，终于死亡","八周岁以上的未成年人为无民事行为能力人","十六周岁以上的未成年人一律视为完全民事行为能力人","法人的民事权利能力与自然人的民事权利能力完全相同"],"answer":0,"explain":"民法典规定，自然人从出生时起到死亡时止具有民事权利能力，A项正确。八周岁以上的未成年人是限制民事行为能力人；十六周岁以上以自己劳动收入为主要生活来源者才视为完全民事行为能力人；法人与自然人的权利能力并不相同。"},{"id":"gk-2025-20","stem":"下列关于中国古代科技文化成就的表述，正确的是：","options":["张衡发明的地动仪能够准确预测地震发生的时间","《本草纲目》是我国现存最早的药物学专著","祖冲之将圆周率精确到小数点后第七位","活字印刷术由东汉时期的蔡伦发明"],"answer":2,"explain":"祖冲之算出圆周率在3.1415926与3.1415927之间，即精确到小数点后第七位，C项正确。地动仪只能测知地震的发生及方位，不能预测时间；现存最早的药物学专著是《神农本草经》；活字印刷术由北宋毕昇发明，蔡伦改进的是造纸术。"}]},{"name":"政治理论","material":null,"questions":[{"id":"gk-2025-21","stem":"“因地制宜”“对症下药”“一把钥匙开一把锁”这些说法共同体现的哲学道理是：","options":["矛盾的普遍性寓于特殊性之中，并通过特殊性表现出来","要具体分析矛盾的特殊性，坚持具体问题具体分析","主要矛盾在事物发展过程中处于支配地位、起决定作用","事物的发展是前进性与曲折性的统一"],"answer":1,"explain":"“因地制宜”“对症下药”“一把钥匙开一把锁”都强调针对不同对象的具体特点采取不同办法，即承认矛盾的特殊性，坚持具体问题具体分析，这是正确认识事物和解决矛盾的关键，B正确。A讲普遍性与特殊性的联系，C讲主要矛盾，D讲发展道路，均与题意不符。"},{"id":"gk-2025-22","stem":"改革开放以来，我国不断调整和完善所有制结构、分配制度等，使之与生产力发展水平相适应，推动了经济社会持续发展。这表明：","options":["生产关系一定要适合生产力状况，这是一条不以人的意志为转移的客观规律","上层建筑的性质决定经济基础的性质","生产力可以脱离生产关系而独立发展","社会意识对社会存在起决定作用"],"answer":0,"explain":"所有制结构、分配制度属于生产关系范畴，调整它们以适合生产力发展水平，正体现了生产关系一定要适合生产力状况的规律，A正确。经济基础决定上层建筑，B因果颠倒；生产力与生产关系相互联结，C割裂了二者关系；社会存在决定社会意识，D表述错误。"},{"id":"gk-2025-23","stem":"新发展理念是我国现阶段发展的指挥棒。下列关于新发展理念的说法正确的是：","options":["创新是引领发展的第一动力","协调发展注重解决的是社会公平正义问题","绿色发展注重解决的是发展内外联动问题","共享发展注重解决的是人与自然和谐共生问题"],"answer":0,"explain":"新发展理念中，创新是引领发展的第一动力，A正确。协调注重解决发展不平衡问题，开放注重解决发展内外联动问题，绿色注重解决人与自然和谐共生问题，共享注重解决社会公平正义问题，B、C、D三项把各理念所对应的问题相互混淆。"}]}]},{"id":"gk-sl-2023","title":"2023年国家公务员录用考试《申论》（副省级·模拟卷）","region":"全国","examType":"国考","subject":"申论","year":2023,"duration":180,"totalScore":100,"kind":"essay","note":"本卷为依据历年真题题型结构编写的原创模拟题，非官方真题原文，仅供练习。","materialTitle":"给定资料","material":"给定资料1\n“上面千条线，下面一根针。”A市B区C街道党工委书记老周翻了翻手机：一个月里他加入了七个工作群，收到各类通知上百条，填报的表格二十多张，其中不少内容彼此重复。社区干部小李说，有的部门上午发通知、下午就要数据，“我们一半时间在填表、拍照、留痕，真正下网格的时间被挤掉了”。区里曾组织一次集中检查，一周之内三个部门分别到同一个社区查看同一项工作，“看的是同一本台账，问的是同一批人”。有的应用软件要求每天打卡学习、上传照片，不完成就通报；有的创建工作把“是否建了微信群”当作考核指标，基层为了留痕只能“拍照—上传—再拍照”。有的社区门口挂了十几块牌子，每块牌子都对应一项考核，群众来办事却不知道该找谁。老周坦言，减负不是简单地少开几次会、少发几份文件，而是要把基层从“围着报表转”的状态里解放出来，把精力用在解决群众的实际问题上。去年以来，B区推行基层事务准入清单，凡未列入清单的事项一律不得随意下派，同时压减报表、合并考核，让街道干部每周至少有两个半天沉到网格里。\n\n给定资料2\n在A市政务服务中心，“一网通办”让不少企业和群众感受到了变化：过去开办一家小餐馆要跑五个窗口、交三套材料，如今线上一次填报、后台并联审批，半天就能拿到证照。中心负责人说，改革的着力点不只在“上网”，更在于把部门之间的壁垒打通，把“群众跑”变成“数据跑”。可六十五岁的王阿姨却犯了难：手机上要人脸识别、要上传材料，她试了几次都没成功，只好跑到大厅求助。窗口工作人员帮她办完后说，像王阿姨这样的老人每天都有十多位。有的老年人不会用自助机，有的听不清叫号，有的担心“手机点错了钱就没了”。有企业反映，个别事项线上提交后仍要再跑一趟窗口交纸质件，线上线下“两张皮”，便利度打了折扣。中心随后设立了“办不成事”反映窗口，组建帮办代办队伍，保留人工服务通道，还为行动不便的群众提供上门服务。一位干部说，“一网通办”不是把所有人都赶到线上，而是让愿意上网的网上办、习惯上门的有人帮。\n\n给定资料3\nD街道E社区是一个有着三十多年房龄的老小区，去年完成了改造：路面平整了，管线入地了，还新增了停车位和小广场。可好景不长，新装的健身器材坏了没人修，楼道里的杂物又堆了起来，物业费收缴率也不高。居民张大爷说，“改造是好事，可没人管，过两年又得变回去”。社区党组织随后牵头成立居民议事会，把小区党员、楼栋长、物业负责人和居民代表请到一起，围绕“停车怎么管、维修谁出钱、公共空间怎么用”一连议了五次，最终商定由物业负责日常保洁维修，居民按楼栋轮值参与巡查，小区公共收益优先用于设施维护。社区还把议事规则、经费收支贴在楼道口，“大家的钱怎么花，大家心里要有数”。有居民说，过去社区定了事，我们事后才知道；现在议过的事，我们心里有底。几个月下来，主动报修的居民多了，乱堆乱放的少了。社区书记说，社区治理不能只靠“政府端菜”，更要让群众“点菜”，把“我要管”变成“我们一起管”。\n\n给定资料4\nF区把矛盾纠纷化解作为社会治理的基础工程，建成一站式综治中心，法院、司法、信访、人社等部门集中入驻，群众“只进一扇门、最多跑一地”。前不久，某小区因楼上漏水引发两户居民争执，双方情绪激动，多次报警。综治中心启动“吹哨报到”，组织社区民警、司法所调解员、物业人员和楼栋长共同上门，既讲法律，也讲邻里情理，最终促成和解。中心还培育了以退休法官、热心乡贤为代表的调解队伍，把调解室开到了菜市场旁边、开到了村口。但运行中也暴露出一些问题：有的调解员凭经验办事，对法律法规和调解程序不够熟悉；有的部门“哨响人不到”，把调解责任一股脑推给社区；调解达成的协议缺乏后续跟踪，个别纠纷“调而不解”、反复升级；基层调解力量偏少，一人身兼多职，遇到复杂纠纷常常力不从心。还有当事人对调解结果不满意，却不知道还能通过哪些渠道继续解决。\n\n给定资料5\nG市快递员小陈每天送件三百多件，最发愁的是“没地方歇脚、没地方吃饭、手机没电”。去年，市里在商圈、社区、加油站建起一批“暖蜂驿站”，提供饮水、充电、热饭、休息和应急药品，还配了微波炉和雨具。小陈说，驿站不大，但让人心里暖和。除驿站之外，G市推动快递、外卖等新就业形态劳动者参加职业伤害保障，在医院开通绿色通道，在社区组建“骑手志愿服务队”，聘请骑手担任兼职网格员——他们每天走街串巷，最能发现井盖缺失、路灯不亮、独居老人无人照料等问题。外卖骑手小刘就曾第一时间上报一处燃气泄漏隐患，避免了事故发生。不过，服务也还有欠缺：有的驿站位置偏远、开放时间与骑手作业时间错开；有的骑手进小区送货时常被门禁挡住，与物业时有摩擦；一些骑手对参保政策不了解，担心“交了钱用不上”。市里一位干部说，服务新就业形态劳动者不能只停留在送清凉、送温暖，更要在制度上给他们稳定的预期。\n\n给定资料6\nH市推进公共服务均等化，思路是把优质资源“沉下去”。市里组建医共体，市医院专家定期到乡镇卫生院坐诊、带教，村民在镇上就能做检查，远程会诊把影像传给市里医生看；教育上推行城乡学校结对，城区教师到乡村学校交流任教，乡村学校开齐了音乐、体育、科学课；对偏远村庄，开通“流动服务车”，送医送药、代办证照、代购农资，每月定时进村。一位乡镇卫生院院长说，过去群众“小病拖、大病扛”，现在愿意在镇上看了。市里在总结时提出：公共服务供给不能满足于“有没有”，更要追求“好不好、准不准”；既要有政府主导的普惠性供给，也要善于引入社会力量和市场机制；既要用好数字技术，也要为老年人、残疾人等群体留好人工通道。也有群众提出，好政策贵在长期坚持，最怕“一阵风”，热热闹闹开头、悄无声息收场。有同志说，公共服务没有最好，只有更好，治理的温度，就藏在群众每天的柴米油盐里。","questions":[{"id":"gk-sl-2023-1","stem":"根据给定资料1~3，概括当前基层治理与公共服务供给中存在的主要问题。\n要求：全面、准确、条理清晰，分条作答；不超过250字。（15分）","limit":250,"score":15,"answer":"【参考要点】\n1.基层负担偏重。工作群、通知和报表繁多且重复，检查考核多头分散、重痕迹轻实效，挤占干部下沉服务群众的时间。\n2.存在“数字鸿沟”。线上流程和自助设备对老年人不友好，人工窗口、帮办代办等兜底服务不足，习惯把群众“赶到线上”。\n3.重建设轻管护。老旧小区改造后设施损坏无人修、公共空间被占用、物业费收缴难，缺乏长效管护机制。\n4.群众参与不足。社区事务主要靠干部和物业推动，居民主动性不高，缺少稳定的议事协商和轮值参与机制。\n5.治理方式不够精细。部门之间重复检查、各自为政，工作“一刀切”，忽视不同群体的差异化需求。\n\n【评分参考】\n本题15分，按点赋分，答出5个要点即可得满分，每点3分；要点须出自给定资料1~3，同义表述、合并作答均可。分条书写、概括准确、语言简洁可得结构分。\n常见失分：只堆砌现象不作概括提炼；脱离资料凭空发挥；大段照抄原文；超出规定字数或要点遗漏。"},{"id":"gk-sl-2023-2","stem":"给定资料3中提到：社区治理不能只靠“政府端菜”，更要让群众“点菜”。请结合给定资料，谈谈你对这句话的理解。\n要求：观点明确，分析透彻，条理清晰；不超过300字。（15分）","limit":300,"score":15,"answer":"【参考要点】\n这句话揭示了社区治理理念的转变：“政府端菜”指政府单方面决定服务内容，“群众点菜”指由群众按自身需求提出并参与决定，实质是从“替民做主”转向“由民做主”。\n“端菜”式供给虽然投入不少，却容易供需错位。E社区改造完成后健身器材无人修、楼道杂物回潮、物业费难收，正说明仅靠政府单向投入难以持久。“点菜”则把群众从旁观者变成参与者：居民议事会围绕停车管理、维修出资、公共空间使用反复商议，商定物业负责保洁维修、居民按楼栋轮值巡查、公共收益优先用于设施维护，并公开议事规则和收支，群众知情、参与之后，认同感和主动性明显增强。\n因此，社区治理要以群众满意为出发点，搭好议事协商平台，把决策权、参与权、监督权交给群众，实现政府治理与居民自治良性互动、共建共治共享。\n\n【评分参考】\n本题15分。解释含义4分，需点明“端菜”与“点菜”的区别及理念转变；结合资料分析7分，要求正反对比、举例贴切、分析到位；结论升华4分，落到群众主体地位和共建共治共享。\n常见失分：只作字面解释不作分析；脱离资料空谈理论；写成对策罗列，缺少“是什么—为什么—怎么办”的逻辑；超出字数。"},{"id":"gk-sl-2023-3","stem":"假如你是G市“暖蜂行动”工作专班的工作人员，请根据给定资料5，就G市服务新就业形态劳动者的有关情况写一份工作简报，报市领导参阅。\n要求：紧扣资料，内容具体，条理清晰，语言流畅；不超过500字。（20分）","limit":500,"score":20,"answer":"【参考要点】\n关于G市服务新就业形态劳动者有关情况的简报\n\n一、基本情况\nG市聚焦快递员、外卖骑手等新就业形态劳动者的急难愁盼，从歇脚、保障、融入三方面着手，让劳动者感受到城市温度。\n\n二、主要做法\n1.建强服务阵地。在商圈、社区、加油站建设“暖蜂驿站”，提供饮水、充电、热饭、休息和应急药品，配备微波炉、雨具等设施。\n2.强化权益保障。推动新就业形态劳动者参加职业伤害保障，在医院开通就医绿色通道。\n3.引导融入治理。组建“骑手志愿服务队”，聘请骑手担任兼职网格员，发挥其走街串巷优势，及时上报井盖缺失、路灯不亮、独居老人无人照料等问题，有骑手第一时间上报燃气泄漏隐患。\n\n三、存在不足\n一是部分驿站位置偏远，开放时间与骑手作业时间错开；二是骑手进小区送货时常被门禁阻挡，与物业存在摩擦；三是部分骑手不了解参保政策，顾虑“交了钱用不上”。\n\n四、下步考虑\n优化驿站布局和开放时段；推动社区、物业与平台协商，为骑手进出提供便利；加强政策宣传解读，用身边事例讲清保障待遇，提高参保意愿。\n\n【评分参考】\n本题20分。格式5分：有标题、分条列项、符合简报体例，无称谓落款不扣分。内容12分：做法三点、不足和下步考虑各一至两点，每点2分左右，须源于给定资料5。语言3分：简洁规范、字数达标。\n常见失分：写成议论文或经验总结；只写做法不提问题和对策；大段照抄原文；忽略简报体例和报送对象；明显超出字数。"},{"id":"gk-sl-2023-4","stem":"针对给定资料4中F区矛盾纠纷多元化解工作存在的问题，请提出改进建议。\n要求：紧扣资料，措施具体可行、针对性强，条理清晰；不超过400字。（15分）","limit":400,"score":15,"answer":"【参考要点】\n1.提升调解队伍专业化水平。吸纳法官、律师、行业专家等加入调解队伍，定期开展法律知识和调解技能培训，明确调解流程与文书规范，实行持证上岗和考核管理。\n2.压实部门报到责任。细化“吹哨报到”事项清单，明确各类纠纷由谁牵头、何时到场，对“哨响人不到”的部门予以通报问责，不得把责任简单推给社区。\n3.健全协议跟踪机制。对调解协议登记建档，明确履行期限和责任人，到期回访；对拒不履行的，及时引导当事人申请司法确认或依法起诉，防止“调而不解”。\n4.充实基层调解力量。通过政府购买服务、设置公益性岗位等方式配备专职调解员，落实补贴和奖励，减轻一人多职压力，对复杂纠纷组建专班攻坚。\n5.加强源头预防。发挥网格员、楼栋长作用，常态化排查矛盾隐患，把调解与普法宣传、心理疏导结合起来，力争把纠纷化解在萌芽状态。\n\n【评分参考】\n本题15分。按点赋分，答出4~5条即可得满分，每条3分左右；建议须与给定资料4的问题一一对应，具体可行、责任明确。\n常见失分：脱离资料自说自话；只表态不落实，如“提高认识”“加强重视”等空话；建议与问题不对应；超出字数。"},{"id":"gk-sl-2023-5","stem":"给定资料6中提到：“公共服务没有最好，只有更好，治理的温度，就藏在群众每天的柴米油盐里。”请结合给定资料，联系实际，自拟标题，写一篇文章。\n要求：（1）观点明确，见解深刻；（2）内容充实，结构完整；（3）语言流畅，书写工整；（4）不拘泥于给定资料，不得抄袭给定资料；（5）1000~1200字。（35分）","limit":1200,"min":1000,"score":35,"answer":"【参考范文】\n\n让治理的温度抵达柴米油盐\n\n公共服务的成色，不在汇报材料的字数里，而在群众的日常感受中。办事少跑一趟路、社区多一张歇脚的长椅、老人看病不必远行几十公里，这些细碎的体验，是治理水平最真实的刻度。基层治理现代化，归根结底要让人被看见、被体谅、被成全，让治理的温度抵达柴米油盐。\n\n让治理有温度，先要把基层从报表和考核中解放出来。C街道干部一周之内被三个部门查看同一本台账，填表、拍照、留痕占去大半时间，真正下网格的脚步就慢了。减负不是减担当，而是把干部的精力从“围着报表转”转到“围着群众转”。B区推行基层事务准入清单，未列入清单的事项不得随意下派，同时压减报表、合并考核，让干部每周至少有两个半天沉到网格，正是把“针”用得其所。干部的时间是有限资源，减掉一分无谓消耗，就能多一分走村入户的耐心。可见，为基层松绑，表面上是减少任务，实质上是把有限的人力还给群众。\n\n让治理有温度，要在共建共治中把群众请上“主位”。E社区改造后设施损坏无人维修、杂物回潮、物业费难收，症结在于“干部干、群众看”。居民议事会成立后，党员、楼栋长、物业和居民代表围绕停车、维修、公共空间使用连议五次，商定物业负责日常维护、居民按楼栋轮值巡查、公共收益优先用于设施维护，还把规则和收支贴在楼道口。群众知情了、参与了，才会把小区的事当成自己的事。治理不是替群众安排好一切，而是搭好台子让群众唱戏，把“我要管”变成“我们一起管”。\n\n让治理有温度，还要在精准供给中把服务做到心坎上。王阿姨用不好手机，并非抗拒新技术，而是需要有人搭把手；政务服务中心保留人工通道、组织帮办代办，才是真正的“一网通办”。快递员小陈在“暖蜂驿站”里喝上一口热水，骑车送件的间隙有了歇脚之处；偏远村庄的“流动服务车”每月进村送医送药，免去老人奔波之苦。这些做法看似不大，却都对准了具体的人、具体的难处。公共服务不能满足于“有没有”，更要追问“好不好、准不准”，用差异化、精细化的供给回应多样化的需求。服务多走一步，群众就少跑一趟，暖意正是在这些不起眼处积少成多。\n\n“治大国若烹小鲜。”柴米油盐看似琐碎，却是群众生活的全部重量。让治理有温度，既要有沉到一线的力量，也要有群众参与的热情，更要有精准供给的本领。唯有把每一件“小事”办好办实，让群众在家门口感受到便利与尊重，治理的现代化才有最坚实的落点。\n\n【写作提示】\n1.立意角度：围绕基层治理现代化与公共服务供给，抓住“温度”与“日常”两个关键词，落脚到以人民为中心。可从“减负增效、共建共治、精准供给”三个维度展开，也可从“下沉力量、数字包容、群众参与”切入，关键是把宏大命题落到群众的日常体验上。\n2.结构安排：建议采用“总—分—总”。开头由金句或生活细节引出总论点；主体设三个分论点，每段按“观点句＋资料例证＋简要分析＋结论”展开，结合而不拘泥于给定资料，可补充身边鲜活事例；结尾回扣主题，升华到治理现代化的价值追求。\n3.注意事项：标题要准确凝练，避免“论基层治理”一类空泛表述；分论点句式力求整齐，语言平实有力；切忌大段照抄给定资料；字数控制在1000~1200字，卷面工整。"}]},{"id":"gk-sl-2024","title":"2024年国家公务员录用考试《申论》（副省级·模拟卷）","region":"全国","examType":"国考","subject":"申论","year":2024,"duration":180,"totalScore":100,"kind":"essay","note":"本卷为依据历年真题题型结构编写的原创模拟题，非官方真题原文，仅供练习。","materialTitle":"给定资料","material":"给定资料1\nA市近年来把“一网通办”作为数字政府建设的突破口，将分散在各部门的政务服务事项集中到一个平台上，群众和企业登录一个入口就能办理多数事项。市政务服务管理局负责人介绍，平台上线以来，网上可办事项明显增加，不少事项实现了“最多跑一次”甚至“一次不用跑”。开小吃店的个体户王大姐说，过去办证要跑好几个部门，材料准备一大摞，现在网上填一次表，营业执照和食品经营许可证一起就办下来了。\n\n但记者走访也发现一些问题。有的部门业务系统与市级平台没有真正打通，数据靠人工导出导入，群众在窗口仍然要重复提交身份证、房产证明等材料；同一事项在不同城区要求不一，A区认可的材料B区不认，企业跨区办事还要“重新来一遍”；部分事项虽然挂到了网上，实际只是“能看不能办”，点击办理就提示“请到线下窗口”；办事指南术语多、条件绕，群众看完仍不清楚该带什么、找谁办。一位窗口工作人员坦言，平台建起来了，但“数据通不通、标准齐不齐，不是我们一个部门能解决的”。有企业反映，办理工程建设项目审批时，同一份图纸要在几个系统分别上传，前后跑了一个多月才办完；还有企业反映，部分事项网上提交后仍需到窗口核验原件，来回跑了两趟。\n\n给定资料2\nB区民营中小企业集中。为帮助企业渡过难关，区里推行“企业服务专员”制度，为规上企业和重点培育企业配备专员；同时上线惠企政策“免申即享”模块，符合条件的企业不用申报，资金直接到账。一家小微企业负责人说，去年有一笔稳岗补贴没打申请就收到了，“确实省事”。\n\n不过，也有企业反映，政策发布渠道分散，有的在部门网站、有的在公众号，企业“找不到、看不懂、算不清”；一些奖补政策申报材料多、周期长，材料交上去迟迟没有回音；遇到涉及多个部门的问题，往往要一家一家跑，“都在管，又都管不全”。区里曾想推动企业开办、员工招聘、不动产登记等“一件事一次办”，但因为涉及多个条线，责任划分、系统对接、数据共享迟迟难以落地。有干部说，跨部门协同最难的不是技术，而是“谁牵头、谁配合、数据给不给”。一些园区企业还反映，涉企检查频次偏高，不同部门在不同时间上门，企业不得不安排专人陪检、疲于应付。\n\n给定资料3\nC局承担市场监管职责。近年来，C局推行“双随机、一公开”抽查，实行信用风险分级分类监管，对信用好、风险低的企业减少检查频次；同时制定轻微违法行为不予处罚清单，对首次、轻微且及时改正的行为依法免予处罚。一家餐饮店因为公示牌摆放位置不对被提醒，店主说：“以前一上来就罚款，现在先指导整改，心里舒服多了。”\n\n与此同时，一些问题也浮现出来。有的基层执法人员担心“不罚就是不作为”，免罚清单落地打了折扣；企业信用信息归集不完整，有的失信记录来自不同部门、标准不一，企业想修复信用不知该找谁；个别地方把联合惩戒用得过宽，一家企业在一个领域失信，招投标、融资、评优处处受限，“一处失信、处处受限”变成了“一处失信、处处受困”。有的企业反映，信用修复要在不同网站分别提交材料，流程复杂，修复结果也不能及时同步，影响了正常经营。C局一位工作人员说，监管不是把企业管死，服务也不是替企业包办，关键要让守信者一路绿灯、让失信者受到应有的约束。\n\n给定资料4\n政务数据共享在带来便利的同时，也带来了安全隐忧。A市一位数据管理人员介绍，各部门数据归集到统一平台后，谁在什么情况下可以调用、调用之后如何留痕，制度还不够细。个别单位为了“方便”，把含有身份证号、手机号的数据表格通过社交软件层层转发；有的把系统运维外包给第三方公司，对驻场人员的管理偏松。一位企业负责人反映，刚在某部门登记完信息，很快就接到推销电话，“不知道信息是从哪儿漏出去的”。有基层干部反映，数据填报系统多头并存，同一个指标要在不同平台各填一遍，加班加点成了常态。\n\n与此同时，基层也存在重复填报的现象。同一组数据，不同部门、不同层级要反复报，口径还不一致；有的报表要求每周报一次，内容大同小异。一位社区工作人员说，光是填表就占了不少时间，“真正下网格、访居民的时间被挤掉了”。有专家提出，数据共享不能只讲“共享”不讲“安全”，也不能只讲“安全”把数据锁死，要在制度、技术、责任上同时用力。\n\n给定资料5\n数字政府建设让办事更便捷，但对部分群体来说，一道“数字鸿沟”也悄然出现。A市一位七十多岁的老人想去医院看病，被告知要提前在手机上挂号，他不会操作，只好一大早赶到医院排队，号却已经挂完。有的政务服务大厅推行“扫码取号”，老年人找不到入口，只能一遍遍问工作人员。\n\n类似情况还出现在小微企业和个体工商户身上。有的经营者年纪偏大、不会用电脑，电子营业执照、电子发票、网上年报常常要请人代劳；有的地方一个部门一个App、一个平台一套账号，群众记不住密码；有的基层干部把“线上办”等同于“不用管”，线下窗口一减了之，帮办代办力量又没跟上。一位社区志愿者说，教老人用手机，最需要的是耐心，“有时候教三遍才会，第四遍又忘了”。有的社区尝试开设“手机课堂”，请大学生志愿者手把手教老年人使用政务App，很受欢迎。也有干部认为，数字化不能只图自己方便，要把“群众会不会用、方不方便”作为衡量标准。\n\n给定资料6\n在一次数字政府建设座谈会上，与会人员围绕如何把这项改革做深做实展开讨论。有人认为，数字政府建设不只是把线下搬到线上，更重要的是以数据共享和流程再造推动政府职能转变，让企业和群众办事更省心。有人提出，要处理好效率与安全的关系，既要让数据依法有序流动，也要守住个人信息保护和数据安全的底线。\n\n还有人强调，线上要快，线下要暖，不能因为推行数字化就取消必要的线下服务，要为老年人、残疾人等群体留出通道、配好帮办。有与会者提出，数字政府建设离不开懂业务、懂技术的复合型人才，也离不开基层干部数字素养的提升。会议形成共识：数字政府建设的出发点和落脚点是便民利企，要坚持技术赋能与制度创新并重、线上服务与线下兜底并行，把“跑一次”“不用跑”的便利真正送到群众和企业身边。","questions":[{"id":"gk-sl-2024-1","stem":"根据给定资料1~3，概括当前A市推进数字政府建设、优化营商环境中存在的主要问题。\n要求：全面、准确，条理清晰，分条作答；不超过250字。（15分）","limit":250,"score":15,"answer":"【参考要点】\n1.数据共享不畅。部门业务系统与市级平台未真正打通，靠人工导入导出，材料重复提交，形成“信息孤岛”。\n2.标准不统一。同一事项各区要求不一、互不认可，跨区办事要重新办理；部分事项“能看不能办”，办事指南术语多、条件绕。\n3.政策服务不优。惠企政策发布渠道分散，企业找不到、看不懂、算不清；申报材料多、周期长、反馈慢。\n4.跨部门协同不力。多部门问题互相推诿，“都在管又都管不全”，牵头责任不清，“一件事一次办”难落地。\n5.监管方式粗放。免罚清单落地打折扣；信用信息归集不全、修复渠道不畅；联合惩戒用得过宽，失信企业处处受困。\n\n【评分参考】\n本题15分，按点赋分。答出以上5个要点即可得满分，每点3分；要点须源于给定资料1~3，同义表述、合并作答均可。分条书写、有概括词、语言简洁可得结构分。\n常见失分：只罗列零散现象不作提炼；把对策混入问题作答；脱离资料凭空发挥；大段照抄原文；超出250字或要点遗漏。"},{"id":"gk-sl-2024-2","stem":"给定资料3中提到：“监管不是把企业管死，服务也不是替企业包办，关键要让守信者一路绿灯、让失信者受到应有的约束。”请结合给定资料3，谈谈你对这句话的理解。\n要求：观点明确，分析透彻，条理清晰；不超过300字。（15分）","limit":300,"score":15,"answer":"【参考要点】\n1.这句话讲的是政府与市场的关系，核心是监管要有力度、有精度、有温度，做到宽严相济、罚当其过。\n2.“不是把企业管死”，指监管不能简单粗暴、“一刀切”。C局推行“双随机、一公开”和信用分级分类监管，对信用好、风险低的企业减少检查；制定轻微违法不予处罚清单，首次、轻微且及时改正的依法免罚，给了企业纠错空间，有利于激发活力。\n3.“不是替企业包办”，指服务不能越位代替企业作决定，政府重在优化环境、制定规则、提供便利，企业才是经营主体，不能以服务之名行干预之实。\n4.“守信者一路绿灯、失信者受到约束”，强调以信用为基础实施差异化监管：对守信企业无事不扰、办事便利，对失信行为依法惩戒。当前免罚清单落地打折扣、信用信息归集不全、信用修复渠道不畅、联合惩戒泛化等问题，恰恰背离了这一要求。\n5.因此，要完善信用信息归集与修复机制，规范失信认定和惩戒范围，让监管既守住底线，又不误伤守法经营的企业。\n\n【评分参考】\n本题15分。解释句意、点明“监管有度、服务不越位、信用差异化监管”得5分；结合资料3中分级分类监管、免罚清单、信用修复、惩戒泛化等事例分析得6分；提出对策性或结论性认识得4分。\n常见失分：脱离资料空谈政府与市场关系；只解释不分析；只写“要包容审慎监管”一句反复展开；观点模糊、无条理；超出300字。"},{"id":"gk-sl-2024-3","stem":"给定资料5反映了部分老年人、小微企业在政务服务数字化过程中遇到的困难。假如你是A市政务服务管理局的工作人员，请根据给定资料5，就帮助群众跨越“数字鸿沟”拟写一份工作方案提纲，供局领导审阅。\n要求：（1）紧扣资料，内容具体；（2）条理清晰，措施可行，有可操作性；（3）不超过500字。（20分）","limit":500,"score":20,"answer":"【参考要点】\n标题：关于帮助群众跨越“数字鸿沟”的工作方案（提纲）\n\n一、工作目标\n坚持线上服务与线下兜底并行，解决老年人、残疾人及小微企业在办事中“不会用、用不好”的问题，让数字化便利覆盖各类群体。\n\n二、重点任务\n1.保留线下通道。政务服务大厅不搞“一刀切”取消人工窗口，保留现金缴费、现场取号等传统方式，设置“无健康码”“无手机”绿色通道。\n2.配强帮办代办。在大厅、社区服务点安排帮办员和志愿者，为老年人提供全程陪同、代填代报服务，做到“进门有人问、办事有人帮”。\n3.推进适老化改造。优化平台界面，采用大字体、大图标、语音播报，精简账号和验证环节，推行“一次认证、多端通用”，减少重复注册。\n4.开展数字助老服务。依托社区、老年大学开设培训，编发图文版操作手册，组织志愿者“一对一”上门教学。\n5.优化企业服务。为小微企业和个体工商户提供电子证照、电子发票等操作指引和上门辅导，推广“免申即享”，减少主动申报负担。\n\n三、保障措施\n加强人员培训与考核，将帮办代办、适老化改造纳入政务服务考核。\n\n【评分参考】\n本题20分。格式5分：有标题、符合方案提纲体例、层次清晰。内容13分：目标、重点任务、保障措施齐全，任务部分答出4~5条且源于资料5，每条2~3分。语言2分：条理清楚、语句通顺、字数达标。\n常见失分：写成议论文或情况汇报；只谈意义不提措施；措施空泛无操作性、脱离资料；遗漏线下兜底和帮办代办等关键点；严重超字数。"},{"id":"gk-sl-2024-4","stem":"给定资料2中B区中小企业在办事和享受政策过程中遇到了一些困难。假如你是B区营商环境建设办公室的工作人员，请根据给定资料2，就进一步优化服务、提升企业获得感提出对策建议。\n要求：（1）紧扣资料，针对性强；（2）措施具体，切实可行；（3）分条作答；不超过400字。（15分）","limit":400,"score":15,"answer":"【参考要点】\n1.集中政策发布。建设惠企政策统一发布平台，整合部门网站、公众号等渠道，按行业、规模分类归集，推行政策“一网可查”。\n2.推动政策易懂可算。配套发布政策解读、申报指南和案例，开发智能匹配、免申即享功能，让企业知道“能不能享、能享多少、怎么享”。\n3.简化申报兑现。减少申报材料和环节，实行告知承诺、容缺受理，压缩审批和兑付周期，对已受理事项明确时限并及时反馈进度。\n4.深化“一件事一次办”。围绕企业开办、员工招聘、不动产登记等高频事项，由区里明确牵头部门，梳理再造流程，推动系统对接、数据共享，实现“一次告知、一表申请、一窗受理”。\n5.健全协同机制。建立跨部门会商和首问负责、限时办结制度，明确“谁牵头、谁配合、数据给不给”，对推诿扯皮严肃问责。\n6.强化服务专员作用。扩大企业服务专员覆盖面，向中小微企业延伸，提供政策辅导、问题协调等常态化服务，定期回访了解诉求。\n\n【评分参考】\n本题15分。答出5条左右对策即可得满分，每条3分，须针对资料2中的问题且具体可行。对策与问题对应、有操作性、表达规范者得分高。\n常见失分：对策与问题脱节；只喊口号如“加强领导、提高认识”；照抄资料原文简单转述；不分条、条理混乱；超出400字。"},{"id":"gk-sl-2024-5","stem":"给定资料6中提到：“数字政府建设不只是把线下搬到线上，更重要的是以数据共享和流程再造推动政府职能转变。”请结合给定资料，联系实际，自拟标题，写一篇文章。\n要求：（1）观点明确，见解深刻；（2）内容充实，结构完整；（3）语言流畅，书写工整；（4）不拘泥于给定资料，不得抄袭给定资料；（5）1000~1200字。（35分）","limit":1200,"min":1000,"score":35,"answer":"【参考范文】\n\n以数字之“智” 提营商之“优”\n\n从“跑多个部门”到“进一扇门”，从“材料一摞”到“填一次表”，数字政府建设正在重塑政府与市场、政府与群众的关系。A市的实践表明，数字化不只是把窗口搬到网上，更是以数据共享、流程再造推动政府职能转变。当前，优化营商环境已进入“深水区”，唯有以数字政府建设为抓手，让数据多跑路、让服务更精准、让监管更有度，才能把便利真正送到企业群众身边，为高质量发展注入持久动力。\n\n让数据“通”起来，是优化营商环境的先手棋。数据壁垒是办事慢、材料多的根源。A市有的部门系统与市级平台没有真正打通，群众不得不重复提交身份证、房产证明；同一事项在不同城区要求不一，企业跨区办事还要“重新来一遍”。数据不共享，流程就难再造。要下决心打破部门本位，推动系统互联互通、数据按需归集，以标准化推动办事指南、材料清单、审核规则统一，让“一份材料、一次提交、多方复用”成为常态。\n\n让服务“准”起来，是提升企业获得感的关键。政策找不到、看不懂、算不清，是企业反映最集中的痛点。B区推行“免申即享”，让符合条件的企业不用申报就能拿到补贴，正是以数据比对代替企业跑腿的有益探索。优化营商环境，不能满足于“有政策”，更要追求“好兑现”。要把惠企政策集中发布、智能匹配、精准推送；要以“一件事一次办”为牵引，推动跨部门协同，明确牵头责任，把企业眼中的“一堆事”变成政府内部的“一件事”。\n\n让监管“度”起来，是激发市场活力的保障。监管不是把企业管死，服务也不是替企业包办。C局实行信用分级分类监管、制定轻微违法免罚清单，让守信者少被打扰、让初犯者有机会改正，体现了包容审慎的态度；但免罚清单落地打折扣、信用信息归集不全、联合惩戒泛化，也可能让企业“一处失信、处处受困”。监管要有力度，更要有精度和温度。要完善信用修复渠道，规范失信认定与惩戒范围，做到宽严相济、罚当其过。\n\n让线上线下“暖”起来，是数字政府的底色。技术再先进，也不能把人落下。老年人挂不上号、不会扫码取号，小微企业主记不住一摞账号密码，都在提醒我们：数字化不能只图管理者方便。要坚持线上服务与线下兜底并行，保留必要的人工窗口和帮办代办力量，推进适老化改造，让“网上办”与“有人帮”并行不悖。同时，数据大量归集也带来安全隐忧，必须厘清调用权限、规范外包管理，把个人信息保护和数据安全的底线守牢。\n\n营商环境没有最好，只有更好。数字政府建设是一场刀刃向内的改革，改的是流程，破的是壁垒，暖的是人心。以数据共享打通堵点，以精准服务回应期盼，以有度监管呵护活力，以线上线下协同守住温度，我们就能让“跑一次”“不用跑”成为常态，让各类经营主体安心经营、放手发展，为高质量发展积蓄深厚底气。\n\n【写作提示】\n1.立意角度：围绕“数字政府建设与营商环境优化”的关系立意，核心是“数字化不止于技术，更在于职能转变与便民利企”。可从“数据共享、服务精准、监管有度、线上线下协同与安全”四个维度展开，也可从“效率与安全、线上与线下、监管与服务”三对关系切入。关键是把数字政府建设落到优化营商环境、增进民生福祉上。\n2.结构安排：建议采用“总—分—总”。开头由办事变化的场景或金句引出总论点；主体设三至四个分论点，每段按“观点句+资料例证+简要分析+对策结论”展开，注意结合而不拘泥于给定资料，可补充身边的政务服务事例；结尾回扣主题，升华到政府治理现代化与高质量发展。\n3.注意事项：标题要准确凝练，避免“论数字政府”一类空泛表述；分论点句式尽量整齐，语言平实有力；切忌大段照抄给定资料；字数控制在1000~1200字，卷面工整。"}]},{"id":"gk-sl-2025","title":"2025年国家公务员录用考试《申论》（副省级·模拟卷）","region":"全国","examType":"国考","subject":"申论","year":2025,"duration":180,"totalScore":100,"kind":"essay","note":"本卷为依据历年真题题型结构编写的原创模拟题，非官方真题原文，仅供练习。","materialTitle":"给定资料","material":"给定资料1\nA市是一座有着深厚文化底蕴的古城，拥有竹编、木雕、油纸伞、地方戏曲等多个传统技艺项目。近年来，市里对本地文化家底进行了全面摸排，登记在册的各级非物质文化遗产项目有数十项，各级代表性传承人上百人。但摸排也摸出了隐忧：部分传承人年事已高，最年轻的徒弟也已过不惑之年，个别技艺面临“人走艺绝”的境地；一些手艺人守着好手艺，产品却主要是当地日常用品，销路窄、价钱低，一年忙到头收入有限，年轻人不愿学。\n\n市非遗保护中心的工作人员说，过去我们习惯把老手艺当成“老物件”供起来，搞展览、上电视、进档案，热闹一阵就冷清了。有传承人直言：“手艺不是古董，放在玻璃柜里就死了。得有人用、有人买、有人学，手艺才能传下去。”近几年，市里支持部分传承人与职业院校、设计机构合作，把传统纹样、榫卯结构用到文具、家居用品上，一款改良竹编灯罩成了网上热销品；一位油纸伞传承人走进直播间讲傘面上的故事，订单排到了几个月后；“老戏新唱”把传统唱腔与现代舞美、短视频结合起来，在年轻人中意外走红。\n\n不过，热潮之下也有困惑。有的项目为了迎合市场，把工艺一减再减，用机器批量替代手工，产品便宜了，味道却淡了；有的传承人担心“改着改着就不是自己了”；也有干部认为，只要把项目报上去、牌子挂起来，就算完成任务。一位文化研究者提醒：非遗保护不是把它冻起来，也不是把它改头换面，而是要让它在当代生活中找到位置、生出活力。\n\n给定资料2\nB县老城区至今保留着成片的传统民居和历史街巷。青石板路、木格门窗、临河而建的老屋，构成了独特的风貌。当地干部说，这些房子大多建于几十年前，房龄长、砖木结构，有的已是危房；屋内脏乱差，没有独立厨卫，停车、充电、消防都成问题，年轻人大都搬去了新区，留下的多是老人，老街“越来越安静”。\n\n前些年，县里曾把沿街铺面统一对外招商，做小吃、卖纪念品，短时间内人气很旺。可没过多久，问题就来了：店主大多不是本地人，卖的货与这条街、这座城没什么关系，同质化严重，游客逛一条街就够了；铺租上涨，原住民陆续搬走，街巷里听不到乡音，也闻不到饭菜香，“古镇不是古镇，倒像一个布景”。这次教训让县里重新思考：老城的价值到底是什么？\n\n此后，县里调整思路，把“留人”放在首位：对危房进行原址修缮，保留原有格局和街巷肌理，先补齐地下管网、消防通道、公共厕所等基础配套；不搞整街搬迁，通过租金补贴、以奖代补等方式，鼓励原住民留下来，把自家小院改成茶室、书吧、手工作坊；同时组织居民成立老街议事会，改建方案、经营业态由大家商量着办。有居民说，现在孙子周末愿意回来了，老街又有了人气。但县里同志也坦言：老城保护投入大、周期长、见效慢，少数群众不大理解，觉得“房子旧了不如推倒重建”；财政压力不小，后续修缮、管护的钱从哪里来，还没有稳定的路子。\n\n给定资料3\nC镇近年来推进基层公共文化设施建设，各村陆续建起了文化礼堂、农家书屋、文体广场，有的还配了舞台和音响。硬件上了，但使用情况并不理想。镇文化站站长反映，有的村农家书屋的门常年锁着，书架上的书还是几年前配的，与村民种养、务工的实际需要对不上；有的文化礼堂一年就热闹几场，平时空着；有的地方送戏下乡、送电影下乡，来的人多是老人和孩子，年轻人兴趣不大。\n\n也有做得好的村子。D村把文化礼堂交给村里的文艺骨干和返乡大学生一起打理，建立了“文化能人库”，谁有本事谁上台：会唱戏的教唱戏，会写字的开书法班，会拍短视频的带着大家拍村史、拍农事。村里还把礼堂和红白事场地、议事场所合起来用，一年到头都有活动。村支书说：“文化设施不是摆着看的，关键得有人张罗、有人捧场。”E村则把村里的老祠堂修缮后用作村史馆和乡贤议事厅，把老照片、老农具、老族谱陈列出来，还组织老人给孩子讲村子的来龙去脉，不少在外打工的年轻人回乡后专程来看。\n\n镇里一位干部感慨：这些年我们送文化多、种文化少，配设施多、育队伍少。公共文化服务要送到群众心坎上，就要问一问群众到底想要什么，能不能自己办起来。\n\n给定资料4\nA市在推动文旅融合过程中，既有亮点，也有困惑。F镇把古村落里的老宅、祠堂、古道串成一线，不搞大拆大建，而是请本地老人当讲解员，讲家风家训、讲村落变迁，游客能跟着手艺人在门前打糍粑、做豆腐，还能住进改造后的农房，吃上家常饭。镇里同时统一了停车场、标识牌、公厕等配套，去年接待游客数量明显增长。\n\nG县则有另一种景象。看到邻县民俗体验项目火了，县里也照着仿建了一条民俗街，从外地采购同款灯笼、同款小吃、同款表演，开街两年来，旺季勉强维持，淡季冷冷清清；一处投资不小的文化产业园，因为缺乏运营团队、周边配套跟不上，招商不足，部分场馆长期闲置。当地干部反思：别人成功靠的是自己的文化底子，我们只学了“壳”，没学到“魂”。\n\n市文旅局同志分析，文旅融合要警惕“千村一面”。有的地方把老建筑刷得锃亮，把老手艺做成流水线上的商品，游客看一眼就走，走得也快；有的地方一拥而上搞项目，摊位、民宿迅速过剩，最后伤了农民积极性。他认为，文旅融合要算两笔账：一笔是文化账，看有没有把本地文化的精气神讲出来；一笔是长远账，看能不能让群众长期受益。文化走在前头，旅游才走得长远。\n\n给定资料5\n青少年是传统文化传承的希望所在。A市一所小学把剪纸、戏曲身段、传统节日等内容编成校本课程，每周一节，由本校老师和校外传承人共同授课；学校还开设了“非遗社团”，孩子们自己动手做香囊、扎灯笼，把作品摆进校园长廊。家长说，孩子回家会主动问起爷爷奶奶小时候的事，家里的老规矩也愿意听了。\n\n但也有学校遇到困难：校本课程缺少系统教材，师资不足，多靠一两位有热情的老师“撑着”；有的地方把传统文化教育做成一次性的参观、一台晚会，活动结束就没了下文；个别学校为完成考核任务，组织学生填表打卡、拍照片，家长有意见。一位中学老师认为，传统文化教育不能停在“认几个字、背几首诗”，更要让孩子明白这些文化从哪里来、与自己有什么关系。\n\n市里一位负责人说，传承不是一代人的事。要让传统文化在青少年心里扎根，需要学校、家庭、社会各尽所能：学校要把课上好，家庭要把日子过出味道，社会要把场所敞开。博物馆、图书馆、文化馆、老街区、老工坊，都可以是课堂。\n\n给定资料6\n在一次关于城乡文化建设的座谈会上，与会人员展开了讨论。\n\n有人认为，文化建设的最大误区是“重建设、轻运营”，钱花在了水泥和砖头上，却没有花在人、内容和机制上；场馆建起来了，没有人气，反而成了负担。\n\n有人提出，保护与利用不是对立的。老城区、老村落只有在使用中才能被发现价值、获得修缮的动力；把原住民都请出去，把生活场景都清空，留下的只是躯壳。\n\n也有人强调，文化传承必须“见人见物见生活”。传统技艺要走进当代生活，传统美德要融入日常言行，传统村落要留住烟火气；离开生活，文化就成了标本。\n\n还有人提醒，要防止两种倾向：一种是“僵化保护”，把文化当古董封存起来，老百姓碰不得、用不上；另一种是“过度开发”，把文化当噱头消费掉，讲不清来路，也留不下什么。\n\n会议形成共识：让中华优秀传统文化活起来、传下去，关键要处理好保护与利用、传承与创新、政府与群众的关系，既要守住根脉，也要融入时代；城乡文化建设要一体谋划，县城和乡村都要有书卷气、烟火气，让群众在身边就能感受到文化的温度。","questions":[{"id":"gk-sl-2025-1","stem":"根据给定资料1~3，概括当前A市及B县、C镇在传统文化保护和城乡文化建设中面临的主要问题。\n要求：全面、准确、条理清晰，分条作答；不超过250字。（15分）","limit":250,"score":15,"answer":"【参考要点】\n1.传承链条脆弱。传承人年龄偏大、后继乏人，个别技艺面临“人走艺绝”，年轻人不愿学。\n2.市场转化乏力。手艺人产品销路窄、价格低、收入有限，缺乏设计、营销和品牌支撑。\n3.保护理念偏差。习惯把老手艺当“老物件”供起来，重申报挂牌、轻活态传承；保护与利用关系认识不清。\n4.热情之下走偏。为迎合市场简化工艺、以机器批量替代手工，或改得失去原有特色。\n5.老城保护困难。房屋老旧、配套缺失、人口外流；早期商业化导致业态同质、原住民搬离；投入大、周期长、见效慢，财政与管护资金缺乏稳定来源，部分群众不理解。\n6.公共文化设施使用率低。书屋、礼堂常年闲置，图书与群众需求脱节，送文化多、种文化少，活动吸引力不足。\n\n【评分参考】\n本题15分，按点赋分。答出6个要点即可得满分，每点约2~3分；要点须来自给定资料1~3，同义表述、合并作答均可。分条书写、概括准确、语言简洁可得结构分。\n常见失分：只罗列现象不作概括；把资料中的做法、成绩误当作问题；脱离给定资料凭空发挥；要点交叉重复；超过规定字数。"},{"id":"gk-sl-2025-2","stem":"给定资料2中提到：“古镇不是古镇，倒像一个布景。”请根据给定资料2、给定资料4，谈谈你对这句话的理解。\n要求：观点明确，分析深入，条理清晰；不超过300字。（15分）","limit":300,"score":15,"answer":"【参考要点】\n1.点明实质。这句话批评的是一些地方在历史文化街区、古村落保护利用中“重商业、轻文化”，只留下建筑的壳，丢掉了生活与文化这个魂。\n2.分析表现。沿街铺面统一招商，店主以外来者为主，商品与本地文化无关、同质化严重；铺租上涨迫使原住民搬走，街巷失去乡音、炊烟和生活场景；盲目照搬外地模式，仿建民俗街、文化产业园，同款灯笼小吃表演，缺乏运营与配套，旺季勉强维持、淡季冷清，场馆闲置。\n3.指出危害。文化特色被消解，游客“看一眼就走”，难以持续；原住民利益受损、积极性受挫；投入大而收益短，伤了发展根基。\n4.得出结论。历史街区、古村落的价值在于真实的生活与独特的文化。应把“留人”放在首位，先补配套、修缮危房、保留街巷肌理，让原住民留下来、生活延续；同时深挖本地文化内涵，让文化走在前头，算好文化账和长远账，实现保护与利用相统一。\n\n【评分参考】\n本题15分。观点（3分）：准确点出实质，态度鲜明。分析（9分）：能结合给定资料2、4，说清表现、危害与成因，每层3分左右。结论（3分）：提出正确认识或改进方向。须立足给定资料，不得脱离材料空谈。\n常见失分：只复述原句不作解释；只谈危害不提对策结论；未结合给定资料4中民俗街、文化产业园等例证，分析单薄；写成对策题；超字数。"},{"id":"gk-sl-2025-3","stem":"假设你是C镇文化站的工作人员，根据给定资料3，就D村、E村管好用好公共文化设施的做法，写一份经验交流材料，供全镇各村参考。\n要求：紧扣资料，内容具体，条理清晰，语言流畅，有可操作性；不超过500字。（20分）","limit":500,"score":20,"answer":"【参考要点】\n标题：关于D村、E村管好用好公共文化设施的经验交流材料\n\n一、主要做法\n1.依靠群众办文化。D村把文化礼堂交给文艺骨干和返乡大学生共同打理，建立“文化能人库”，谁有本事谁上台，教唱戏、开书法班、拍村史短视频。\n2.一室多用提效率。把文化礼堂与红白事场地、村民议事场所合并使用，一年到头都有活动，避免设施空置。\n3.盘活老场所。E村把老祠堂修缮后用作村史馆和乡贤议事厅，陈列老照片、老农具、老族谱，延续村庄记忆。\n4.以故事聚人心。组织老人给孩子讲村子的来龙去脉，在外务工青年回乡后专程参观，增强认同感。\n\n二、经验启示\n1.转变思路。从“送文化”转向“种文化”，从“配设施”转向“育队伍”。\n2.问需于民。设施建什么、活动办什么，先问群众想要什么。\n3.培育队伍。发掘本村文化能人，培养返乡青年成为骨干，让村里的事村里人办。\n4.健全机制。明确管理责任人，把活动排进日常、纳入常态，做到门常开、人常在、活动常新。\n\n【评分参考】\n本题20分。格式4分：有标题，符合经验交流材料的文体和口吻，无称谓、落款不扣分。内容12分：做法4点、启示4点，每点约1.5分，须源于给定资料3。语言4分：条理清晰、语句通顺、字数达标。\n常见失分：写成议论文、工作总结或情况汇报；大段照抄原文；只写做法、不提启示；对策空泛、缺乏可操作性；明显超字数。"},{"id":"gk-sl-2025-4","stem":"给定资料6中座谈会提出，要防止“僵化保护”和“过度开发”两种倾向。请根据给定资料，就如何促进中华优秀传统文化活态传承、推动城乡文化建设提出对策建议。\n要求：紧扣资料，措施具体可行，针对性强，条理清晰；不超过400字。（15分）","limit":400,"score":15,"answer":"【参考要点】\n1.健全传承机制。建立传承人梯队和学徒培养制度，给予补助和荣誉激励，支持传承人进校园、进社区收徒传艺，破解后继乏人问题。\n2.推动融入生活。支持技艺与现代设计、文创产品、日常生活用品结合，开发实用新品；引导传承人用好直播、短视频等新渠道，拓展销路、提高收入。\n3.守住文化根脉。制定工艺和质量标准，明确哪些可创新、哪些须坚守，防止以机器批量替代手工、随意删减工序；坚持非遗项目真实性，反对改得面目全非。\n4.保护历史街区。坚持原址修缮、保留街巷肌理，先补齐管网、消防、停车等配套；通过租金补贴、以奖代补鼓励原住民留下，业态由居民议事会商量，避免同质化商业。\n5.提升公共文化服务。转变重建设轻运营的思路，一室多用、培育本土文化能人队伍，按需配书送戏，把祠堂、老宅等改造为村史馆、议事厅。\n6.深化文旅融合。立足本地文化特色编制规划，防止盲目仿建、千村一面；配强运营团队和配套设施，算好文化账和长远账，健全利益联结，让群众长期受益。\n7.稳定投入保障。建立财政支持、社会资本、集体收益相结合的多元投入机制，明确管护责任和资金渠道。\n\n【评分参考】\n本题15分，按点赋分。答出5~6个要点即可得满分，每点2~3分，要点须源于给定资料并具有可操作性。有总起句、分条表述、措施与问题对应的，可另给结构分。\n常见失分：对策与问题脱节；只喊口号、无可操作抓手；照抄原文；只答一个方面（如只谈旅游开发）；超出规定字数。"},{"id":"gk-sl-2025-5","stem":"给定资料6中提到：“让中华优秀传统文化活起来、传下去，既要守住根脉，也要融入时代。”请结合给定资料，联系实际，自拟标题，写一篇文章。\n要求：（1）观点明确，见解深刻；（2）内容充实，结构完整；（3）语言流畅，书写工整；（4）不拘泥于给定资料，不得抄袭给定资料；（5）1000~1200字。（35分）","limit":1200,"min":1000,"score":35,"answer":"【参考范文】\n\n守住根脉 融入时代\n——让中华优秀传统文化在城乡大地活起来\n\n文化是一个民族的根与魂。从A市竹编油纸伞的兴与困，到B县老街“像一个布景”的警醒，再到D村文化礼堂里的人气，生动图景发人深省：传统文化既不能锁进玻璃柜当作标本，也不能削足适履沦为噱头。唯有守住根脉、融入时代，文化才能真正活起来、传下去，为城乡发展注入持久的精神力量。\n\n守住根脉，才能让文化传承不失其本。B县老街曾把铺面统一招商，卖的是与本地无关的货、听不到熟悉的乡音，热闹一阵便门可罗雀；而后来坚持原址修缮、保留街巷肌理、让原住民留下来，老街才重新有了烟火气。这正反两面的对比说明，历史街区、传统村落的魂魄在于真实的生活与独特的文化，一旦抽空，剩下的不过是空壳。技艺传承亦然：若为迎合市场一减再减、以机器批量替代手工，短期产品便宜了、赚钱了，长远看却丢掉了手艺中最珍贵的东西。守住根脉，不是抱残守缺，而是要弄清什么必须坚守、什么可以创新，为传统留一条清晰的底线。\n\n融入时代，才能让文化传承获得活力。文化若不能在当代生活中被使用、被需要，就只能枯萎。A市把传统纹样、榫卯结构用到文具和家居用品上，让竹编灯罩成为热销品；一位油纸伞传承人走进直播间，把伞面上的故事讲给万千网友；“老戏新唱”借力短视频，意外赢得年轻观众。这些探索的共同点，是让传统技艺从“被保护的展品”变成“可用的产品”，从“别人来看的热闹”变成“自己参与的生活”。更值得注意的是，融入时代不仅是产品形态的更新，还有传播方式、经营理念和人才结构的更新——要把设计、营销、运营的专业力量引进来，把返乡青年、文化能人培养起来，文化的活水才不会断流。\n\n城乡协同，才能让文化传承扎根大地。文化建设的短板，往往不在硬件而在运营。C镇一些村的书屋常年锁门、礼堂一年热闹几场，问题不在房子建得不够好，而在没有人打理、内容不对群众胃口；D村把礼堂交给文化能人和返乡大学生，一室多用，E村把老祠堂改成村史馆和议事厅，老人给孩子讲村子的来龙去脉，设施就活了。这提示我们：公共文化服务要从“送文化”转向“种文化”，从“配设施”转向“育队伍”，多问群众想要什么，让群众自己办起来。同时，城乡要一体谋划，把博物馆、图书馆的大门对乡村敞开，把学校、家庭、社会的力量调动起来，让青少年在身边就能触摸到文化的温度——传承从来不是一代人的事。\n\n守住根脉与融入时代，看似两端，实则一体。只守不进，文化会僵；只进不守，文化会散。既不能搞“僵化保护”，把老手艺供成古董；也不能搞“过度开发”，把文化消费成噱头。让传统在生活里生长、在创新中延续、在城乡间流动，中华优秀传统文化必将焕发更加夺目的光彩，为民族复兴凝聚起持久而深沉的力量。\n\n【写作提示】\n1.立意角度。围绕“守正与创新”“保护与利用”的辩证关系立意，可聚焦“活态传承”，也可从“守住根脉、融入时代、城乡协同”三个维度展开。核心是把传统文化传承与城乡文化建设、群众生活、青少年成长贯通起来，落到文化自信和精神力量上。\n2.结构安排。建议“总—分—总”：开篇由资料中的典型现象或一句有分量的话引出总论点；主体设2~3个分论点，每段按“观点句＋资料例证＋简要分析＋对策落点”展开，注意结合而不拘泥于给定资料，可补充身边鲜活事例，如博物馆热、非遗进校园、国潮消费等；结尾回扣主题并适度升华。\n3.注意事项。标题要准确凝练，避免“论文化建设”一类空泛表述；分论点句式力求整齐；切忌大段照抄给定资料；语言平实有力，可适度引用名言；字数控制在1000~1200字，卷面工整。"}]},{"id":"gd-2023","title":"2023年广东省公务员录用考试《行政职业能力测验》（模拟卷）","region":"广东省","examType":"广东省考","subject":"行测","year":2023,"duration":90,"totalScore":100,"note":"本卷为依据历年真题题型结构编写的原创模拟题，非官方真题原文，仅供练习。","sections":[{"name":"言语理解与表达","material":null,"questions":[{"id":"gd-2023-01","stem":"一些城市在推进老旧街区改造时，倾向于大拆大建，把原有的街巷格局和居民生活一并抹去，代之以整齐划一的新建筑。这样的改造看似面貌一新，却切断了居民与原有生活空间的情感联系，也让城市失去了可辨识的历史记忆。事实上，老旧街区的价值不仅在于建筑本身，更在于其中长期形成的邻里关系、生活习俗和社区网络。因此，街区改造应当把人的需要放在首位，在改善居住条件的同时，尽可能保留原有的空间肌理和社会关系。\n这段文字意在说明：","options":["大拆大建的改造方式能够迅速改善城市面貌，值得推广","老旧街区改造应在改善居住条件的同时，保留原有的空间肌理和社会关系","历史建筑是城市历史记忆的唯一载体，必须原封不动地保存","老旧街区的建筑价值高于其中长期形成的社会关系价值"],"answer":1,"explain":"文段先批评大拆大建的弊端，再指出老旧街区的价值更在于邻里关系与社区网络，最后用“因此”给出对策：改造应把人的需要放在首位，兼顾居住改善与原有空间肌理、社会关系的保留。A项与文意相反，C项“唯一”过于绝对，D项颠倒价值判断。"},{"id":"gd-2023-02","stem":"中小企业量大面广，是技术创新的重要源泉，但在实际中往往面临研发资金不足、人才短缺、试验设备缺乏等困难。一些地方通过建立公共技术服务平台，向中小企业开放大型科研仪器和检测设备，并组织高校院所的专家提供技术咨询，使不少中小企业的创新成本明显降低、研发周期大幅缩短。这说明，支持中小企业创新未必需要直接投入大量资金，搭建共享平台同样是有效的方式。\n这段文字主要说明：","options":["中小企业是技术创新的主体，应当获得更多直接资金补贴","中小企业创新普遍面临资金、人才和设备的三重困难","搭建公共技术服务平台是支持中小企业创新的有效途径","大型科研仪器只能由高校和科研院所使用，不宜向社会开放"],"answer":2,"explain":"文段先说明中小企业创新的现实困难，再举例介绍一些地方搭建公共技术服务平台的做法与成效，末句“这说明”点明主旨：支持中小企业创新，搭建共享平台同样是有效方式。A项与末句意思相悖，B项只是背景而非重点，D项与文段举例内容相反。"},{"id":"gd-2023-03","stem":"将下列句子重新排列组合，语序最恰当的一项是：\n①城市湿地能够在降雨时吸纳并储存大量雨水\n②近年来，随着城市规模不断扩张，不透水地面大幅增加\n③在干旱时节，这些储存的雨水又能缓慢释放，补给周边的土壤和植被\n④这导致雨水难以自然下渗，地表径流量显著增加\n⑤从而减轻了城市排水管网的压力，也降低了内涝发生的风险\n⑥因此，保护和修复城市湿地，是提升城市韧性的重要举措","options":["④②①③⑤⑥","②④①⑤③⑥","②①④⑤③⑥","①②④③⑤⑥"],"answer":1,"explain":"②先交代城市扩张、不透水地面增加的背景，④中“这”指代②所述现象，二者必须相连；①承接④引出城市湿地吸纳雨水的功能，⑤用“从而”紧承①说明其效果，③补充干旱时释放雨水的另一功能，⑥用“因此”作总结。故顺序为②④①⑤③⑥。"},{"id":"gd-2023-04","stem":"推进基层治理，既要善于________群众的诉求，也要勇于________矛盾，不能遇到问题就绕着走。\n依次填入横线部分最恰当的一项是：","options":["倾听 直面","体察 回避","忽视 直面","忽视 回避"],"answer":0,"explain":"第一空与“善于”搭配，并要与后文“绕着走”形成对比，“倾听”体现主动了解群众诉求的态度，“忽视”与“善于”自相矛盾。第二空由“勇于”和“不能遇到问题就绕着走”可知，所填词应与“回避”意思相反，“直面”符合。故只有第一项两空皆恰当。"},{"id":"gd-2023-05","stem":"面对复杂多变的市场环境，企业不能________，而应当立足自身条件选择适合的发展路径。盲目跟风往往导致资源分散、优势丧失，最终________。\n依次填入横线部分最恰当的一项是：","options":["独辟蹊径 事半功倍","独树一帜 得不偿失","随波逐流 事半功倍","随波逐流 得不偿失"],"answer":3,"explain":"第一空与后文“盲目跟风”呼应，“随波逐流”指没有主见、跟着别人走，最合语境；“独辟蹊径”“独树一帜”都表示有独特做法，与“不能”及“盲目跟风”相矛盾。第二空承接“资源分散、优势丧失”，结果应是付出多而收获少，“事半功倍”与文意相反。"}]},{"name":"数量关系","material":null,"questions":[{"id":"gd-2023-06","stem":"一项工程，甲队单独完成需要12天，乙队单独完成需要24天。现由两队合作完成，期间甲队因故休息了若干天，结果从开工到完工共用了10天。问甲队休息了几天？","options":["2天","3天","4天","5天"],"answer":1,"explain":"设工程总量为24，则甲队效率为2，乙队效率为1。乙队10天全程工作，共完成10，剩余14由甲队完成，甲队实际工作14÷2=7天。总工期为10天，故甲队休息了10-7=3天。"},{"id":"gd-2023-07","stem":"某商品按进价加价50%标价，因销路不畅，商家按标价打八折出售，每件仍获利24元。问该商品的进价是多少元？","options":["80元","100元","120元","150元"],"answer":2,"explain":"设进价为x元，则标价为1.5x元，打八折后售价为1.5x×0.8=1.2x元，每件获利1.2x-x=0.2x元。由0.2x=24解得x=120。验证：进价120元、标价180元、八折售价144元，利润144-120=24元，与题意相符。"},{"id":"gd-2023-08","stem":"某兴趣小组共有5名男生和4名女生，现要从中选出4人组成参赛小队，要求小队中至少有1名女生。问共有多少种不同的选法？","options":["120种","121种","125种","126种"],"answer":1,"explain":"采用间接法。从9人中任选4人共有C(9,4)=126种选法；其中4人全是男生的选法为C(5,4)=5种，不符合“至少有1名女生”的要求。故符合条件的选法为126-5=121种，注意结果不重复也不遗漏。"}]},{"name":"判断推理","material":null,"questions":[{"id":"gd-2023-09","stem":"一组正多边形按下列顺序排列：第1个是正三角形，第2个是正方形，第3个是正五边形，第4个是正六边形……按此规律，第7个图形的对称轴共有多少条？","options":["7条","8条","9条","10条"],"answer":2,"explain":"规律为第n个图形是正(n+2)边形。正多边形的边数与对称轴条数相等，故第7个图形是正九边形，对称轴有9条。也可直接观察序列：3、4、5、6、7、8、9，第7项为9条。"},{"id":"gd-2023-10","stem":"“隐性知识”是指难以通过语言、文字、图表等方式明确表达和传递，主要依靠个人长期经验、直觉和体悟才能获得的知识。\n根据上述定义，下列属于隐性知识的是：","options":["老张从医三十余年，能够凭手感判断患者脉象的细微变化","小李从教科书上学到的机械零件公差计算公式","某企业将老师傅的调漆经验整理成图文手册供新员工学习","小王在论文中详细记录了数据分析的完整操作流程"],"answer":0,"explain":"隐性知识的关键是难以用语言文字明确表达、依赖个人经验与体悟。第一项凭手感判断脉象变化，是经验积累形成的直觉，无法用文字完整传递，符合定义。第二项的公式、第四项的流程都能用文字明确表述；第三项经验已整理成图文手册，可明确传递，属显性知识。"},{"id":"gd-2023-11","stem":"“沉没成本”是指已经发生且无法收回的支出。理性决策应当只比较未来的成本与收益，而不受沉没成本的影响。\n根据上述定义，下列最能体现“理性对待沉没成本”的是：","options":["小张为一个已投入三年的项目继续追加投资，理由是前期投入太多，不能半途而废","某公司因已购设备闲置可惜，勉强继续生产已经滞销的产品","小王觉得自助餐已付费，即使吃不下了也坚持把盘子里的食物吃完","小刘买票进场后看了半小时觉得影片无趣，果断退场去做更有意义的事"],"answer":3,"explain":"定义强调决策不受已发生且无法收回的支出影响。第四项中票款已付且无法收回，小刘以“是否值得继续看”为标准及时退场，符合理性对待沉没成本。前三项都是因为舍不得已经付出的成本而继续追加投入或勉强坚持，属于被沉没成本左右的非理性决策。"},{"id":"gd-2023-12","stem":"医生∶患者∶医院\n找出与题干逻辑关系最为贴近、相似或匹配的一项：","options":["演员∶观众∶电影","律师∶法官∶法院","厨师∶菜肴∶餐厅","教师∶学生∶学校"],"answer":3,"explain":"题干中医生在医院为患者提供服务，构成“服务者—服务对象—场所”的关系。第四项教师在学校为学生提供教育服务，关系完全一致。第一项电影是演员表演的作品而非场所；第二项律师与法官是不同职业，不存在服务关系；第三项菜肴是厨师制作的产物而非服务对象。"},{"id":"gd-2023-13","stem":"某市为缓解早晚高峰交通拥堵，推行“错峰上下班”制度，鼓励机关和企事业单位调整上下班时间。制度实施一年后，该市主干道早晚高峰平均车速比实施前提高了8%。因此有人认为，错峰上下班制度有效缓解了交通拥堵。\n以下哪项如果为真，最能削弱上述结论？","options":["部分企业对错峰上下班制度配合度不高，执行并不到位","该市主干道非高峰时段的平均车速与实施前相比基本没有变化","同期该市新开通了两条地铁线路，分流了大量主干道通勤客流","部分市民反映，错峰上下班后自己的出行体验没有明显改善"],"answer":2,"explain":"题干由高峰车速提高推出错峰制度有效，属因果论证。第三项指出同期新开通地铁并分流大量通勤客流，说明车速提高可能存在他因，直接削弱了制度与缓解拥堵的因果关系。第一、四项只涉及执行情况和主观感受，力度弱；第二项排除了整体交通好转的解释，不能削弱。"},{"id":"gd-2023-14","stem":"某小组要从张、王、李、赵四人中选出一人参加比赛。已知：\n（1）如果选张，那么也选王；\n（2）张和王中至少选一人；\n（3）如果不选王，那么选张。\n若最终只选出一人，则被选出的是：","options":["张","王","李","赵"],"answer":1,"explain":"由（1）可知，若选张则必选王，两人同去与“只选一人”矛盾，故不选张。由（2）张、王中至少选一人，既然不选张，则必选王。代入（3）：“不选王”为假，假言命题整体为真，与条件相符。因此被选出的是王。"}]},{"name":"资料分析","material":"2022年，某市实现地区生产总值12000亿元，比上年增长4.0%。其中，第一产业增加值600亿元，增长2.0%；第二产业增加值4800亿元，增长3.5%；第三产业增加值6600亿元，增长4.5%。\n全年社会消费品零售总额4500亿元，比上年增长2.5%；进出口总额8480亿元，比上年增长6.0%。\n全年城镇居民人均可支配收入60000元，比上年增长3.0%；农村居民人均可支配收入24000元，比上年增长5.0%。","questions":[{"id":"gd-2023-15","stem":"2022年，该市第三产业增加值占地区生产总值的比重约为：","options":["45%","50%","52%","55%"],"answer":3,"explain":"根据资料，2022年该市地区生产总值为12000亿元，第三产业增加值为6600亿元。比重=6600÷12000=0.55，即55%。可用三次产业增加值600+4800+6600=12000亿元验证资料自洽，故选55%。"},{"id":"gd-2023-16","stem":"2021年该市进出口总额约为多少亿元？","options":["7600","8000","8480","9000"],"answer":1,"explain":"本题考查基期量计算。基期量=现期量÷(1+增长率)，即8480÷1.06=8000亿元。需要注意的是，基期量不能用8480×(1-6%)来求，增长率应作除数而非直接相减，否则会得到偏小的结果。故为8000亿元。"},{"id":"gd-2023-17","stem":"2022年该市第三产业增加值比第二产业增加值约多百分之几？","options":["27.5%","32.5%","37.5%","45%"],"answer":2,"explain":"2022年该市第三产业增加值为6600亿元，第二产业增加值为4800亿元，二者之差为1800亿元。所求为1800÷4800=0.375，即37.5%。注意“比……多百分之几”应以作为比较基准的第二产业增加值为分母。"}]},{"name":"常识判断","material":null,"questions":[{"id":"gd-2023-18","stem":"下列关于粤港澳大湾区的表述，正确的是：","options":["港珠澳大桥连接广州、香港、澳门三地","深圳前海、珠海横琴是粤港澳合作的重要平台，其中前海位于珠海","粤港澳大湾区仅包括香港、澳门和广州、深圳四个城市","粤港澳大湾区由香港、澳门两个特别行政区和广东省珠三角九市组成"],"answer":3,"explain":"粤港澳大湾区由香港、澳门两个特别行政区和广州、深圳、珠海、佛山、惠州、东莞、中山、江门、肇庆九个珠三角城市组成，即“9+2”。港珠澳大桥连接的是香港、珠海和澳门，并不连接广州；前海位于深圳，横琴位于珠海，大湾区也不止四个城市，故前三项均错。"},{"id":"gd-2023-19","stem":"下列关于岭南文化的说法，正确的是：","options":["《二泉映月》是广东音乐的代表曲目","粤绣（广绣）与苏绣、湘绣、蜀绣并称中国四大名绣","粤剧唱腔以西洋美声唱法为主，不使用粤方言演唱","岭南画派的代表人物是齐白石和张大千"],"answer":1,"explain":"粤绣（广绣）与苏绣、湘绣、蜀绣并称中国四大名绣。《二泉映月》是江苏无锡民间音乐家华彦钧（阿炳）创作的二胡名曲，并非广东音乐；粤剧以粤方言演唱，是岭南代表性剧种，有“南国红豆”之称；岭南画派代表人物为高剑父、高奇峰、陈树人。"},{"id":"gd-2023-20","stem":"关于广东的改革开放与区域发展，下列说法正确的是：","options":["广东是全国唯一拥有经济特区的省份","珠江三角洲地区包括广东省全部21个地级市","我国最早设立的四个经济特区中，广东占三个","广东的简称是“桂”，省会是深圳"],"answer":2,"explain":"1980年我国设立深圳、珠海、汕头、厦门四个经济特区，其中深圳、珠海、汕头均在广东，广东占三个。福建同样拥有经济特区（厦门），故“唯一”错误；珠三角并未涵盖广东全部地级市；广东简称“粤”，省会是广州，故其余各项均有误。"}]},{"name":"科学推理","material":null,"questions":[{"id":"gd-2023-21","stem":"用一张较厚的纸折成一个小盒，向盒中加入适量清水，再把它放在点燃的酒精灯上加热。过了一段时间水沸腾了，纸盒却完好无损，并没有被烧着。对这种现象最合理的解释是：","options":["纸的着火点明显高于水的沸点，水沸腾时不断吸热汽化，使纸盒温度始终达不到着火点","水把纸盒与火焰完全隔开，火焰的热量根本无法传递到纸盒上","纸盒浸湿之后着火点升高，因此不再具备燃烧的条件","水的比热容较大，能够把火焰放出的热量全部吸收，纸盒温度始终不变"],"answer":0,"explain":"纸的着火点在130℃以上，水的沸点为100℃。加热时水不断沸腾汽化，大量吸收热量，使纸盒温度始终略高于100℃而远低于着火点，因此不会燃烧。B项中热量仍能传到纸盒，C项着火点不因遇水而改变，D项“全部吸收”表述绝对。"},{"id":"gd-2023-22","stem":"家用洁厕灵的主要成分是盐酸，84消毒液的有效成分是次氯酸钠。若把二者混合使用，会放出一种黄绿色、有强烈刺激性气味的有毒气体，危害人体健康。这种气体是：","options":["氧气","氢气","氯气","二氧化碳"],"answer":2,"explain":"盐酸与次氯酸钠发生氧化还原反应：NaClO+2HCl=NaCl+Cl2↑+H2O，生成的氯气呈黄绿色、有强烈刺激性气味且有毒，与题述现象一致。氧气、氢气、二氧化碳均为无色气体，也没有刺激性气味，均不符合。故二者绝不能混合使用。"},{"id":"gd-2023-23","stem":"买回家的新鲜叶菜用保鲜袋装好放进冰箱冷藏室，通常能比放在室温下多保存好几天。下列解释最合理的是：","options":["低温使蔬菜细胞的呼吸作用明显减弱，有机物消耗减慢，同时微生物的繁殖也受到抑制","低温使蔬菜细胞完全停止呼吸作用，不再消耗自身储存的有机物","低温使蔬菜细胞的光合作用增强，能够不断合成新的有机物加以补充","保鲜袋把袋内空气完全隔绝，蔬菜因此无法进行呼吸作用"],"answer":0,"explain":"蔬菜采收后不再进行光合作用，只能靠呼吸作用消耗自身储存的有机物。低温能降低呼吸酶的活性，使呼吸作用减弱、有机物消耗减慢，同时抑制微生物繁殖，故能延长保鲜期。呼吸作用并不会完全停止，保鲜袋也不能完全隔绝空气，且在无光条件下光合作用无法进行。"}]},{"name":"政治理论","material":null,"questions":[{"id":"gd-2023-24","stem":"马克思主义认为，社会存在决定社会意识，社会意识又具有相对独立性。下列表述最能体现社会意识相对独立性的是：","options":["社会意识的内容归根到底来源于社会存在，是社会存在的反映","旧的社会制度被取代之后，落后的思想观念仍可能长期存在并影响人们的行为","社会存在一旦发生变化，社会意识就会立即随之发生同步的变化","生产力的发展水平决定着生产关系的性质和变革方向"],"answer":1,"explain":"社会意识的相对独立性表现为它与社会存在的变化不完全同步，具有历史继承性，并反作用于社会存在。第二项中旧制度消亡后落后观念仍长期存在，正体现这种不同步性。第一项讲社会存在决定社会意识，第三项与相对独立性相反，第四项讲生产力与生产关系的关系。"},{"id":"gd-2023-25","type":"multi","stem":"中国式现代化既有各国现代化的共同特征，更有基于自身国情的中国特色。下列属于中国式现代化中国特色的有：","options":["人口规模巨大的现代化","少数人先富起来的现代化","物质文明和精神文明相协调的现代化","人与自然和谐共生的现代化"],"answer":[0,2,3],"explain":"中国式现代化是人口规模巨大的现代化，是全体人民共同富裕的现代化，是物质文明和精神文明相协调的现代化，是人与自然和谐共生的现代化，是走和平发展道路的现代化。第一、三、四项符合。第二项“少数人先富起来”与全体人民共同富裕的要求相违背，故不选。"},{"id":"gd-2023-26","type":"judge","stem":"判断：生产关系一定要适合生产力发展状况是客观规律，因此生产关系的变革越超前，就越能促进生产力的发展。","options":["正确","错误"],"answer":1,"explain":"生产关系一定要适合生产力发展状况，意味着生产关系既不能长期落后于生产力，也不能超越生产力的发展水平。人为拔高、超前变革生产关系，同样会阻碍甚至破坏生产力的发展。该说法的症结在于把“适合”偷换为“越超前越好”，故其错误。"}]}]},{"id":"gd-2024","title":"2024年广东省公务员录用考试《行政职业能力测验》（模拟卷）","region":"广东省","examType":"广东省考","subject":"行测","year":2024,"duration":90,"totalScore":100,"note":"本卷为依据历年真题题型结构编写的原创模拟题，非官方真题原文，仅供练习。","sections":[{"name":"言语理解与表达","material":null,"questions":[{"id":"gd-2024-01","stem":"社区养老服务的难点，往往不在场地和设备，而在人。一个日间照料中心即使装修一新，如果没有稳定的护理员队伍，服务也难以持续。而护理员流失的原因，多半不是技能不足，而是职业认同感低、上升通道窄。因此，想让社区养老真正立得住，就要在待遇保障和职业发展上给出实实在在的安排。这段文字主要说明：","options":["社区养老服务的场地和设备并非关键问题","稳定护理员队伍是社区养老持续发展的关键","护理员流失的主要原因是专业技能不足","日间照料中心的装修水平决定服务质量"],"answer":1,"explain":"文段先指出社区养老的难点\"在人不在地\"，接着分析护理员流失的深层原因是职业认同感低、上升通道窄，最后落到待遇保障与职业发展。可见主旨是稳定护理员队伍，其余三项均为文段局部信息或与文意相反。"},{"id":"gd-2024-02","stem":"一项针对农技推广的调查显示，接受过系统培训的农户，平均亩产比未接受培训的农户高出约两成；但培训结束一年后，仍坚持采用新技术的农户不足一半。研究者认为，问题不在技术本身，而在于推广往往止于\"教会\"，缺少后续的跟踪服务和风险兜底，农户一旦在应用中受挫，就容易退回熟悉的老办法。这段文字主要说明：","options":["新技术能够显著提高农产品的单位面积产量","农户对农业新技术的接受程度普遍不高","农技推广需要配套持续的后续服务与风险保障","系统培训是农技推广取得成效的必要环节"],"answer":2,"explain":"文段先承认培训有效，随后用\"但\"转折指出坚持者不足一半，并直接点明原因在于缺少后续跟踪服务和风险兜底。作者要说明的是推广方式需要改进，故选择强调配套后续服务的一项，其余三项均偏离落脚点。"},{"id":"gd-2024-03","stem":"将下列句子重新排列，语序最恰当的一项是：\n①近年来，青少年体质健康问题受到越来越多的关注\n②作为提升体质最直接的途径，学校体育课本应发挥重要作用\n③然而，一些学校的体育课长期被其他课程挤占，课时难以保证\n④课时不足直接导致学生失去规律锻炼的机会，体质改善无从谈起\n⑤因此，要让体育课真正发挥作用，还须在课时保障和评价机制上作出制度安排","options":["①②③④⑤","①③②④⑤","②①③④⑤","①③④②⑤"],"answer":0,"explain":"①交代背景、引出话题；②指出体育课应有的作用，③以\"然而\"转折指出被挤占的现状，与②构成正反照应；④中的\"课时不足\"紧承③；⑤以\"因此\"作结论性收束。故顺序为①②③④⑤。"},{"id":"gd-2024-04","stem":"依次填入下列横线处的词语，最恰当的一项是：\n任何一项改革都不可能______，它总要触动既有的利益格局，因而难免遇到阻力。改革者需要的不仅是勇气，更是______的耐心，在反复权衡中寻找最大公约数。","options":["一帆风顺 / 急功近利","一劳永逸 / 立竿见影","一蹴而就 / 锲而不舍","轻而易举 / 一曝十寒"],"answer":2,"explain":"\"一蹴而就\"指一下子就成功，与改革要触动利益格局、难免遇阻相呼应；第二空\"锲而不舍\"形容持之以恒，与\"耐心\"搭配恰当。其余三项的第二空均与\"耐心\"搭配不当，可整体排除。"},{"id":"gd-2024-05","stem":"依次填入下列横线处的词语，最恰当的一项是：\n科学传播不是把专业结论简单地\"翻译\"成大白话，而是要在______与准确之间寻找平衡：过分通俗可能牺牲严谨，过分严谨又容易让公众______。","options":["生动 / 一知半解","通俗 / 望而却步","简洁 / 嗤之以鼻","严谨 / 心领神会"],"answer":1,"explain":"由后文\"过分通俗可能牺牲严谨\"可知第一空应填\"通俗\"，与\"准确\"构成一组对应；\"望而却步\"指因畏惧而退缩，恰好说明过分严谨会让公众疏远，符合语境。其余选项与这一对应关系均不成立。"}]},{"name":"数量关系","material":null,"questions":[{"id":"gd-2024-06","stem":"一个长方形的长比宽多4米。若把它的长和宽都增加3米，则面积增加57平方米。这个长方形原来的面积是多少平方米？","options":["48平方米","60平方米","63平方米","72平方米"],"answer":1,"explain":"设原宽为w米，则原长为(w＋4)米。长宽各增加3米后面积为(w＋3)(w＋7)，比原来多57，即(w＋3)(w＋7)＝w(w＋4)＋57，展开得w²＋10w＋21＝w²＋4w＋57，解得w＝6，原长10米，故原面积为6×10＝60平方米。"},{"id":"gd-2024-07","stem":"甲、乙两人沿同一条环形跑道同向跑步，甲每分钟跑250米，乙每分钟跑200米，跑道一圈长800米。两人同时同地出发，经过多少分钟甲第一次追上乙？","options":["8分钟","12分钟","16分钟","20分钟"],"answer":2,"explain":"同向而行时，甲第一次追上乙意味着甲比乙正好多跑一圈，即多跑800米。甲每分钟比乙多跑250－200＝50米，所需时间为800÷50＝16分钟。验证：16分钟时甲跑5圈、乙跑4圈，恰好相差一圈。"},{"id":"gd-2024-08","stem":"袋中装有3个红球和2个白球，从中不放回地随机取出2个球，取出的两个球颜色相同的概率是多少？","options":["1/5","2/5","3/5","1/2"],"answer":1,"explain":"从5个球中任取2个共有C(5,2)＝10种取法；颜色相同包括2红或2白，共C(3,2)＋C(2,2)＝3＋1＝4种。所求概率为4÷10＝2/5。"}]},{"name":"判断推理","material":null,"questions":[{"id":"gd-2024-09","stem":"一个圆被过圆心的水平线和垂直线分成四个扇形区域。一组图形呈现如下规律：第1个图形中黑色扇形位于右上角，第2个图形中黑色扇形位于右下角，第3个图形中黑色扇形位于左下角，即黑色扇形每次沿顺时针方向移动一个区域。按此规律，第4个图形中黑色扇形应位于：","options":["右下角","正上方","左上角","右上角"],"answer":2,"explain":"黑色扇形依次位于右上、右下、左下，即每一步都沿顺时针方向旋转90度。继续顺时针移动一个区域，第4个图形中的黑色扇形应落在左上角，也就是转过四分之三圈后所处的位置。"},{"id":"gd-2024-10","stem":"信息茧房，是指人们长期只接触自己偏好的信息，从而把自己置于相对封闭的信息环境之中，逐渐丧失了解多元信息、进行独立判断的能力。根据上述定义，下列属于信息茧房的是：","options":["小陈只关注与自己观点一致的博主，对相反意见一概不看，久而久之以为自己的看法就是主流","小刘为完成调研任务，广泛查阅了立场各异的资料并逐一对比","小周因工作繁忙，每天只浏览几分钟新闻便不再关注","小吴购物时习惯货比三家，反复比较之后才决定下单"],"answer":0,"explain":"信息茧房的要点是\"只接触自己偏好的信息\"并因此陷入封闭、丧失多元判断能力。该项中只关注观点一致的博主、回避相反意见，完全符合定义。广泛查阅立场各异的资料与定义相反，只浏览几分钟是时间精力所限，货比三家属于消费决策行为，均不符合。"},{"id":"gd-2024-11","stem":"逆向物流，是指商品从消费端返回到生产端或处理端的流通过程，通常包括退货、召回、废旧产品回收等环节。根据上述定义，下列不属于逆向物流的是：","options":["电商平台将消费者退回的服装集中运回区域仓库","汽车厂商对存在缺陷的零部件实施召回并集中处理","家电企业上门回收旧冰箱，运回工厂拆解再利用","经销商将新生产的空调从工厂运往各地门店上架"],"answer":3,"explain":"逆向物流的方向是商品由消费端返回到生产端或处理端。退货回流仓库、召回缺陷零部件、回收旧家电拆解都符合这一方向；而把新生产的空调从工厂运往门店，属于正向的销售物流，方向相反，故不属于逆向物流。"},{"id":"gd-2024-12","stem":"指南针∶方向","options":["书本∶知识","天平∶质量","道路∶汽车","画笔∶画家"],"answer":1,"explain":"题干中指南针是用于指示方向的工具，二者为\"工具与其作用对象\"的关系。天平是用于测量质量的工具，关系与之最为贴近。书本是知识的载体而非测量工具，道路是汽车的行驶场所，画笔与画家是工具与使用者的关系，均与题干不一致。"},{"id":"gd-2024-13","stem":"甲、乙、丙三人中有一人利用周末去社区做了志愿服务，另外两人没有去。三人的说法如下：甲说\"乙去了\"；乙说\"我没有去\"；丙说\"甲没有去\"。已知三人中只有一人说了真话，则去社区做志愿服务的是：","options":["乙","丙","甲","根据条件无法确定"],"answer":2,"explain":"假设甲去了：甲说\"乙去了\"为假，乙说\"我没有去\"为真，丙说\"甲没有去\"为假，恰好一真两假，符合条件。若去的是乙，则甲、丙的话都为真；若去的是丙，则乙、丙的话都为真，均不符合。故去社区做志愿服务的是甲。"},{"id":"gd-2024-14","stem":"某市图书馆试行延时开放，将闭馆时间由17时推迟到21时。试行三个月后，夜间到馆读者日均约300人次，其中多数是上班族。该馆据此认为，延时开放有效满足了市民的阅读需求。要使上述结论成立，还需要补充的前提是：","options":["延时开放期间图书馆的水电和人力成本有所增加","其他城市的部分图书馆也实行过延时开放","夜间到馆的读者多数此前因闭馆时间过早而无法到馆","该市市民的总体阅读量近年来呈上升趋势"],"answer":2,"explain":"题干由\"夜间到馆人数多\"推出\"延时开放满足了阅读需求\"，隐含前提是这些人原本因闭馆过早而无法到馆，即延时开放创造了新增需求，而非把白天的人挪到晚上。若多数人本来也会在白天到馆，则需求并未被额外满足。成本、其他城市做法、总体阅读量均无关。"}]},{"name":"资料分析","material":"某市2023年全年实现规模以上工业增加值1200亿元，比上年增长8.0%。分行业看：电子信息业实现增加值420亿元，比上年增长12.5%；装备制造业实现增加值300亿元，比上年增长5.0%；纺织服装业实现增加值180亿元，比上年下降2.5%；其余行业合计实现增加值300亿元，比上年增长12.2%。\n全年该市完成固定资产投资800亿元，比上年增长10.0%，其中工业投资320亿元，比上年增长15.0%。\n全年该市实现社会消费品零售总额1500亿元，比上年增长6.5%。","questions":[{"id":"gd-2024-15","stem":"2022年该市规模以上工业增加值约为多少亿元？","options":["1080","1104","1111","1120"],"answer":2,"explain":"材料给出2023年规模以上工业增加值1200亿元、比上年增长8.0%，求基期值应除以(1＋增长率)，即1200÷1.08≈1111亿元。注意不能用1200×(1－8%)或1200×8%来计算。"},{"id":"gd-2024-16","stem":"2023年该市社会消费品零售总额约是固定资产投资的多少倍？","options":["1.5倍","1.9倍","2.4倍","0.5倍"],"answer":1,"explain":"求倍数用社会消费品零售总额除以固定资产投资，即1500÷800＝1.875，约为1.9倍。注意\"A是B的多少倍\"应计算A÷B，不能颠倒为800÷1500，也不必把现期数据换算成基期数据。"},{"id":"gd-2024-17","stem":"2023年该市社会消费品零售总额比上年约增加多少亿元？","options":["92","98","105","75"],"answer":0,"explain":"已知现期值1500亿元、增长率6.5%，求增长量应用1500÷(1＋6.5%)×6.5%≈1500÷1.065×0.065≈91.5亿元，即约92亿元。若直接用1500×6.5%＝97.5亿元，是把增长率错用于现期值，属常见陷阱。"}]},{"name":"常识判断","material":null,"questions":[{"id":"gd-2024-18","stem":"下列关于广东方言分布的说法，正确的是：","options":["广东全省居民都能用粤方言交流","广东境内主要分布粤方言、客家方言和闽方言三大方言","客家方言主要分布在珠江三角洲的核心地带","闽方言在广东境内没有分布"],"answer":1,"explain":"广东境内的汉语方言主要有粤方言、客家方言和闽方言三大类，故该项正确。粤方言并非全省通用；客家方言主要分布在粤东、粤北的梅州、河源、韶关等地，而非珠江三角洲核心地带；闽方言在粤东潮汕一带和雷州半岛也有分布。"},{"id":"gd-2024-19","stem":"下列关于珠江的说法，正确的是：","options":["珠江是我国流程最长的河流","珠江三角洲位于长江入海口附近","珠江是西江、北江、东江及珠江三角洲诸河的总称","珠江发源于广东省境内"],"answer":2,"explain":"珠江并非一条单一的河流，而是西江、北江、东江及珠江三角洲诸河的总称，故该项正确。我国流程最长的河流是长江；珠江三角洲位于珠江入海口一带，与长江入海口无关；其干流西江发源于云南省，并非发源于广东境内。"},{"id":"gd-2024-20","stem":"下列省级行政区中，不与广东省陆地接壤的是：","options":["福建省","江西省","海南省","广西壮族自治区"],"answer":2,"explain":"广东省东邻福建，北接江西、湖南，西连广西，南临南海，与海南隔琼州海峡相望而不接壤。因此海南不属于与广东陆地相邻的省级行政区，其余三项均为广东的邻省（区）。"}]},{"name":"科学推理","material":null,"questions":[{"id":"gd-2024-21","stem":"下列生活现象与其物理原理对应正确的是：","options":["书包背带做得较宽——增大受力面积，减小对肩膀的压强","菜刀的刀刃磨得很薄——增大受力面积，减小压强","拦河大坝设计成下宽上窄——液体压强随深度增加而减小","用吸管吸饮料——嘴的吸力把饮料直接吸上来"],"answer":0,"explain":"书包背带做得较宽，是在压力一定时通过增大受力面积来减小压强，故该项正确。刀刃磨薄是减小受力面积、增大压强；大坝下宽上窄是因为液体压强随深度增加而增大；用吸管吸饮料靠的是外界大气压把饮料压上来，而不是嘴的吸力。"},{"id":"gd-2024-22","stem":"下列生活中的做法与其化学解释对应正确的是：","options":["用食醋浸泡可以除去水壶内壁的水垢——醋酸能与水垢中的碳酸钙等物质反应","在室内放一盆水可以防止一氧化碳中毒——一氧化碳易溶于水","用明矾处理自来水可以消毒杀菌——明矾能杀死水中的细菌","用铁制容器长期存放食醋——铁与醋酸不发生化学反应"],"answer":0,"explain":"水垢的主要成分是碳酸钙和氢氧化镁，食醋中的醋酸具有酸性，能与碳酸钙反应生成可溶的醋酸钙、水和二氧化碳，故可除垢。一氧化碳难溶于水，放水盆不起作用；明矾只能吸附悬浮杂质使其沉降，不能杀菌；铁能与醋酸反应。"},{"id":"gd-2024-23","stem":"移栽树苗时，人们常常剪去部分枝叶，并选择在傍晚进行移栽。这样做的主要目的是：","options":["降低蒸腾作用，减少水分散失，提高树苗成活率","降低呼吸作用，减少树苗体内有机物的消耗","减弱光合作用，避免移栽后叶片被强光灼伤","减少枝叶的相互遮挡，促使根系向土壤深处生长"],"answer":0,"explain":"移栽时根系受损，吸水能力下降。叶片是蒸腾作用的主要器官，剪去部分枝叶可减小蒸腾面积，减少水分散失；傍晚光照弱、气温低，蒸腾更弱。二者使树苗水分保持平衡，减少萎蔫，提高成活率。呼吸作用、光合作用并非主要原因。"}]},{"name":"政治理论","material":null,"questions":[{"id":"gd-2024-24","stem":"下列谚语最能体现\"量变是质变的必要准备，质变是量变的必然结果\"这一哲理的是：","options":["千里之堤，溃于蚁穴","城门失火，殃及池鱼","守株待兔","刻舟求剑"],"answer":0,"explain":"千里之堤，溃于蚁穴指蚁穴这样的微小隐患不断积累，最终导致大堤崩溃，正体现量变积累到一定程度必然引起质变的规律。城门失火殃及池鱼反映事物之间的普遍联系，守株待兔把偶然现象当作必然，刻舟求剑否认了事物的运动变化。"},{"id":"gd-2024-25","type":"multi","stem":"关于我国社会主义基本经济制度，下列理解正确的有：","options":["公有制为主体、多种所有制经济共同发展","按劳分配为主体、多种分配方式并存","社会主义市场经济体制","以按资分配为主体、多种分配方式并存"],"answer":[0,1,2],"explain":"我国社会主义基本经济制度包括公有制为主体、多种所有制经济共同发展的所有制结构，按劳分配为主体、多种分配方式并存的分配制度，以及社会主义市场经济体制。故前三项正确。第四项把按资分配说成主体，与按劳分配为主体的制度相违背。"},{"id":"gd-2024-26","type":"judge","stem":"判断：中国特色社会主义最本质的特征是中国共产党领导，中国特色社会主义制度的最大优势也是中国共产党领导。","options":["正确","错误"],"answer":0,"explain":"该表述正确，但两个分句的出处不同：“中国共产党领导是中国特色社会主义最本质的特征”由我国《宪法》第一条第二款明确规定；“中国特色社会主义制度的最大优势是中国共产党领导”出自党的十九大报告和党的十九届四中全会《决定》，属党的文献，并未写入宪法条文。坚持党的领导是保证我国发展社会主义方向、凝聚各方面力量的根本所在。"}]}]},{"id":"gd-2025","title":"2025年广东省公务员录用考试《行政职业能力测验》（模拟卷）","region":"广东省","examType":"广东省考","subject":"行测","year":2025,"duration":90,"totalScore":100,"note":"本卷为依据历年真题题型结构编写的原创模拟题，非官方真题原文，仅供练习。","sections":[{"name":"言语理解与表达","material":null,"questions":[{"id":"gd-2025-01","stem":"乡村振兴，既要塑形，也要铸魂。一个村庄如果只在房屋修缮、道路硬化上用力，却丢掉了自己的文化根脉，纵使面貌一新，也难免让人感到陌生。那些流传于田间地头的传统技艺、节庆习俗和乡音乡情，才是乡村真正的“魂”。留住乡亲、记住乡愁，离不开对乡村文化的持续滋养。这段文字意在强调：","options":["古村落的修缮保护应当作为乡村振兴的首要任务","乡村文化设施建设应优先于农村经济发展","文化根脉的传承与滋养是乡村振兴的内在要求","非物质文化遗产是乡村文化建设唯一的载体"],"answer":2,"explain":"文段先指出乡村振兴不能只搞建筑修缮，再强调文化根脉是乡村的“魂”，最后落到留住乡亲、记住乡愁，核心是文化传承与滋养对乡村振兴的意义。A项“首要任务”、B项“优先于经济”、D项“唯一载体”均属绝对化表述。"},{"id":"gd-2025-02","stem":"青年科研人员思维活跃、学习能力强，正处于创造力最旺盛的阶段，但也容易因考核压力而急于求成、频繁转向。基础研究往往周期长、见效慢，那些真正重要的突破常常来自十几年甚至更长时间的专注积累。因此，支持青年科研人员成长，既需要给予他们“板凳甘坐十年冷”的耐心，也需要建立允许试错、宽容失败的评价机制。这段文字主要说明：","options":["青年科研人员已经成为我国基础研究的绝对主力","支持青年科研人员成长，重在营造宽容失败、鼓励长期积累的制度环境","基础研究周期较长，青年科研人员应尽早转向应用研究","评价机制改革的关键是提高论文发表数量的考核要求"],"answer":1,"explain":"文段先指出青年科研人员有优势也有短板，再用“既需要……也需要……”引出重点，即制度上要给予长期积累的耐心和宽容失败的环境。B项正是这一主旨；A项表述绝对，C项与文意相反，D项与“宽容失败”的要求相悖。"},{"id":"gd-2025-03","stem":"将下列5个句子重新排列，语序最恰当的一项是：\n①城市治理的精细化，最终要落到市民可感可及的日常体验上\n②近年来，不少地方在老旧小区改造、背街小巷整治等方面投入了大量资源\n③但也有一些地方出现“重建设、轻管护”的现象，设施建成后很快又陷入失管状态\n④这说明，仅靠一次性投入难以形成长效机制\n⑤因此，把管护责任、资金来源和居民参与机制一并明确下来，才是治本之策","options":["②①③④⑤","①②③⑤④","②③①⑤④","③④⑤①②"],"answer":0,"explain":"②先交代各地投入资源的背景，①点明治理要落到日常体验，③用“但”转折指出重建设轻管护的问题，④的“这说明”承接③，⑤的“因此”给出治本之策，故为②①③④⑤。其余选项均存在指代不明或结论与依据倒置的问题。"},{"id":"gd-2025-04","stem":"依次填入下列横线处的词语，最恰当的一项是：\n产业转型升级不可能____，需要循序渐进、久久为功；面对技术变革的冲击，企业既要有保持定力的清醒，也要善于____，及时调整发展路径。","options":["一挥而就　见风使舵","一蹴而就　顺势而为","一劳永逸　随波逐流","立竿见影　亦步亦趋"],"answer":1,"explain":"第一空，“一蹴而就”指事情一下子就能成功，与“循序渐进、久久为功”正相对；第二空，企业应对技术变革应“顺势而为”，含褒义。A项“一挥而就”形容写作绘画，C、D项第二空的“随波逐流”“亦步亦趋”均含贬义，不合语境。"},{"id":"gd-2025-05","stem":"一座城市的竞争力，从来不只体现在高楼大厦和GDP数字上。菜市场是否整洁、老旧小区有没有电梯、公交站台有没有遮阳棚、社区里有没有一张可供歇脚的长椅，这些看似琐碎的细节，恰恰构成了普通人对一座城市最直接的感受。一座真正有温度的城市，往往是把这些“小事”先办好。这段文字意在说明：","options":["城市竞争力主要取决于基础设施投入的总规模","民生细节是衡量城市治理水平和城市温度的重要标尺","城市发展应当把经济增长放在次要位置","老旧小区加装电梯是城市治理中最紧迫的课题"],"answer":1,"explain":"文段先否定“只看高楼和GDP”，再列举菜市场、电梯、遮阳棚等细节，末句点明“有温度的城市先办好这些小事”，意在说明民生细节是衡量城市治理水平与温度的标尺。A项与文意相反，C、D两项属过度推断。"}]},{"name":"数量关系","material":null,"questions":[{"id":"gd-2025-06","stem":"某工程若由甲队单独完成需要20天，由乙队单独完成需要30天。现先由甲队单独施工4天，余下工程全部交由乙队完成，则乙队还需要多少天？","options":["22天","24天","26天","28天"],"answer":1,"explain":"设工程总量为1，甲队工效为1/20，乙队工效为1/30。甲队施工4天完成4×1/20=1/5，剩余4/5；乙队单独完成需要(4/5)÷(1/30)=24（天）。故选24天。"},{"id":"gd-2025-07","stem":"甲、乙两地相距420千米。一辆客车从甲地开往乙地，速度为80千米/时；同时一辆货车从乙地开往甲地，速度为60千米/时。两车相遇时，客车比货车多行驶多少千米？","options":["40千米","50千米","60千米","70千米"],"answer":2,"explain":"两车相向而行，速度和为80+60=140（千米/时），相遇时间为420÷140=3（小时）。客车行驶80×3=240千米，货车行驶60×3=180千米，客车比货车多行240-180=60（千米）。"},{"id":"gd-2025-08","stem":"某单位从5名男员工和3名女员工中随机选出3人参加培训，要求选出的3人中至少有1名女员工，则共有多少种不同的选法？","options":["36种","45种","46种","56种"],"answer":2,"explain":"8人中任选3人共有C(8,3)=56种选法，其中全是男员工的选法有C(5,3)=10种。用总数减去不符合条件的情况，至少有1名女员工的选法为56-10=46（种），可避免分类讨论。"}]},{"name":"判断推理","material":null,"questions":[{"id":"gd-2025-09","stem":"观察下列一组图形：第一个图形是三角形，内部有3个小圆；第二个图形是正方形，内部有4个小圆；第三个图形是正五边形，内部有5个小圆；第四个图形是正六边形，内部有6个小圆。按照这一规律，第五个图形应当是：","options":["正七边形，内部有6个小圆","正七边形，内部有7个小圆","正八边形，内部有7个小圆","正六边形，内部有8个小圆"],"answer":1,"explain":"题干图形的外框依次为三角形、正方形、正五边形、正六边形，边数每次增加1；内部小圆数依次为3、4、5、6，与对应外框的边数相等。故第五个图形应为正七边形，且内部小圆数为7个，选B。"},{"id":"gd-2025-10","stem":"棘轮效应是指人的消费习惯形成之后具有不可逆性，即消费水平易于向上调整而难于向下调整，短期内尤为明显。根据上述定义，下列属于棘轮效应的是：","options":["小李每月工资到账后固定存下2000元，其余用于日常开支","小王收入提高后租住了更贵的房子，收入下降后仍不愿搬回原来的住处","小张为攒钱买房，主动把每天一杯的咖啡换成了白开水","小赵每逢打折季都会大量囤货，事后常常为冲动消费后悔"],"answer":1,"explain":"棘轮效应的关键是消费习惯“易上难下”、短期内不可逆。B项小王收入提高后租住更贵的房子，收入下降后仍不愿降低居住标准，符合“上去了下不来”的特征；A项是固定储蓄，C项是主动降低消费，D项属冲动消费，均不符合。"},{"id":"gd-2025-11","stem":"邻避效应是指垃圾处理厂、变电站等公共设施能够为社会带来整体利益，但所在地居民因担心其可能带来的负外部影响而采取抵制行为。根据上述定义，下列属于邻避效应的是：","options":["某小区居民担心垃圾焚烧厂影响健康和周边环境，联名要求另行选址","某企业因排放超标被生态环境部门责令停产并限期整改","某村村民因认为征地补偿标准过低而拒绝签署补偿协议","某社区居民自发组织垃圾分类宣传和桶前值守志愿服务活动"],"answer":0,"explain":"邻避效应有两个要件：设施整体上为社会带来利益，所在地居民因担心负外部性而抵制。A项居民因担心健康与环境问题联名要求垃圾焚烧厂另行选址，符合定义；B项是违法受罚，C项是补偿争议，D项是自愿公益，均不属于邻避效应。"},{"id":"gd-2025-12","stem":"工匠∶木器∶木材","options":["画家∶颜料∶画布","厨师∶菜肴∶食材","农民∶土地∶庄稼","作家∶出版∶书籍"],"answer":1,"explain":"题干为“劳动者—产品—原料”的关系：工匠以木材为原料制作木器。B项厨师以食材为原料制作菜肴，三者关系与题干一致。A项颜料是工具而非产品，C项土地是场所且庄稼是产物而非原料，D项出版是环节而非原料，均不匹配。"},{"id":"gd-2025-13","stem":"某市对校外培训机构开展专项治理，并明确规定：凡未通过重新审核登记的机构，一律不得继续开展培训业务。据此，下列哪一项一定为真？","options":["某机构不得继续开展培训业务，说明它未通过审核登记","某机构通过了审核登记，它就一定能继续开展培训业务","某机构仍在继续开展培训业务，说明它已通过审核登记","某机构没有申请参加审核登记，它一定可以继续开展培训业务"],"answer":2,"explain":"题干规定可表述为“未通过审核→不得开展培训”，其逆否命题“继续开展培训→已通过审核”必然为真，C项正确。A项肯定后件、B项否定前件都不能推出必然结论，D项与题干规定相矛盾。"},{"id":"gd-2025-14","stem":"某调查发现，经常参加社区志愿服务的居民，其邻里信任度评分明显高于很少参加志愿服务的居民。据此有人认为，参加社区志愿服务能够提升邻里之间的信任水平。以下哪项如果为真，最能削弱上述观点？","options":["部分居民参加社区志愿服务是为了获得积分或实物奖励","该社区的志愿服务内容主要是环境清扫和秩序维护","往往是原本就与邻居关系融洽、彼此信任的居民更愿意参加志愿服务","有受访居民表示，参加志愿服务后与邻居的交流明显增多"],"answer":2,"explain":"题干由“参加志愿服务者信任度更高”推出“志愿服务提升信任”，属于因果论证。C项指出本就信任邻居的人更愿意参加志愿服务，说明可能是信任促成参与，而非参与带来信任，属因果倒置，最能削弱。A、B项与因果关系无关，D项反而加强。"}]},{"name":"资料分析","material":"2025年，广东省某市持续推进稳就业、促增收工作，全年城镇新增就业13.3万人。该市技能人才队伍建设情况如下：\n2023年：技能人才总量196万人，其中高技能人才60万人；\n2024年：技能人才总量202万人，其中高技能人才66万人；\n2025年：技能人才总量210万人，其中高技能人才72万人。\n另据统计，2025年该市城镇新增就业人员中，制造业吸纳的就业人数占42%。","questions":[{"id":"gd-2025-15","stem":"2023年至2025年，该市高技能人才数量年均增长约多少万人？","options":["4万人","5万人","6万人","7万人"],"answer":2,"explain":"年均增长量等于末期值减初期值再除以间隔年数，即(72-60)÷(2025-2023)=12÷2=6（万人）。注意“年均增长量”用的是首末两年的差值除以年份间隔数，而不是各年增量简单平均。"},{"id":"gd-2025-16","stem":"2024年，该市高技能人才数占技能人才总量的比重约为：","options":["30.6%","32.7%","34.3%","35.2%"],"answer":1,"explain":"2024年高技能人才66万人，技能人才总量202万人，比重为66÷202≈32.7%。其中30.6%约为2023年的水平，34.3%约为2025年的水平，属于时间错位设置的干扰项。"},{"id":"gd-2025-17","stem":"2025年，该市城镇新增就业人员中，制造业吸纳的就业人数约为多少万人？","options":["4.8万人","5.6万人","6.2万人","7.0万人"],"answer":1,"explain":"2025年该市城镇新增就业13.3万人，制造业吸纳就业占比42%，则制造业吸纳就业13.3×42%=5.586≈5.6（万人）。计算时应以新增就业总量乘以比重，不能用技能人才总量来乘。"}]},{"name":"常识判断","material":null,"questions":[{"id":"gd-2025-18","stem":"在粤港澳大湾区建设中，地处珠海、以推动与澳门深度合作、促进澳门经济适度多元发展为主要定位的重大合作平台是：","options":["前海深港现代服务业合作区","横琴粤澳深度合作区","南沙粤港澳全面合作示范区","河套深港科技创新合作区"],"answer":1,"explain":"横琴粤澳深度合作区位于珠海，是推动与澳门深度合作、促进澳门经济适度多元发展的重要平台；前海、河套位于深圳，南沙位于广州，均与“珠海—澳门”的定位不符。故选横琴粤澳深度合作区。"},{"id":"gd-2025-19","stem":"下列广东代表性非物质文化遗产项目中，已被列入联合国教科文组织人类非物质文化遗产代表作名录的是：","options":["粤剧","广东醒狮","广绣","潮州木雕"],"answer":0,"explain":"粤剧于2009年列入联合国教科文组织人类非物质文化遗产代表作名录，是广东最具代表性的入选项目。广东醒狮、广绣、潮州木雕虽都是国家级非物质文化遗产，但并未被列入联合国教科文组织的这一名录。"},{"id":"gd-2025-20","stem":"下列关于广东省自然地理与区域发展格局的说法，正确的是：","options":["粤北地区以山地丘陵为主，森林覆盖率高，是全省重要的生态屏障","珠江三角洲是全省面积最大、以农牧业生产为主的区域","广东省的河流大多自西向东流，最终注入东海","雷州半岛位于广东省北部，与湖南省接壤"],"answer":0,"explain":"粤北以山地丘陵为主，森林覆盖率高，是全省重要的生态屏障，A项正确。珠三角经济发达、城镇化水平高，并非以农牧业为主；广东河流主要注入南海；雷州半岛位于广东西南部。故B、C、D三项错误。"}]},{"name":"科学推理","material":null,"questions":[{"id":"gd-2025-21","stem":"小明在实验室做凸透镜成像实验。他把一支点燃的蜡烛放在焦距为10厘米的凸透镜前30厘米处，在透镜另一侧的光屏上得到了清晰的像。关于这个像，下列说法正确的是：","options":["倒立、缩小的实像，与照相机的成像特点相同","倒立、放大的实像，与投影仪的成像特点相同","正立、放大的虚像，与放大镜的成像特点相同","正立、缩小的虚像，光屏上无法承接"],"answer":0,"explain":"凸透镜焦距f=10厘米，物距u=30厘米，满足u>2f。根据凸透镜成像规律，物距大于二倍焦距时成倒立、缩小的实像，像距位于f与2f之间，照相机就是依据这一原理工作的。u>2f时不可能成放大或正立的像，故B、C、D三项均错误。"},{"id":"gd-2025-22","stem":"蒸馒头时，面团中往往要加入适量的小苏打（碳酸氢钠）。加热蒸制的过程中，面团会逐渐变得疏松多孔，蒸出的馒头松软可口。其原因是：","options":["小苏打受热分解产生二氧化碳气体，气体在面团中形成许多小孔","小苏打受热熔化变成液体，冷却后把面团撑出空隙","小苏打与水反应生成氧气，氧气使面团膨胀","小苏打受热分解放出氮气，氮气使面团体积变大"],"answer":0,"explain":"碳酸氢钠受热分解生成碳酸钠、水和二氧化碳：2NaHCO₃→Na₂CO₃+H₂O+CO₂↑。二氧化碳在面团内形成大量气泡，使面团疏松多孔、体积膨胀。小苏打受热不产生氧气或氮气，也不是靠熔化撑开面团，故其余选项均错误。"},{"id":"gd-2025-23","stem":"把一株生长状况良好的绿色植物放入透明的密封容器中，先置于黑暗处一段时间。与放入时相比，容器内气体成分的变化最可能是：","options":["氧气浓度上升，二氧化碳浓度下降","氧气浓度下降，二氧化碳浓度上升","氧气和二氧化碳的浓度都上升","氧气和二氧化碳的浓度都不变"],"answer":1,"explain":"黑暗中植物不能进行光合作用，但呼吸作用时刻都在进行。呼吸作用消耗氧气并产生二氧化碳，因此密闭容器内氧气浓度逐渐下降、二氧化碳浓度逐渐上升。选项中“氧气上升、二氧化碳下降”是光合作用强于呼吸作用时的表现，“都不变”则忽视了呼吸作用的持续进行。"}]},{"name":"政治理论","material":null,"questions":[{"id":"gd-2025-24","stem":"“照抄照搬别国经验、别国模式，从来不能得到成功。”一个国家走什么样的道路，只能由这个国家的人民根据本国国情去探索和决定。这一论断最直接体现的马克思主义基本原理是：","options":["矛盾的普遍性与特殊性相互联结，必须把普遍原理与本国具体实际相结合","量变是质变的必要准备，质变是量变的必然结果","社会意识具有相对独立性，有时会落后于社会存在","生产力决定生产关系，生产关系反作用于生产力"],"answer":0,"explain":"马克思主义揭示的是普遍规律，各国国情则各有其特殊性。照抄照搬别国模式不能成功，就在于只承认普遍性而否认特殊性；依据本国国情探索道路，正是把矛盾普遍性与特殊性统一起来。B、C、D三项与题意不构成最直接对应。"},{"id":"gd-2025-25","type":"multi","stem":"推进实践基础上的理论创新，必须把握好习近平新时代中国特色社会主义思想的世界观和方法论，坚持好、运用好贯穿其中的立场观点方法。下列表述属于这一立场观点方法的有：","options":["必须坚持人民至上","必须坚持自信自立","必须坚持守正创新","必须坚持以外部模式为主导"],"answer":[0,1,2],"explain":"这一世界观和方法论被概括为“六个必须坚持”，即必须坚持人民至上、自信自立、守正创新、问题导向、系统观念、胸怀天下，前三项均在其中。D项主张以外部模式为主导，背离了自信自立和独立自主的要求，不属于这一立场观点方法。故本题选A、B、C。"},{"id":"gd-2025-26","type":"judge","stem":"判断：实践是检验真理的唯一标准，凡是经过实践检验并被证明为正确的认识，都是真理。","options":["正确","错误"],"answer":0,"explain":"真理是标志主观与客观相符合的哲学范畴，实践是联结主观与客观的桥梁，只有实践才能把主观认识与客观实际加以对照，因而实践是检验真理的唯一标准。经过实践检验并被证明为正确的认识符合客观实际，就是真理。故该说法正确。"}]}]},{"id":"gd-sl-2023","title":"2023年广东省公务员录用考试《申论》（模拟卷）","region":"广东省","examType":"广东省考","subject":"申论","year":2023,"duration":150,"totalScore":100,"kind":"essay","note":"本卷为依据历年真题题型结构编写的原创模拟题，非官方真题原文，仅供练习。","materialTitle":"给定资料","material":"给定资料1\n广东省委、省政府部署实施“百县千镇万村高质量发展工程”，把县镇村发展摆在突出位置。A镇是粤东山区的一个传统农业镇，户籍人口四万余人，常住人口却不足两万。镇干部老陈说，镇里最头疼的是“三块地”：撂荒地多，年轻人不愿种；宅基地散，村庄建设难规划；集体建设用地少，招来的项目落不下。镇里曾引进一家农产品加工企业，厂房建到一半，因为用地手续和污水处理配套跟不上，项目最终搁置。村民李大姐说，家里几亩地种一年不如出去打工一个月，“种地不赚钱，谁还愿意守着田？”\n\n类似情况在其他地方也不同程度存在。有的县产业基础薄弱，规上企业数量少，产业链短，附加值低，农产品大多以原料形式外销，加工转化率不高；有的镇公共服务供给不足，教育、医疗资源向城区集中，“村里看病要跑几十公里”；有的村集体经济“空壳化”，一年到头收入寥寥，想为群众办事却没有钱。省里一位调研人员坦言，城乡区域发展不平衡，是广东高质量发展必须迈过的一道坎。\n\n给定资料2\nB市L镇的做法提供了另一种可能。L镇过去以种植水稻为主，近年来立足本地资源，把“一颗果子”做成了大产业。镇里成立产业发展专班，编制全产业链规划，引进龙头企业建设标准化种植基地，配套建设分拣中心、冷链仓储和精深加工车间，鲜果销售期由两个月延长到全年。企业负责人说，农户以土地经营权入股合作社，合作社与企业签订保底收购协议，农户既有租金、又有股金，还能在基地务工挣薪金，“一份土地三份收入”。\n\n在销售端，L镇组织返乡青年成立电商团队，把直播间搬进果园，通过短视频讲述果农故事；镇里还统一注册区域公用品牌，制定分级分选标准，好果子卖出好价钱。如今，全镇果农户均增收明显，村集体收入稳步提升，过去外出务工的年轻人陆续回乡创业。不过，L镇党委书记也坦言，目前产业链条仍偏短，精深加工产品不多，品牌影响力主要局限在省内；一旦市场价格波动，农户抗风险能力依然偏弱，“产业能不能立得住，还要看链条扎得深不深”。\n\n给定资料3\nC县把农村人居环境整治作为“百千万工程”的先手棋。县里推行“积分制”，村民参与清扫保洁、垃圾分类、绿化管护可以攒积分，积分能在村口“积分超市”兑换生活用品；各村把“门前三包”写入村规民约，成立由老党员、乡贤组成的监督小组，定期开展“美丽庭院”评比。几年下来，村道干净了，河沟清了，房前屋后种上了果树和花草，村容村貌明显改观。\n\n但整治过程中也出现了一些值得注意的现象。有的村为了迎检，集中突击清理，检查一过就恢复原样；有的地方一味追求“高大上”，把村口建成景观大道，却挤占了村民晾晒、停车的空间，群众有意见；还有的村干部抱怨“我们干得热火朝天，群众却站在边上看”，环境卫生的日常维护主要靠村干部和保洁员，村民主动参与的积极性不高。县农业农村局一位同志说，环境整治不是“一阵风”，关键要找到让群众愿意参与、能够持续的办法，“村容村貌是面子，群众认同是里子”。\n\n给定资料4\nD镇E村曾经是一个典型的“空心村”，常住人口以老人和儿童为主。转机出现在两年前，镇里实施“乡村CEO”引才计划，面向社会公开选聘懂经营、善管理的乡村职业经理人，由村集体提供资源，经理人负责运营，收益按约定比例分成。返乡青年小林通过选聘成为E村的第一位“乡村CEO”。他盘活村里闲置的老屋和山地，打造民宿集群和研学基地，把村里的竹子、蜂蜜、时令蔬果做成伴手礼，一年下来为村集体带来可观收入，还带动不少村民在家门口就业。\n\nE村的变化不止于经济。镇里同步推进“数字乡村”建设，村里的党务、村务、财务在手机端公开，重大事项由村民议事会商议，村民扫码就能提意见、看进度。村支书说，过去开会要挨家挨户通知，现在线上议一议，参与的人反而多了。不过，E村的探索也遇到烦恼：请来的经理人留不住，有的干满一年就走；村里懂直播、懂财务的年轻人依然紧缺；民宿旺季一房难求，淡季却门可罗雀，配套的道路、停车、污水处理还跟不上。小林说，乡村需要有奔头，年轻人愿意来，也要留得下。\n\n给定资料5\n省里召开“百千万工程”推进会，与会人员围绕如何把这项工程做深做实展开讨论。有人认为，广东各县资源禀赋差异大，不能“一个模子刻到底”，要因地制宜、分类施策，宜农则农、宜工则工、宜游则游。有人提出，产业发展要更多把农民嵌进链条，让农民更多分享增值收益，避免“企业赚钱、农民旁观”。还有人强调，要把基础设施和公共服务补起来，路、水、电、网、冷链一起抓，教育、医疗、养老一起上，让县镇村既有“颜值”更有“里子”。\n\n会议形成共识：实施“百千万工程”，要在县域内统筹城乡，把县的优势、镇的特点、村的资源更好统筹起来，推动城乡融合发展；要建管并重，既要建得好，更要管得久、用得活；要充分尊重农民意愿，把群众从“旁观者”变成“参与者”“受益者”。一位负责同志说，县域活则全省活，乡村兴则全省兴。工程能不能落地见效，最终要看群众的获得感成色足不足。","questions":[{"id":"gd-sl-2023-1","stem":"根据给定资料1~3，概括当前广东推进“百县千镇万村高质量发展工程”过程中存在的主要问题。\n要求：全面、准确、条理清晰，分条作答；不超过300字。（20分）","limit":300,"score":20,"answer":"【参考要点】\n1.产业基础薄弱。规上企业少，产业链短、附加值低，农产品多以原料外销，加工转化率不高；项目落地受用地手续、污水处理等配套制约。\n2.要素保障不足。撂荒地多、宅基地分散、集体建设用地少，好项目落不下；镇村财力弱，部分村集体经济“空壳化”，办事缺钱。\n3.公共服务存在短板。教育、医疗资源向城区集中，群众看病、上学不便。\n4.环境整治长效不足。存在突击迎检、检查一过就反弹的现象；个别地方重“面子”轻实用，挤占村民生活空间。\n5.群众参与不够。日常维护主要靠村干部和保洁员，村民主动性不高，呈现“干部干、群众看”。\n\n【评分参考】\n本题20分，按点赋分，答出5个要点即可得满分，每点约4分；要点须来自给定资料1~3，同义表述、合并作答均可。条理清晰、分条书写、语言准确可得结构分。\n常见失分：只罗列零散现象而不作概括提炼；脱离资料凭空发挥；照抄原文大段堆砌；超出规定字数或漏答要点。"},{"id":"gd-sl-2023-2","stem":"给定资料4介绍了D镇E村选聘“乡村CEO”、激活乡村资源的做法。假如你是D镇“百千万工程”指挥部办公室的工作人员，请根据给定资料4，就E村的经验写一份经验交流材料，供全镇各村参考。\n要求：紧扣资料，内容具体，条理清晰，语言流畅，有可操作性；不超过500字。（30分）","limit":500,"score":30,"answer":"【参考要点】\n标题：关于E村选聘“乡村CEO”激活乡村资源的经验交流材料\n\n一、主要做法\n1.公开引才。实施“乡村CEO”引才计划，面向社会选聘懂经营、善管理的乡村职业经理人。\n2.明晰权责。村集体提供资源，经理人负责运营，收益按约定比例分成，实现责权利相统一。\n3.盘活资源。盘活闲置老屋和山地，发展民宿集群、研学基地，把竹子、蜂蜜、时令蔬果做成伴手礼。\n4.联农带农。村集体收入增加，村民在家门口就业，共享发展成果。\n5.数字治理。同步推进“数字乡村”，党务、村务、财务手机端公开，重大事项由村民议事会商议，扫码可提意见、看进度。\n\n二、启示建议\n1.因地制宜盘活闲置资产，宜游则游、宜农则农。\n2.完善利益联结与激励机制，让人才留得下、干得久。\n3.培育本土人才，补齐直播、财务等能力短板。\n4.统筹配套道路、停车、污水处理，破解淡旺季失衡。\n\n【评分参考】\n本题30分。格式5分：有标题，符合经验交流材料口吻，无称谓、落款不扣分。内容20分：做法4~5点、启示建议3~4点，每点2~3分，须源于给定资料4。语言5分：条理清晰、语句通顺、字数达标。\n常见失分：写成议论文或情况汇报；大段照抄原文；只写做法、不提启示；缺少可操作性对策；超字数明显。"},{"id":"gd-sl-2023-3","stem":"给定资料5中提到：“县域活则全省活，乡村兴则全省兴。”请结合给定资料，联系实际，自拟标题，写一篇文章。\n要求：（1）观点明确，见解深刻；（2）内容充实，结构完整；（3）语言流畅，书写工整；（4）不拘泥于给定资料，不得抄袭给定资料；（5）1000~1200字。（50分）","limit":1200,"min":1000,"score":50,"answer":"【参考范文】\n\n以县镇村之兴 筑南粤高质量发展之基\n\n县域是城乡融合的纽带，镇村是岭南大地的根脉。广东经济总量长期位居全国前列，但城乡区域发展不平衡，始终是必须迈过的一道坎。A镇的土地撂荒、C县整治之后的反弹、E村人才“引得来却留不住”，都在提醒我们：没有县镇村的全面振兴，就没有全省的高质量发展。扎实推进“百县千镇万村高质量发展工程”，正当其时、意义深远。\n\n产业是根基，要以特色产业激活县域经济。产业不兴，一切无从谈起。A镇有资源、有热情，却因用地手续和污水处理配套跟不上，项目半途搁置，说明发展不能只靠一腔热血，更要靠扎实的要素保障；L镇把“一颗果子”做成全产业链，让农户收租金、分股金、挣薪金，说明找准路子、延链补链、联农带农，土特产也能长成大产业。广东各县资源禀赋不同，最忌“一个模子刻到底”。要因地制宜、分类施策，宜农则农、宜工则工、宜游则游；要立足县域统筹布局，把加工、冷链、销售等环节尽量留在县镇，让更多增值收益留在农村、留给农民。唯有如此，县域经济才能立得住、走得远。\n\n环境是底色，要以建管并重提升乡村品质。乡村振兴，既要“颜值”，更要“里子”。C县推行积分制，把“门前三包”写进村规民约，村容村貌明显改观，群众也得了实惠；而个别村庄突击迎检，检查一过就恢复原样，或一味追求“高大上”，却挤占村民晾晒、停车的空间，反而伤了民心。这说明，环境整治不能靠“一阵风”，更不能搞“形象工程”。要把群众满意作为标尺，尊重村民意愿，多办雪中送炭的实事；要建立长效机制，让管护有人、有钱、有制度，让好环境长长久久、让好日子实实在在。\n\n人才是关键，要以治理创新激发内生动力。乡村的活力，归根结底在人。E村选聘“乡村CEO”，盘活闲置老屋和山地，村集体和村民双双受益，靠的正是“专业的人干专业的事”；但经理人干满一年就走、懂直播懂财务的年轻人紧缺，也暴露出引才用才机制的短板。要让人才愿意来、留得下，既要给舞台、给收益，也要补齐道路、停车、污水处理等配套，让乡村真正有奔头；要用好“数字乡村”，把党务、村务、财务晒在阳光下，让村民从“旁观者”变成“参与者”，把外部帮扶转化为内生动力。\n\n“县域活则全省活，乡村兴则全省兴。”县镇村的振兴，不是一朝一夕之功，也非一人一部门之责。既要有政府的引导和支持，也要有市场的力量和农民的参与；既要抓产业发展、环境整治，也要抓公共服务、人才培养和基层治理。唯有着眼长远、建管并重、久久为功，把每一项工作都做到群众心坎上，才能让县镇村真正强起来、活起来，为广东在推进中国式现代化建设中走在前列筑牢坚实根基。\n\n【写作提示】\n1.立意角度：围绕“百千万工程”与广东高质量发展，抓住“县、镇、村”三个层级，落点在城乡区域协调发展与共同富裕。可从“产业、环境、人才治理”三个维度展开，也可从“因地制宜、联农带农、建管并重、城乡融合”切入，关键是把“县域活、乡村兴”与全省发展大局贯通起来。\n2.结构安排：建议采用“总—分—总”。开头由现实问题或金句引出总论点；主体设三个分论点，每段按“观点句+资料例证+简要分析+对策结论”展开，注意结合而不拘泥于给定资料，可补充身边鲜活事例；结尾回扣主题，升华到中国式现代化的广东实践。\n3.注意事项：标题要准确凝练，避免“论百千万工程”一类空泛表述；分论点句式力求整齐，语言平实有力；切忌大段照抄给定资料；字数控制在1000~1200字，卷面工整。"}]},{"id":"gd-sl-2024","title":"2024年广东省公务员录用考试《申论》（模拟卷）","region":"广东省","examType":"广东省考","subject":"申论","year":2024,"duration":150,"totalScore":100,"kind":"essay","note":"本卷为依据历年真题题型结构编写的原创模拟题，非官方真题原文，仅供练习。","materialTitle":"给定资料","material":"给定资料1\n广东部署推进绿美广东生态建设，提出持续提升生态系统质量，让绿色成为高质量发展的鲜明底色。A镇地处粤北山区，林地面积占全镇面积七成以上。镇干部老周说，前些年镇里造林热情很高，一年下来种下不少苗木，可成活率并不理想，“春天种、夏天黄、秋天当柴烧”。原因之一是选苗图省事，多用速生树种，土层薄、坡度大的山场也照种不误；种完就交给村里，既没有专人管护，后续补植和抚育的资金也接不上。村民陈伯指着后山说，那片林子看着绿，其实林相单一，松树一多，病虫害就找上门，“一场虫、一场火，几年功夫就白费了”。\n\n类似情况在其他地方也时有发生。有的地方把绿化简单等同于“种树”，乡村道路两旁栽得整整齐齐，却挤占了排水沟和会车空间，村民颇有意见；有的村把古树名木当成“拦路石”，修路建房时随意移栽甚至砍伐；有的地方绿化资金主要靠上级项目，“钱来了就干、钱没了就停”，管护队伍不稳定，村民参与度不高。省里一位林业技术人员说，绿化不是挖坑栽树就完事，“种得下，更要管得住、长得好”。\n\n给定资料2\nB市曾是内河涌黑臭问题较为突出的城市之一。近年来，市里实施水环境综合治理，打出“控源截污、清淤活水、生态修复、长效管护”的组合拳：新建改造污水管网，推动小区、城中村雨污分流；清理河涌底泥，引活水入城，沿河建设贯通连续的碧道；把河长制从“有名”做到“有实”，市县镇村四级河长定期巡河，问题清单网上公开、销号管理。几年下来，几条主要河涌水质明显改善，岸边成了市民散步跑步的好去处，沿河的老旧厂房也改造成了文创空间和小型咖啡馆。\n\n但治理中也暴露出短板。有的片区管网改造只做了主干管，小区内部的雨污分流没有跟上，一到雨天污水还是直排河涌；有的碧道建得漂亮，配套的厕所、照明、停车跟不上，热闹一阵就冷清下来；有的镇把河涌治理当成“一次性工程”，验收之后管护责任悬空，垃圾漂浮、水草疯长的问题时有反弹。市生态环境局一位干部坦言，水环境治理“问题在水里，根子在岸上”，“治好一条河不难，难的是让它一直清下去”。\n\n给定资料3\nC县是全省较早推行生活垃圾分类的县。县里在县城和乡镇同步铺开，居民小区设置分类投放点、配备督导员，在早晚投放高峰现场指导；推行“积分兑换”，分类准确可以攒积分，用来换米面油和日用品。可回收物由专业企业上门收运，厨余垃圾就地就近处理，有害垃圾单独暂存、定期转运。县里还建起再生资源分拣中心，推动环卫清运网与再生资源回收网“两网融合”，一批废旧家具、旧家电有了去处。\n\n不过，推行过程中难题不少。有的居民嫌麻烦，“一个袋子装到底”，督导员一走就混投；有的小区前端分得挺细，中端却是一辆车装走、一车运到填埋场，群众看到后直言“白分了”；有的乡镇末端处理设施选址困难，周边村民担心异味和渗滤液，“谈建色变”，项目迟迟落不了地；个别村庄把垃圾往山边、河边一堆了之，靠保洁员定期清理，治标不治本。县里一位负责人说，垃圾分类是“最难的习惯革命”，“设施建得起来，习惯养不起来，照样转不动”。\n\n给定资料4\nD市老城区建筑密集、绿地稀缺，居民休闲活动空间不足。近年来，市里从“边角地”入手，把桥下空间、闲置厂房、街角空地和废弃花坛改造成“口袋公园”，见缝插绿、拆墙透绿，配套座椅、步道、健身器材和儿童游乐设施，让居民推窗见绿、出门入园。改造之前，社区召开“板凳会”“议事会”，请居民提意见：老人希望有树荫和长椅，年轻人想要健身场地，家长关心孩子的活动安全。有的社区还组织居民认养花木、轮流打理，把一块块荒废地变成了大家共同维护的“小花园”。\n\n微更新过程中也出现了一些值得注意的现象。有的地方一味追求“网红”效果，铺装讲究、灯光炫目，却没有遮阴的树、没有坐的地方，老人不愿去；有的改造挤占了原有的停车位和晾晒空间，居民意见不小；有的公园建成后无人管护，草皮被踩秃、设施锈蚀损坏，没多久就荒废了；还有的项目由部门单方面拍板，居民直到施工才知道家门口的树被移走了。一位社区干部说，微更新不能“干部干、群众看”，“群众点单、共同维护，改出来的地方才用得久”。\n\n给定资料5\n绿美生态建设也给不少地方带来新的发展机遇。E县山多林密，过去“守着青山过穷日子”。近年来，县里探索生态产品价值实现路径：发展林下种植养殖，培育森林康养、生态研学等新业态，把好山好水变成好风景、好收益；探索林业碳汇、碳普惠等机制，让村集体和农户从护林育林中得到实实在在的回报。一些村庄发展生态旅游，村民开起民宿、卖起山货，护林员成了“生态向导”。不过也有干部提醒，生态价值转化不能“一哄而上”，有的地方缺乏规划和承载能力评估，游客一多，垃圾、污水、停车问题随之而来，反而伤了生态。\n\n座谈会上，与会人员围绕如何深入推进绿美广东生态建设展开讨论。有人认为，绿化不能只看种了多少树，更要看活了多少、群众受益多少；有人提出，要把生态治理与产业发展、人居环境整治统筹起来，让好生态有好“钱景”；还有人强调，要倡导绿色低碳生活方式，从垃圾分类、节水节电、绿色出行这些身边小事做起。会议形成共识：绿美广东生态建设，既要有生态的“含绿量”，也要有发展的“含金量”；既要种得下、管得住，更要让群众看得见、得实惠。","questions":[{"id":"gd-sl-2024-1","stem":"根据给定资料1~3，概括当前广东推进绿美广东生态建设中存在的主要问题。\n要求：全面、准确，条理清晰，分条作答；不超过300字。（20分）","limit":300,"score":20,"answer":"【参考要点】\n1.造林绿化重数量轻质量。选苗图省事，树种单一、林相单调，土层薄、坡度大的山场也照种；重种轻管，缺少专人管护和后续补植抚育资金，成活率不高，易生病虫害和火灾。\n2.绿化实施不够科学。把绿化简单等同于“种树”，挤占排水沟和会车空间；随意移栽甚至砍伐古树名木；资金依赖上级项目，“钱来了就干、钱没了就停”，管护队伍不稳定。\n3.水环境治理不够彻底。管网改造只做主干管，小区内部雨污分流未跟上，雨天污水直排；碧道厕所、照明、停车等配套不足；工程验收后管护责任悬空，垃圾漂浮、水草疯长出现反弹。\n4.垃圾分类成效不稳固。居民混投，督导员一走就反弹；前端分类、中端混装混运，群众认为“白分了”；末端处理设施选址难、遭“邻避”；个别村庄垃圾乱堆，靠保洁员清理治标不治本。\n5.群众参与和长效机制不足。绿化、垃圾分类、河涌管护主要靠干部和专业人员，群众主动性不高，呈现“干部干、群众看”；长效管护的制度、资金、责任落实不到位。\n\n【评分参考】\n本题20分，按点赋分，答出5个要点即可得满分，每点约4分；要点须来自给定资料1~3，同义表述、合并作答均可，分条书写、语言准确可得结构分。\n常见失分：只罗列零散现象而不作概括提炼；脱离资料凭空发挥；大段照抄原文；超出规定字数或要点遗漏。"},{"id":"gd-sl-2024-2","stem":"给定资料3、5介绍了生活垃圾分类和绿色低碳生活方式方面的探索。假如你是B市生态环境局的一名工作人员，请根据给定资料3、5，面向全市市民写一份“践行绿色低碳生活 共建绿美家园”倡议书，倡导市民从身边小事做起，共同参与绿美广东生态建设。\n要求：紧扣资料，内容具体，条理清晰，语言得体，有号召力；不超过500字。（30分）","limit":500,"score":30,"answer":"【参考要点】\n标题：践行绿色低碳生活 共建绿美家园——致全市市民的倡议书\n称谓：广大市民朋友们\n开头：说明绿美广东生态建设的意义，指出垃圾分类是“最难的习惯革命”，绿色低碳要从身边小事做起，发出倡议。\n倡议事项：\n1.践行垃圾分类。家中分类、准确投放，配合督导员指导，参与积分兑换；不混装混投，共同抵制“前分后混”。\n2.节约资源能源。随手关灯关水，节约用电用纸，减少一次性用品，废旧家具家电交由正规渠道回收。\n3.坚持绿色出行。短途步行、骑行，优先乘坐公共交通，少开一天车。\n4.爱护身边环境。不乱堆乱倒垃圾，参与社区植绿护绿、认养花木和口袋公园管护。\n5.参与监督共治。发现混装混运、垃圾乱倒、污水直排等问题及时反映，做绿美家园的守护者。\n结尾：号召市民从今天做起、从点滴做起，让绿色成为生活底色。\n落款：B市生态环境局及日期。\n\n【评分参考】\n本题30分。格式5分：有标题、称谓、正文、号召结尾、落款（单位和日期），缺项酌扣。内容20分：倡议事项4~5条，每条4分左右，须源于给定资料3、5，具体可行，有号召力、语言得体。语言5分：条理清晰、语句通顺、字数达标。\n常见失分：写成议论文或工作总结；只讲意义不提具体做法；照抄资料原文；缺少称谓或落款；明显超出字数。"},{"id":"gd-sl-2024-3","stem":"给定资料5中提到：“绿美广东生态建设，既要有生态的‘含绿量’，也要有发展的‘含金量’。”请结合给定资料，联系实际，自拟标题，写一篇文章。\n要求：（1）观点明确，见解深刻；（2）内容充实，结构完整；（3）语言流畅，书写工整；（4）不拘泥于给定资料，不得抄袭给定资料；（5）1000~1200字。（50分）","limit":1200,"min":1000,"score":50,"answer":"【参考范文】\n\n厚植生态底色 提升发展成色\n\n绿水青山是广东最宝贵的家底。从粤北连绵的林地到珠三角纵横的河涌，从城市街角的“口袋公园”到乡村房前屋后的绿树繁花，绿美广东生态建设正在改变南粤大地的面貌。然而，A镇“春天种、夏天黄”的尴尬、B市河涌治理的反弹、C县垃圾分类“白分了”的抱怨都在说明：生态建设不能满足于种了多少树、建了多少设施，而要实现生态“含绿量”与发展“含金量”的同步提升。\n\n提升“含绿量”，要在科学和长效上下功夫。绿化不是挖坑栽树就完事，树种选得对不对、后期管不管得住，直接决定成效。A镇选苗图省事、重种轻管，林相单一、病虫害频发，几年功夫白费，教训不可谓不深。这就要求我们尊重自然规律，因地制宜选育乡土树种，宜林则林、宜草则草；健全管护机制，明确责任人、稳定资金渠道，把补植抚育、防火防虫做到日常；坚决纠治挤占排水沟、随意移栽古树名木等做法，让绿色长得久、立得住。种得下更要管得住，绿美才能真正落地。\n\n提升“含金量”，要在转化和惠民上做文章。好生态不应只是“看得见的风景”，还应当是“摸得着的收益”。E县发展林下种植养殖，培育森林康养、生态研学，探索林业碳汇和碳普惠，让村集体和农户从护林育林中得实惠，护林员成了“生态向导”，生动诠释了“绿水青山就是金山银山”。但转化不能“一哄而上”，必须做好规划与承载能力评估，防止游客一多，垃圾、污水、停车问题随之而来，反而伤了生态。要在保护优先的前提下，把生态优势转化为产业优势、发展优势，让群众在护绿中增收、在增绿中受益。\n\n提升“含绿量”和“含金量”，还要在共治共享上求突破。生态建设是全民事业，不能“干部干、群众看”。B市把河长制从“有名”做到“有实”，问题清单网上公开、销号管理，靠的是责任落地；C县推行积分兑换、配备督导员，D市改造口袋公园前开“板凳会”“议事会”，靠的是群众参与。反之，前端分得细、中端混装混运，或者建成后无人管护，都会消耗群众的信任和热情。要畅通参与渠道，把群众从“旁观者”变成“参与者”“监督者”，让垃圾分类、节水节电、绿色出行成为生活习惯，让共建共治共享成为生态建设的常态。\n\n绿美广东，美在山川，实在民生。生态“含绿量”是底色，发展“含金量”是成色，两者相辅相成、不可偏废。只要我们既守护好绿水青山，又善于把生态优势转化为发展胜势，既靠制度管长远，又靠群众聚合力，就一定能让南粤大地天更蓝、山更绿、水更清，让人民群众在绿美家园中收获更多幸福感。\n\n【写作提示】\n1.立意角度：紧扣“含绿量”与“含金量”的辩证关系，落点在绿美广东生态建设与高质量发展、民生福祉的统一。可从“科学绿化与长效管护”“生态价值转化”“全民共治共享”三个维度展开，也可从“保护与发展”“建设与管护”“政府与群众”几对关系切入。\n2.结构安排：建议采用“总—分—总”。开头由金句或现实问题引出总论点；主体设三个分论点，每段按“观点句+资料例证+分析+对策”展开，可适当补充身边事例；结尾回扣主题，升华到人与自然和谐共生。\n3.注意事项：标题要凝练准确，避免“论绿美广东”一类空泛表述；结合而不拘泥于给定资料，切忌大段照抄；分论点句式尽量整齐，语言平实有力；字数控制在1000~1200字，卷面工整。"}]},{"id":"gd-sl-2025","title":"2025年广东省公务员录用考试《申论》（模拟卷）","region":"广东省","examType":"广东省考","subject":"申论","year":2025,"duration":150,"totalScore":100,"kind":"essay","note":"本卷为依据历年真题题型结构编写的原创模拟题，非官方真题原文，仅供练习。","materialTitle":"给定资料","material":"给定资料1\n广东坚持制造业当家，把发展经济的着力点放在实体经济上，推动制造业高端化、智能化、绿色化发展。A市是珠三角一座以家电、五金、灯具等传统制造见长的城市，制造业企业众多，但规上企业占比不高。市工信局一位干部说，不少企业仍停留在“接单—加工—交货”的老路上，产品同质化严重，利润薄得像纸；百亿级企业屈指可数，多数中小企业规模小、链条短，处在价值链中低端。\n\n在老城区的一处工业园里，老周经营着一家五金厂。老周靠十几台冲床起家，厂里设备老旧，订单多来自外贸公司，价格一年比一年低。“一台设备用了十几年，不是不想换，实在算不过账。”老周说，换一条自动化产线要投入几百万元，厂房还是租的，银行不敢放贷，只能一年一年往后拖。车间里，四十多岁的老师傅占了大半，年轻人干不满三个月就走，“机器能买，会调机器的人难找”。市里调研发现，有的企业担心“不改造等死、改造找死”，不敢投；有的改造后设备连了网、数据上了云，却不会用，系统闲置成摆设；还有的想招懂工艺又懂数据的复合型人才，开出较高薪酬依然乏人问津。一家纺织企业负责人说，他们最缺的不是资金，而是“看得懂图纸、也看得懂代码”的人。\n\n给定资料2\n与A市的焦虑不同，同处珠三角的B市把功夫下在了“链”上。B市智能装备产业园里，链主企业华擎公司是做工业机器人的整机厂商，产值规模居行业前列。过去，华擎的核心零部件大多从外地甚至国外采购，交货周期长、成本高，供应链一有波动就被“卡脖子”。市里围绕华擎梳理上下游配套清单，缺什么引什么，建起电机、减速器、控制器等专业配套区，引导本地中小企业“卡位入链”。\n\n华擎把非核心的机加工、钣金件交给本地供应商，自己腾出手来攻关键技术；向配套企业开放图纸标准、检测设备和试验平台，派工程师驻厂帮带，帮供应商把合格率提上来。“以前是压价，现在是陪跑。”华擎供应链负责人说，供应商能力上来了，整机成本反而降了，交付也更稳。园区里，一批专精特新中小企业由此成长，有的在细分领域做到全国前列。\n\n不过，B市的探索也有隐忧。市发改局一位同志坦言，园区里真正掌握核心技术的企业还是少数，部分配套企业名义上“入链”，实际只做低端代工，整机订单减少就最先受冲击；还有的企业“小而散”，研发投入偏低，专利多集中在外观和实用新型，发明专利不多。“链主强不等于链条强，链条长不等于链条壮。”这位同志说，下一步要在“强链”上下功夫。\n\n给定资料3\n传统产业不是落后产业。C市D区是全国知名的纺织服装产业集群地，几千家中小企业扎堆，过去靠“低价格、大批量”闯市场，日子并不好过。D区的破题办法是推动集群整体数字化改造。区里搭建面向中小企业的工业互联网平台，汇聚订单、产能、设备数据，缺单的企业可以“接单”，产能富余的可以“派单”；平台还提供共享打版、检测、仓储等服务，中小企业不用自己建，按需付费就能用。\n\n区里还挑选了一批愿意改、有条件改的企业做示范。一家针织企业上了智能排产系统后，交期由经常延误变为准时交付，库存积压明显减少，用工也省了下来。企业负责人说，改造不是把机器人都搬进来，而是先把流程理顺，“先算账、再上设备，一步一步来”。针对部分企业“不会用”的问题，区里组织服务商上门“诊断”，先出方案再定投入，还办起面向车间主任、班组长的培训班，把数据看板怎么读、异常怎么处理讲清楚。\n\n变化是明显的，但难题依然不少。区工信部门一位同志说，改造成本对中小企业仍是不小的负担，回收周期偏长；不同厂商的系统接口不统一，数据互通困难，企业怕被“锁死”；更让人头疼的是数据安全，有的企业担心订单、工艺数据外泄，宁可不上平台。此外，服务商水平参差不齐，个别“卖完软件就走人”，后续维护跟不上，影响了企业改造的信心。\n\n给定资料4\n产业要升级，人是根本。E市是广东重要的制造业基地，技能人才缺口大。市里推动产教融合，支持职业院校与龙头企业共建产业学院，把课堂搬进车间，把生产线搬进学校。在E市职业技术学院，学生入学第一年打基础，第二年进校企共建的实训中心，第三年直接到企业顶岗实习，毕业就能上手。学院一位老师说，过去教材几年不更新，学生学的和厂里用的“两张皮”；现在课程由校企共同开发，企业工程师定期来上课，教学与需求对上了。\n\n企业也在主动“造血”。一家精密制造企业与本地职业院校合作开设“订单班”，企业出设备、师傅、标准，学校出场地、师资、学生，毕业后定向到企业就业。企业人力资源负责人说，过去招人靠“抢”，现在靠“育”，员工的稳定性明显提高。市里还推行“新八级工”技能等级评价并与薪酬待遇挂钩，让一线技术工人有奔头；企业设立“首席技师”“技能大师工作室”，让老师傅带徒弟、传手艺。\n\n但产教融合推进得并不轻松。有职业院校反映，校企合作多是“学校热、企业冷”，企业担心影响生产、担心技术外泄，参与积极性不高；有的合作停留在挂牌、签协议，实训设备陈旧，学生练不上真活；有的“订单班”招生不易，家长和学生仍觉得“读职校低人一等”。一位企业负责人直言，技能人才成长需要时间，待遇上不去、上升通道不清晰，“培养出来也留不住”。\n\n给定资料5\n建设粤港澳大湾区，为广东制造业转型升级提供了广阔空间。近年来，珠三角与粤东粤西粤北的产业共建持续推进，一些企业把生产制造环节布局到粤东西北，把研发设计、总部管理留在珠三角，“总部+基地”“研发+生产”的分工格局逐步形成。一家从珠三角转移到粤西的企业负责人说，当地用地、用工成本相对较低，政府服务也在跟上，但物流、检测、模具等生产性服务业不够发达，部分零部件仍要回珠三角采购。\n\n粤港澳三地的产业协同也在深化。港澳高校在基础研究、国际规则对接上有优势，珠三角制造业门类齐全、配套完整，二者结合可以加快科技成果转化。有企业反映，与港澳高校合作的项目，从实验室成果到中试再到量产，环节多、周期长，中间缺资金、缺平台、缺懂产业化的人，“最后一公里”并不好走。\n\n省里召开制造业高质量发展座谈会，讨论热烈。有人认为，制造业当家不能只盯几个大项目，要把中小企业这支“大部队”带起来；有人提出，传统产业改造是“存量变革”，比新上项目见效慢，但空间更大，要有耐心和定力；还有人强调，政府和市场要各就其位，政府重在搭平台、优服务、给场景，不搞“拉郎配”，也不能一阵风。一位负责同志说，制造业是广东的厚实家底，也是必须守住的根基，能不能实现从“制造大省”到“制造强省”的跨越，关键看转型成色足不足。","questions":[{"id":"gd-sl-2025-1","stem":"根据给定资料1~3，概括当前广东推动制造业转型升级面临的主要困难。\n要求：全面、准确、条理清晰，分条作答；不超过300字。（20分）","limit":300,"score":20,"answer":"【参考要点】\n1.企业转型意愿与能力不足。产品同质化、利润薄，多处于价值链中低端；改造投入大、回收周期长，融资难，担心“不改造等死、改造找死”，不敢投。\n2.数字化应用不深。设备联网后不会用，系统闲置成摆设；系统接口不统一、数据难互通，企业怕被“锁死”，担心数据外泄而不敢上平台。\n3.人才支撑薄弱。缺懂工艺又懂数据的复合型人才，一线技工老化、年轻人留不住，招人难。\n4.产业链条不强。核心技术与发明专利偏少，研发投入偏低，部分配套企业只做低端代工，“链主强不等于链条强”。\n5.服务体系不优。服务商水平参差不齐，后续维护跟不上，影响企业改造信心。\n\n【评分参考】\n本题20分，按点赋分，答出5个要点即可得满分，每点约4分；要点须来自给定资料1~3，同义表述、合并作答均可，分条书写、条理清晰可得结构分。\n常见失分：只堆砌现象不作概括提炼；脱离资料凭空发挥；大段照抄原文；只写困难不谈表现；明显超出规定字数或要点遗漏。"},{"id":"gd-sl-2025-2","stem":"给定资料2中提到：“链主强不等于链条强，链条长不等于链条壮。”请根据给定资料，谈谈你对这句话的理解。\n要求：观点明确，分析深入，条理清晰；不超过500字。（30分）","limit":500,"score":30,"answer":"【参考要点】\n1.亮明观点。这句话指出了当前制造业产业链建设中的认识误区：个别龙头企业的强，不等于整个链条的强；链条环节多、企业多，也不等于链条有竞争力、抗风险能力强。发展制造业必须在“强链”上做文章。\n2.释义一：“链主强不等于链条强”。资料二中B市引进链主企业华擎，带动一批配套企业“卡位入链”，但真正掌握核心技术的企业仍是少数，部分配套企业名义上入链、实际只做低端代工，整机订单减少时最先受冲击。可见龙头强而配套弱，链条不稳，随时可能被“卡脖子”。\n3.释义二：“链条长不等于链条壮”。C市D区纺织企业数量众多，但长期靠低价格、大批量竞争，研发投入偏低，专利多集中在外观和实用新型、发明专利不多，附加值低。链条虽长，却大而不强、多而不优。\n4.原因分析。根源在于企业创新动力和能力不足，专业化分工协作不够紧密，要素保障和公共服务支撑不到位。\n5.对策结论。要在“强链”上下功夫：链主开放标准、平台和场景，带动配套企业提升能力，由政府梳理清单、缺什么引什么；推动集群数字化改造和共享服务，支持专精特新企业成长；强化人才、资金、数据等要素保障，让链条既强又壮。\n\n【评分参考】\n本题30分。观点（4分）：准确指出误区并落到“强链”；释义（10分）：分别解清“链主强≠链条强”“链条长≠链条壮”，每层5分，须结合资料2、资料3；分析（8分）：能点出原因、讲清逻辑；结论（8分）：对策具体可行、源于资料。语言与条理5分。\n常见失分：只解释字面意思不作分析；脱离资料空谈产业政策；只谈一个分句、遗漏另一层；没有观点态度；超字数明显。"},{"id":"gd-sl-2025-3","stem":"给定资料5中提到：“制造业是广东的厚实家底，也是必须守住的根基。”请结合给定资料，联系实际，自拟标题，写一篇文章。\n要求：（1）观点明确，见解深刻；（2）内容充实，结构完整；（3）语言流畅，书写工整；（4）不拘泥于给定资料，不得抄袭给定资料；（5）1000~1200字。（50分）","limit":1200,"min":1000,"score":50,"answer":"【参考范文】\n\n守好制造家底 挺起产业脊梁\n\n制造业是实体经济的根基，是广东赢得今天、走向明天的底气所在。广东的制造家底，是靠几代人一锤一锤敲出来的。然而，家底厚不等于根基牢。A市五金厂老周的观望、C市D区纺织企业的低价竞争、产教融合中“学校热、企业冷”的尴尬，提醒我们：守好家底，必须推动制造业转型升级。\n\n守好家底，要在“链”上做文章，让产业链既长又强。产业的竞争力，不在于单个企业的块头，而在于链条的结实。B市围绕链主企业华擎梳理上下游清单，缺什么引什么，引导中小企业“卡位入链”，并从“压价”转向“陪跑”，开放标准和平台帮供应商提能力，整机成本反而下降、交付更加稳定；反观一些园区，配套企业名义上入了链、实际只做低端代工，整机订单一减就最先受冲击。可见，链主强不等于链条强，必须在“强链”上用力：支持链主开放平台和标准，带动配套企业升级，扶持专精特新企业深耕细分领域。链条壮了，风浪再大也吹不倒。\n\n守好家底，要在“改”上求实效，让传统产业焕发新生。传统产业不是落后产业，往往是家底最厚实的那一块。C市D区推动纺织集群整体数字化改造，建平台让企业“接单”“派单”，提供共享打版、检测、仓储，先诊断再投入，降了成本、稳了交期。但也要看到，中小企业改造投入压力大、系统接口不通、数据安全存疑。改造不能一味求“高大上”，更不能“一窝蜂”，要坚持先算账、再上设备，先理顺流程、再更新机器，让企业改得起、用得好、见得到效益。\n\n守好家底，要在“人”上下本钱，让技能人才扎根车间。机器能买，会调机器的人难找。老周车间里年轻人干不满三个月就走，不少企业开出较高薪酬，仍招不到“看得懂图纸、也看得懂代码”的人。E市推动产教融合，校企共建产业学院、开设订单班，课程共同开发，工程师进课堂，学生毕业就能上手；推行技能等级评价并与薪酬挂钩，让一线工人有奔头。破解“两张皮”，要让技能有价、成才有多条路，使年轻人愿意进车间、留得下、干得久。\n\n守好家底，要在“合”上拓空间，让区域协同释放效能。建设粤港澳大湾区，为制造业升级打开了广阔天地。珠三角配套完整、研发能力强，粤东西北用地用工相对充裕，港澳善于基础研究和对接国际规则。推动“总部+基地”“研发+生产”分工协作，补齐物流、检测、模具等生产性服务业短板，打通科技成果从实验室到量产的“最后一公里”，就能把各自所长聚成整体之势。\n\n“制造业是广东的厚实家底，也是必须守住的根基。”守家底不是守摊子，而是要在转型升级中把根基夯得更实。这既需要政府搭平台、优服务、给场景，也需要企业敢投入、善经营、重创新。保持耐心和定力，一手抓链条和改造、一手抓人才和协同，广东制造必能从“大”走向“强”，在新征程上挺起产业脊梁。\n\n【写作提示】\n1.立意角度：围绕“制造业当家”与广东高质量发展，抓住“家底”与“根基”两个关键词，落点在“守家底不是守摊子，而是靠转型升级把根基夯得更实”。可分维度展开：产业链群、数字化改造、技能人才、区域协同（大湾区），也可从“存量变革与增量突破”“政府与市场各就其位”切入。\n2.结构安排：建议采用“总—分—总”。开头由制造业根基地位引入，用资料中的现实困境带出总论点；主体设三至四个分论点，每段按“观点句+资料例证+简要分析+对策结论”推进，分论点句式力求整齐；结尾回扣“厚实家底”“必须守住的根基”，升华到制造强省与中国式现代化的广东实践。\n3.注意事项：标题要准确凝练，避免“论制造业当家”一类空泛表述；结合资料但要跳出资料，可补充身边企业的鲜活事例；切忌大段照抄给定资料；字数控制在1000~1200字，卷面工整。"}]},{"id":"sy-2023","title":"2023年广东省事业单位公开招聘工作人员考试《公共基础知识》（模拟卷）","region":"广东省","examType":"广东事业单位（编制）","subject":"公基","year":2023,"duration":90,"totalScore":100,"note":"本卷为依据历年真题题型结构编写的原创模拟题，非官方真题原文，仅供练习。","sections":[{"name":"政治理论","material":null,"questions":[{"id":"sy-2023-01","stem":"历史唯物主义认为，推动社会存在和发展、决定社会面貌的决定性力量是（　）","options":["地理环境","人口因素","物质资料的生产方式","杰出人物的个人意志"],"answer":2,"explain":"历史唯物主义认为，物质资料的生产方式是社会存在和发展的决定力量，它决定社会的性质与面貌，并制约着政治生活和精神生活。地理环境和人口因素是社会发展的必要条件，但不起决定作用，杰出人物的意志也不能决定历史发展方向。"},{"id":"sy-2023-02","stem":"中国特色社会主义进入新时代，我国社会主要矛盾已经转化为人民日益增长的（　）和不平衡不充分的发展之间的矛盾。","options":["物质文化需要","美好生活需要","精神文化需要","民主法治需要"],"answer":1,"explain":"新时代我国社会主要矛盾是人民日益增长的美好生活需要和不平衡不充分的发展之间的矛盾。这一转化没有改变我国仍处于社会主义初级阶段的基本国情，也没有改变我国是世界最大发展中国家的国际地位，发展仍是第一要务。"},{"id":"sy-2023-03","stem":"中国共产党的根本宗旨是（　）","options":["解放思想、实事求是","民主集中制","独立自主、自力更生","全心全意为人民服务"],"answer":3,"explain":"全心全意为人民服务是中国共产党的根本宗旨，是党区别于其他政党的显著标志。实事求是是党的思想路线的核心，民主集中制是党的根本组织原则，独立自主、自力更生是我国对外政策和革命建设的重要方针，均不是党的根本宗旨。"},{"id":"sy-2023-04","stem":"社会主义核心价值观在公民个人层面的价值准则是（　）","options":["富强、民主、文明、和谐","自由、平等、公正、法治","爱国、敬业、诚信、友善","和平、发展、合作、共赢"],"answer":2,"explain":"社会主义核心价值观分为三个层面：富强、民主、文明、和谐是国家层面的价值目标，自由、平等、公正、法治是社会层面的价值取向，爱国、敬业、诚信、友善是公民个人层面的价值准则，三者相互贯通、相互支撑，共同构成完整的价值体系。"}]},{"name":"法律","material":null,"questions":[{"id":"sy-2023-05","stem":"根据我国现行宪法的规定，宪法的修改由全国人民代表大会以全体代表的（　）以上的多数通过。","options":["二分之一","三分之二","四分之三","五分之四"],"answer":1,"explain":"宪法第六十四条规定，宪法的修改由全国人民代表大会常务委员会或者五分之一以上的全国人民代表大会代表提议，并由全国人民代表大会以全体代表的三分之二以上的多数通过；法律和其他议案则由全体代表的过半数通过。故选B。"},{"id":"sy-2023-06","stem":"根据《中华人民共和国民法典》的规定，向人民法院请求保护民事权利的普通诉讼时效期间为（　）","options":["一年","二年","三年","五年"],"answer":2,"explain":"民法典第一百八十八条规定，向人民法院请求保护民事权利的诉讼时效期间为三年，法律另有规定的依照其规定。该期间自权利人知道或者应当知道权利受到损害以及义务人之日起计算，最长不超过二十年。故选C。"},{"id":"sy-2023-07","stem":"根据《中华人民共和国行政处罚法》的规定，对当事人的同一个违法行为，不得给予两次以上（　）的行政处罚。","options":["警告","罚款","没收违法所得","暂扣许可证件"],"answer":1,"explain":"行政处罚法第二十九条规定，对当事人的同一个违法行为，不得给予两次以上罚款的行政处罚；同一个违法行为违反多个法律规范应当给予罚款处罚的，按照罚款数额高的规定处罚。这体现了行政处罚中的一事不再罚原则。故选B。"},{"id":"sy-2023-08","stem":"根据《中华人民共和国劳动合同法》的规定，用人单位自用工之日起超过一个月不满一年未与劳动者订立书面劳动合同的，应当向劳动者每月支付（　）的工资。","options":["一倍","一点五倍","二倍","三倍"],"answer":2,"explain":"劳动合同法第八十二条规定，用人单位自用工之日起超过一个月不满一年未与劳动者订立书面劳动合同的，应当向劳动者每月支付二倍的工资。该规定旨在督促用人单位及时订立书面劳动合同，保障劳动者的合法权益。故选C。"}]},{"name":"经济","material":null,"questions":[{"id":"sy-2023-09","stem":"需求定律表明，在其他条件不变的情况下，商品的价格与其需求量之间（　）","options":["呈反方向变动","呈同方向变动","没有关系","先同方向后反方向变动"],"answer":0,"explain":"需求定律指在其他条件不变时，商品价格上升则需求量减少，价格下降则需求量增加，二者呈反方向变动。需注意需求量的变动由价格引起，而需求变动由收入、偏好、相关商品价格等价格以外因素引起。故选A。"},{"id":"sy-2023-10","stem":"中央银行上调存款准备金率，通常属于（　）","options":["扩张性财政政策","扩张性货币政策","紧缩性货币政策","紧缩性财政政策"],"answer":2,"explain":"存款准备金率是中央银行调控货币供应量的重要工具。上调存款准备金率会减少商业银行可用于放贷的资金，收缩货币供应量，抑制社会总需求，因而属于紧缩性货币政策。财政政策的工具主要是税收、国债和财政支出。故选C。"}]},{"name":"管理与公文","material":null,"questions":[{"id":"sy-2023-11","stem":"在组织规模一定的条件下，行政组织的管理幅度与管理层次之间一般（　）","options":["呈正比关系","没有关系","先正比后反比","呈反比关系"],"answer":3,"explain":"管理幅度指一名管理者能够有效直接领导的下属人数，管理层次指组织纵向划分的等级数目。在组织规模既定时，管理幅度越大，所需的管理层次越少；管理幅度越小，管理层次越多，二者呈反比关系。故选D。"},{"id":"sy-2023-12","stem":"根据《党政机关公文处理工作条例》，适用于不相隶属机关之间商洽工作、询问和答复问题、请求批准和答复审批事项的公文文种是（　）","options":["报告","函","通知","请示"],"answer":1,"explain":"函适用于不相隶属机关之间商洽工作、询问和答复问题、请求批准和答复审批事项。报告用于向上级机关汇报工作、反映情况，请示用于向上级机关请求指示、批准，通知用于发布、传达要求下级机关执行和有关单位周知或执行的事项。故选B。"},{"id":"sy-2023-13","stem":"根据《党政机关公文格式》的要求，公文的发文字号中，年份应当标全称并（　）","options":["用圆括号括入","用方括号括入","不加任何括号","用六角括号括入"],"answer":3,"explain":"发文字号由发文机关代字、年份、发文顺序号组成，其中年份和发文顺序号用阿拉伯数字标注，年份应标全称并用六角括号“〔〕”括入，发文顺序号不加“第”字、不编虚位。故选D。"}]},{"name":"科技人文","material":null,"questions":[{"id":"sy-2023-14","stem":"下列关于“光年”的表述，正确的是（　）","options":["光年是时间单位","光年是长度单位，表示光在真空中一年内传播的距离","光年是速度单位","光年是质量单位"],"answer":1,"explain":"光年是天文学中计量天体之间距离的单位，指光在真空中沿直线传播一年所经过的距离，数值极其巨大。它虽然带有“年”字，但属于长度单位而非时间单位，这是常见的易错知识点，需注意区分。故选B。"},{"id":"sy-2023-15","stem":"下列关于人体器官的表述，正确的是（　）","options":["人体面积最大、重量最重的器官是皮肤","人体最大的器官是肝脏","人体最大的器官是肺","人体最大的器官是心脏"],"answer":0,"explain":"皮肤覆盖人体表面，是人体面积最大、重量最重的器官，具有屏障保护、感觉、调节体温和分泌排泄等功能。肝脏是人体最大的内脏器官，也是最大的消化腺，但就人体全部器官而言，最大的器官是皮肤。故选A。"},{"id":"sy-2023-16","stem":"西汉时期提出“罢黜百家，独尊儒术”主张并被朝廷采纳的思想家是（　）","options":["董仲舒","司马迁","王充","朱熹"],"answer":0,"explain":"西汉汉武帝时期，董仲舒在应对策问时提出“罢黜百家，独尊儒术”的主张，被汉武帝采纳，儒学从此成为封建社会的正统思想。司马迁是西汉史学家，著有《史记》；王充是东汉思想家；朱熹是南宋理学家。故选A。"},{"id":"sy-2023-17","stem":"我国第一部纪传体通史是（　）","options":["《春秋》","《左传》","《汉书》","《史记》"],"answer":3,"explain":"《史记》为西汉司马迁所著，记述了从黄帝到汉武帝时期的历史，是我国第一部纪传体通史，被鲁迅誉为“史家之绝唱，无韵之离骚”。《春秋》《左传》是编年体史书，《汉书》是我国第一部纪传体断代史。故选D。"}]},{"name":"广东省情","material":null,"questions":[{"id":"sy-2023-18","stem":"根据粤港澳大湾区建设的总体部署，下列城市中被确定为大湾区中心城市（区域发展核心引擎）之一的是（　）","options":["佛山市","东莞市","深圳市","中山市"],"answer":2,"explain":"粤港澳大湾区建设以香港、澳门、广州、深圳四大中心城市作为区域发展的核心引擎，各自发挥辐射带动作用；佛山、东莞、中山等城市属于大湾区重要节点城市，承担支撑和承接功能，但未被确定为中心城市。故选C。"},{"id":"sy-2023-19","stem":"下列省级行政区中，与广东省陆地相邻的是（　）","options":["浙江省","湖南省","江苏省","湖北省"],"answer":1,"explain":"广东省陆地分别与福建省、江西省、湖南省、广西壮族自治区相邻，并与香港、澳门两个特别行政区相连，南临南海。浙江、江苏地处华东沿海，湖北位于长江中游，均不与广东陆地接壤，与广东隔琼州海峡相望的是海南省。故选B。"},{"id":"sy-2023-20","stem":"下列各项中，不属于岭南地区代表性文化形式的是（　）","options":["粤剧","广东音乐","醒狮","昆曲"],"answer":3,"explain":"岭南文化是广东等地的重要地域文化，粤剧、广东音乐、醒狮、广绣、客家山歌等都是其代表性形式，具有鲜明的地方特色。昆曲发源于江苏昆山一带，属于江南文化系统，并不属于岭南地区代表性文化形式。故选D。"}]},{"name":"多项选择题","material":null,"questions":[{"id":"sy-2023-21","type":"multi","stem":"根据我国现行宪法的规定，下列属于公民基本义务的有（　）","options":["宗教信仰自由","依法纳税","遵守宪法和法律","依法服兵役"],"answer":[1,2,3],"explain":"宪法第五十六条规定公民有依照法律纳税的义务，第五十三条规定公民必须遵守宪法和法律，第五十五条规定依照法律服兵役是公民的光荣义务。宗教信仰自由属于宪法第三十六条规定的公民基本权利，不是基本义务。"},{"id":"sy-2023-22","type":"multi","stem":"根据《中华人民共和国民法典》的规定，下列民事法律行为无效的有（　）","options":["无民事行为能力人实施的民事法律行为","因重大误解实施的民事法律行为","违背公序良俗的民事法律行为","行为人与相对人以虚假的意思表示实施的民事法律行为"],"answer":[0,2,3],"explain":"民法典第一百四十四条规定，无民事行为能力人实施的民事法律行为无效；第一百四十六条规定，行为人与相对人以虚假意思表示实施的民事法律行为无效；第一百五十三条规定，违背公序良俗的民事法律行为无效。因重大误解实施的行为属于可撤销行为，并非当然无效。"},{"id":"sy-2023-23","type":"multi","stem":"根据公文处理、管理与经济、地理常识，下列说法正确的有（　）","options":["广东省是我国陆地面积最大的省级行政区","党政机关向上级机关行文，原则上主送一个上级机关，不抄送下级机关","居民消费价格指数（CPI）是衡量通货膨胀程度的重要指标","管理的基本职能一般包括计划、组织、领导、控制"],"answer":[1,2,3],"explain":"《党政机关公文处理工作条例》第十五条规定，向上级机关行文原则上主送一个上级机关，不抄送下级机关。管理的基本职能一般包括计划、组织、领导、控制；CPI是衡量通货膨胀程度的重要指标。我国陆地面积最大的省级行政区是新疆维吾尔自治区，不是广东。"}]},{"name":"判断题","material":null,"questions":[{"id":"sy-2023-24","type":"judge","stem":"根据《中华人民共和国行政处罚法》的规定，行政机关不得因当事人陈述、申辩而给予更重的处罚。","options":["正确","错误"],"answer":0,"explain":"行政处罚法第四十五条规定，当事人有权进行陈述和申辩，行政机关必须充分听取当事人的意见；行政机关不得因当事人陈述、申辩而给予更重的处罚。题干表述与法律规定一致，故正确。"},{"id":"sy-2023-25","type":"judge","stem":"根据《中华人民共和国劳动合同法》的规定，劳动合同期限一年以上不满三年的，试用期不得超过三个月。","options":["正确","错误"],"answer":1,"explain":"劳动合同法第十九条规定，劳动合同期限一年以上不满三年的，试用期不得超过二个月；三个月以上不满一年的，试用期不得超过一个月；三年以上固定期限和无固定期限的劳动合同，试用期不得超过六个月。题干所述三个月与法律规定不符，故错误。"},{"id":"sy-2023-26","type":"judge","stem":"一般情况下，海拔越高，大气压越低，水的沸点也越低。","options":["正确","错误"],"answer":0,"explain":"大气压随海拔升高而降低，液体的沸点随外界气压降低而降低，所以高原上水的沸点低于100摄氏度，需借助高压锅提高气压才能让水达到较高温度。题干表述符合这一原理，故正确。"}]}]},{"id":"sy-2024","title":"2024年广东省事业单位公开招聘工作人员考试《公共基础知识》（模拟卷）","region":"广东省","examType":"广东事业单位（编制）","subject":"公基","year":2024,"duration":90,"totalScore":100,"note":"本卷为依据历年真题题型结构编写的原创模拟题，非官方真题原文，仅供练习。","sections":[{"name":"政治理论","material":null,"questions":[{"id":"sy-2024-01","stem":"在唯物辩证法的基本规律中，揭示事物发展的源泉和动力、处于实质与核心地位的是（　）","options":["质量互变规律","对立统一规律","否定之否定规律","普遍联系的观点"],"answer":1,"explain":"唯物辩证法由对立统一规律、质量互变规律、否定之否定规律以及一系列范畴构成，其中对立统一规律揭示了事物发展的源泉和动力，是唯物辩证法的实质与核心，其他规律和范畴都以此为基础。"},{"id":"sy-2024-02","stem":"辩证唯物主义认识论认为，检验真理的唯一标准是（　）","options":["权威人物的论断","多数人的意见","社会实践","严密的逻辑推理"],"answer":2,"explain":"辩证唯物主义认识论认为，真理是主观认识与客观实际相符合，检验真理的唯一标准只能是社会实践。权威论断、多数人意见和逻辑推理都属于主观范围，不能充当检验客观真理的标准。"},{"id":"sy-2024-03","stem":"我国宪法明确规定，中国特色社会主义最本质的特征是（　）","options":["以经济建设为中心","人民当家作主","实现全体人民共同富裕","中国共产党领导"],"answer":3,"explain":"《宪法》第一条规定，社会主义制度是中华人民共和国的根本制度，中国共产党领导是中国特色社会主义最本质的特征，禁止任何组织或者个人破坏社会主义制度，这是宪法对我国根本问题的确认。"},{"id":"sy-2024-04","stem":"中国共产党的根本组织原则和领导制度是（　）","options":["民主集中制","集体领导制度","首长负责制","请示报告制度"],"answer":0,"explain":"民主集中制是民主基础上的集中和集中指导下的民主相结合，是党的根本组织原则和领导制度，党章对此有明确规定；它同时也是我国国家机构的组织和活动原则，与首长负责制的适用范围不同。"}]},{"name":"法律","material":null,"questions":[{"id":"sy-2024-05","stem":"根据我国现行宪法，有权决定全国或者个别省、自治区、直辖市进入紧急状态的机关是（　）","options":["全国人民代表大会","国务院","全国人民代表大会常务委员会","国家主席"],"answer":2,"explain":"《宪法》第六十七条规定，全国人民代表大会常务委员会有权决定全国或者个别省、自治区、直辖市的进入紧急状态；国务院则决定省、自治区、直辖市范围内部分地区的进入紧急状态，两者权限范围不同。"},{"id":"sy-2024-06","stem":"根据《民法典》，不满八周岁的未成年人是（　）","options":["完全民事行为能力人","限制民事行为能力人","无民事行为能力人","视为完全民事行为能力人"],"answer":2,"explain":"《民法典》第二十条规定，不满八周岁的未成年人为无民事行为能力人，由其法定代理人代理实施民事法律行为；八周岁以上的未成年人原则上为限制民事行为能力人，二者以八周岁为界。"},{"id":"sy-2024-07","stem":"根据《行政处罚法》，违法行为在（　）内未被发现的，不再给予行政处罚；涉及公民生命健康安全、金融安全且有危害后果的，该期限延长至五年。","options":["一年","二年","三年","五年"],"answer":1,"explain":"《行政处罚法》第三十六条规定，违法行为在二年内未被发现的，不再给予行政处罚；涉及公民生命健康安全、金融安全且有危害后果的，上述期限延长至五年，法律另有规定的除外。"},{"id":"sy-2024-08","stem":"根据《劳动合同法》，劳动合同期限三个月以上不满一年的，试用期不得超过（　）","options":["半个月","一个月","二个月","三个月"],"answer":1,"explain":"《劳动合同法》第十九条规定，劳动合同期限三个月以上不满一年的，试用期不得超过一个月；一年以上不满三年的不得超过二个月；三年以上固定期限和无固定期限的不得超过六个月。"}]},{"name":"经济","material":null,"questions":[{"id":"sy-2024-09","stem":"在其他条件不变的情况下，若某商品的需求价格弹性大于1，则该商品降价销售通常会使其销售总收益（　）","options":["增加","减少","保持不变","无法判断"],"answer":0,"explain":"需求价格弹性大于1表示需求富有弹性，价格下降引起的需求量增加幅度大于价格下降幅度，销售总收益随之增加；当弹性小于1即需求缺乏弹性时，降价才会使总收益减少。"},{"id":"sy-2024-10","stem":"按国土原则核算，一国或地区在一定时期内所生产的全部最终产品和服务的市场价值总和，称为（　）","options":["国民生产总值","国民收入","国内生产总值","财政收入"],"answer":2,"explain":"国内生产总值（GDP）按国土原则核算，指一国或地区在一定时期内生产的全部最终产品和服务的市场价值总和；国民生产总值按国民原则核算，二者统计口径不同，不能混用。"}]},{"name":"管理与公文","material":null,"questions":[{"id":"sy-2024-11","stem":"在管理的基本职能中，处于首要地位并为其他各项职能提供依据的是（　）","options":["计划","组织","领导","控制"],"answer":0,"explain":"管理的基本职能一般包括计划、组织、领导、控制等。计划是确定目标及实现途径的活动，处于首要地位，为组织机构的设置、人员的指挥激励和活动的纠偏控制提供依据和标准。"},{"id":"sy-2024-12","stem":"某事业单位就某项需要上级机关批准的事项行文，应当使用的公文文种是（　）","options":["报告","请示","意见","函"],"answer":1,"explain":"《党政机关公文处理工作条例》规定，请示适用于向上级机关请求指示、批准；报告适用于向上级机关汇报工作、反映情况、答复询问，且报告中不得夹带请示事项，故请求批准应使用请示。"},{"id":"sy-2024-13","stem":"根据《党政机关公文格式》，关于公文成文日期的标注，下列做法正确的是（　）","options":["用阿拉伯数字将年、月、日标全，年份标全称，月、日不编虚位","用汉字大写数字标注，年份可以简写","用阿拉伯数字标注，月、日一律编虚位","由发文机关根据以往习惯自行确定"],"answer":0,"explain":"《党政机关公文格式》规定，成文日期用阿拉伯数字将年、月、日标全，年份应标全称，月、日不编虚位，例如应标注为2024年3月5日，而不能写成2024年03月05日。"}]},{"name":"科技人文","material":null,"questions":[{"id":"sy-2024-14","stem":"长期从事杂交水稻研究、成功培育出高产杂交水稻品种，被誉为“杂交水稻之父”的科学家是（　）","options":["袁隆平","屠呦呦","钱学森","邓稼先"],"answer":0,"explain":"袁隆平长期从事杂交水稻研究，成功培育出高产杂交水稻品种并大面积推广，为解决我国乃至世界的粮食问题作出重大贡献，被誉为“杂交水稻之父”；屠呦呦以发现青蒿素著称。"},{"id":"sy-2024-15","stem":"计算机中数据存储以字节为基本单位，按照二进制方式计量，1KB等于（　）","options":["1000字节","1024字节","512字节","2048字节"],"answer":1,"explain":"计算机内部采用二进制存储和运算，存储容量单位之间以2的幂次进位，1KB等于2的10次方即1024字节，1MB等于1024KB，这与十进制计量的1000进位不同。"},{"id":"sy-2024-16","stem":"下列不属于我国古代四大发明的是（　）","options":["造纸术","印刷术","指南针","地动仪"],"answer":3,"explain":"造纸术、印刷术、指南针和火药合称我国古代四大发明，对世界文明发展产生了深远影响；地动仪是东汉张衡发明的测震仪器，虽科技价值很高，但不属于四大发明之列。"},{"id":"sy-2024-17","stem":"“路漫漫其修远兮，吾将上下而求索”出自（　）","options":["《诗经》","屈原的《离骚》","《论语》","司马迁的《史记》"],"answer":1,"explain":"该句出自战国时期楚国诗人屈原的《离骚》，是《楚辞》的代表作品，抒发了诗人追求理想、不懈探索的执着精神；屈原是我国浪漫主义文学的奠基人，其作品影响深远。"}]},{"name":"广东省情","material":null,"questions":[{"id":"sy-2024-18","stem":"粤港澳大湾区由香港、澳门两个特别行政区和广东省的（　）个城市共同组成","options":["七个","八个","九个","十个"],"answer":2,"explain":"粤港澳大湾区包括香港、澳门两个特别行政区和广东省广州、深圳、珠海、佛山、惠州、东莞、中山、江门、肇庆九个城市，合计十一个城市，是我国开放程度最高、经济活力最强的区域之一。"},{"id":"sy-2024-19","stem":"主要流行于广东珠江三角洲等粤语地区、被誉为岭南文化代表剧种的戏曲是（　）","options":["粤剧","潮剧","琼剧","汉剧"],"answer":0,"explain":"粤剧又称“广东大戏”，主要流行于广东珠江三角洲及粤语地区，唱腔以梆子、二黄为主，兼具岭南地方特色，2009年入选联合国教科文组织人类非物质文化遗产代表作名录。"},{"id":"sy-2024-20","stem":"与广东省隔琼州海峡相望的省级行政区是（　）","options":["海南省","广西壮族自治区","福建省","台湾省"],"answer":0,"explain":"广东省位于我国大陆南部，其雷州半岛与海南岛之间隔着琼州海峡，海峡以北为广东，以南为海南省，因此与广东隔琼州海峡相望的省级行政区是海南省。"}]},{"name":"多项选择题","material":null,"questions":[{"id":"sy-2024-21","type":"multi","stem":"根据我国现行宪法，下列属于全国人民代表大会常务委员会职权的有（　）","options":["解释宪法，监督宪法的实施","决定特赦","决定驻外全权代表的任免","制定和修改刑事、民事、国家机构的和其他的基本法律"],"answer":[0,1,2],"explain":"《宪法》第六十七条规定，全国人大常委会行使解释宪法、监督宪法实施，决定特赦，决定驻外全权代表的任免等职权；制定和修改基本法律属于第六十二条规定的全国人民代表大会职权，常委会只能作部分补充和修改。"},{"id":"sy-2024-22","type":"multi","stem":"根据《中华人民共和国劳动合同法》，下列情形中，用人单位可以解除劳动合同且无需事先通知劳动者本人的有（　）","options":["劳动者在试用期间被证明不符合录用条件","劳动者不能胜任工作，经过培训或者调整工作岗位仍不能胜任工作","劳动者严重违反用人单位的规章制度","劳动者被依法追究刑事责任"],"answer":[0,2,3],"explain":"《劳动合同法》第三十九条规定，劳动者在试用期间被证明不符合录用条件、严重违反用人单位的规章制度、被依法追究刑事责任的，用人单位可以解除劳动合同且无需事先通知；不能胜任工作本质上属于第四十条情形，须提前三十日书面通知或额外支付一个月工资。"},{"id":"sy-2024-23","type":"multi","stem":"根据《中华人民共和国民法典》，下列民事法律行为无效的有（　）","options":["无民事行为能力人实施的民事法律行为","行为人与相对人以虚假的意思表示实施的民事法律行为","违反法律、行政法规的强制性规定的民事法律行为","限制民事行为能力人实施的纯获利益的民事法律行为"],"answer":[0,1,2],"explain":"《民法典》第一百四十四条规定无民事行为能力人实施的民事法律行为无效；第一百四十六条规定以虚假意思表示实施的民事法律行为无效；第一百五十三条规定违反法律、行政法规强制性规定的民事法律行为无效。限制民事行为能力人实施的纯获利益行为有效。"}]},{"name":"判断题","material":null,"questions":[{"id":"sy-2024-24","type":"judge","stem":"判断：请求保护民事权利，自权利受到损害之日起超过二十年的，人民法院原则上不予保护；有特殊情况的，人民法院可以根据权利人的申请决定延长。","options":["正确","错误"],"answer":0,"explain":"《民法典》第一百八十八条规定，请求保护民事权利的诉讼时效期间为三年；自权利受到损害之日起超过二十年的，人民法院不予保护，有特殊情况的，可以根据权利人的申请决定延长。故该表述正确。"},{"id":"sy-2024-25","type":"judge","stem":"判断：我国纬度位置最低的省级行政区是广东省。","options":["正确","错误"],"answer":1,"explain":"我国纬度位置最低的省级行政区是海南省：海南岛最南端约在北纬18°，三沙市所辖的曾母暗沙更南，是我国领土的最南端。广东省徐闻县是中国大陆的最南端（约北纬20°13′），但作为省级行政区，广东的纬度位置高于海南，故该表述错误。"},{"id":"sy-2024-26","type":"judge","stem":"根据《党政机关公文处理工作条例》，请示应当一文一事，不得在报告等非请示性公文中夹带请示事项。","options":["正确","错误"],"answer":0,"explain":"《党政机关公文处理工作条例》规定，请示适用于向上级机关请求指示、批准，应当一文一事；报告适用于汇报工作、反映情况、答复询问，报告中不得夹带请示事项。这样规定便于上级机关及时研究答复。故该表述正确。"}]}]},{"id":"sy-2025","title":"2025年广东省事业单位公开招聘工作人员考试《公共基础知识》（模拟卷）","region":"广东省","examType":"广东事业单位（编制）","subject":"公基","year":2025,"duration":90,"totalScore":100,"note":"本卷为依据历年真题题型结构编写的原创模拟题，非官方真题原文，仅供练习。","sections":[{"name":"政治理论","material":null,"questions":[{"id":"sy-2025-01","stem":"辩证唯物主义认为，物质与意识的关系是（　）","options":["物质决定意识，意识对物质具有能动的反作用","意识决定物质，物质是意识的外化表现","物质与意识互不相关、各自独立存在","物质与意识同等重要，二者互为决定因素"],"answer":0,"explain":"辩证唯物主义在承认世界的本原是物质、物质决定意识的前提下，又肯定意识具有能动作用，能够反映世界并反作用于物质。B属唯心主义，C否认二者联系，D混淆了决定与被决定的关系。"},{"id":"sy-2025-02","stem":"在社会治理中依法化解矛盾纠纷，坚持办事依法、遇事找法、解决问题用法、化解矛盾靠法。这一要求体现的是（　）","options":["以道德教化作为社会治理的主要手段","以法治方式解决社会矛盾、维护社会秩序","依靠行政机关的自由裁量处理一切纠纷","通过扩大行政强制权力提高治理效率"],"answer":1,"explain":"法治是治国理政的基本方式，要求运用法治思维和法治方式化解社会矛盾、协调利益关系。题干强调依法办事、遇事找法，正是法治方式的体现，而非以道德教化为主或单纯依靠行政强制与自由裁量。"},{"id":"sy-2025-03","stem":"党的十九大明确，党在新时代的强军目标是建设一支（　）的人民军队，把人民军队建设成为世界一流军队。","options":["规模庞大、装备精良、保障有力","听党指挥、能打胜仗、作风优良","政治过硬、军事过硬、作风过硬","忠诚可靠、纪律严明、英勇善战"],"answer":1,"explain":"党的十九大报告明确提出，党在新时代的强军目标是建设一支听党指挥、能打胜仗、作风优良的人民军队，把人民军队建设成为世界一流军队。其中听党指挥是灵魂，能打胜仗是核心，作风优良是保证，三者构成有机整体。"},{"id":"sy-2025-04","stem":"中国共产党的思想路线的核心是（　）","options":["独立自主","群众路线","实事求是","艰苦奋斗"],"answer":2,"explain":"党的思想路线是一切从实际出发，理论联系实际，实事求是，在实践中检验真理和发展真理，其核心是实事求是。群众路线是党的根本工作路线，独立自主、艰苦奋斗则是重要方针和优良作风，均非思想路线的核心。"}]},{"name":"法律","material":null,"questions":[{"id":"sy-2025-05","stem":"根据我国宪法规定，最高国家权力机关的执行机关是（　）","options":["最高人民法院","中央军事委员会","国务院","全国人民代表大会"],"answer":2,"explain":"宪法规定，中华人民共和国国务院即中央人民政府，是最高国家权力机关的执行机关，是最高国家行政机关。全国人民代表大会是最高国家权力机关，最高人民法院是审判机关，中央军事委员会领导全国武装力量，均不符合题干。"},{"id":"sy-2025-06","stem":"根据《民法典》，八周岁以上的未成年人独立实施的、与其年龄和智力不相适应的民事法律行为，其效力状态是（　）","options":["自始无效","当然有效，无需任何人同意","一律可撤销","经法定代理人同意或者追认后有效"],"answer":3,"explain":"《民法典》规定，八周岁以上的未成年人为限制民事行为能力人，其独立实施的民事法律行为经法定代理人同意或者追认后有效，但纯获利益的行为和与其年龄、智力相适应的行为除外，故不属于自始无效或当然有效。"},{"id":"sy-2025-07","stem":"根据《行政处罚法》，行政机关作出行政处罚决定，当事人不在场的，应当自作出决定之日起（　）内依照《中华人民共和国民事诉讼法》的有关规定送达当事人。","options":["三日","五日","十五日","七日"],"answer":3,"explain":"《行政处罚法》规定，行政处罚决定书应当在宣告后当场交付当事人；当事人不在场的，行政机关应当在七日内依照《民事诉讼法》的有关规定送达当事人。三日、五日、十五日均无法律依据。"},{"id":"sy-2025-08","stem":"根据《劳动合同法》，劳动者在试用期内解除劳动合同，应当（　）","options":["提前三日通知用人单位","提前三十日以书面形式通知用人单位","经用人单位书面同意后方可解除","不得单方解除，须由用人单位提出"],"answer":0,"explain":"《劳动合同法》规定，劳动者提前三十日以书面形式通知用人单位，可以解除劳动合同；在试用期内提前三日通知用人单位，可以解除劳动合同。试用期解除无需用人单位同意，其余选项提出的条件均与法律规定不符。"}]},{"name":"经济","material":null,"questions":[{"id":"sy-2025-09","stem":"在其他条件不变的情况下，若猪肉价格大幅上涨，则消费者对鸡肉的需求量通常（　）","options":["减少","保持不变","先增加后必然减少","增加"],"answer":3,"explain":"猪肉与鸡肉在消费中互为替代品，其需求交叉价格弹性为正。猪肉价格上涨会使消费者转向相对便宜的鸡肉，从而增加鸡肉的需求量。若两种商品互为互补品，一种商品涨价才会使另一种商品需求减少。"},{"id":"sy-2025-10","stem":"下列措施中，属于财政政策工具的是（　）","options":["中央银行提高法定存款准备金率","中央银行在公开市场上卖出有价证券","政府调整企业所得税税率","中央银行提高再贴现率"],"answer":2,"explain":"财政政策由政府运用税收、国债、财政支出等工具实施；货币政策由中央银行运用存款准备金率、再贴现率、公开市场业务等工具实施。调整税率属于财政政策；存款准备金率、公开市场业务和再贴现率则属于中央银行运用的货币政策工具，不属财政政策。"}]},{"name":"管理与公文","material":null,"questions":[{"id":"sy-2025-11","stem":"关于计划工作的特征与要求，下列表述正确的是（　）","options":["计划一经编制完成，执行过程中不得作任何调整","计划只需由组织高层编制，基层无需参与","计划应当明确具体，并保持各层次、各部门计划之间的协调衔接","计划的期限越长越好，长期计划可以取代短期计划"],"answer":2,"explain":"计划是对未来行动的预先安排，应当目标明确、内容具体，并注意各层次、各部门计划之间的协调衔接。计划需随环境和条件变化适时调整，编制时应当吸收各管理层级参与，长期计划与短期计划相互配合而非彼此替代。"},{"id":"sy-2025-12","stem":"根据《党政机关公文处理工作条例》，关于公文成文日期的确定，下列说法正确的是（　）","options":["所有公文一律以机关负责人签发日期为准","联合行文时，以最后签发机关负责人的签发日期为准","以公文印发日期为准，签发日期仅供参考","以公文送达受文机关的日期为准"],"answer":1,"explain":"《党政机关公文处理工作条例》规定，公文的成文日期一般以机关负责人签发的日期为准；联合行文时，以最后签发机关负责人签发的日期为准。据此B项正确。A项不加区分一概而论，C项以印发日期代替成文日期，D项以送达日期代替成文日期，均不符合规定。"},{"id":"sy-2025-13","stem":"根据《党政机关公文格式》，下列关于公文各要素的表述，正确的是（　）","options":["发文字号由发文机关代字、年份和发文顺序号组成，年份应当标全称并用六角括号括入","公文标题必须同时标明发文机关名称、事由和文种，三者缺一不可","主送机关应当编排在成文日期之后，并使用全称或者规范化简称","附件说明应当标注在公文正文之前，以体现附件与正文的对应关系"],"answer":0,"explain":"按照公文格式规范，发文字号由发文机关代字、年份和发文顺序号组成，年份应标全称并用六角括号括入。标题一般由发文机关名称、事由和文种组成，并非缺一不可；主送机关编排在标题之下、正文之前；附件说明位于正文之后、发文机关署名之前。"}]},{"name":"科技人文","material":null,"questions":[{"id":"sy-2025-14","stem":"关于第五代移动通信技术（5G），下列表述不正确的是（　）","options":["只能依靠毫米波频段实现信号覆盖","具有高速率、低时延、大连接的技术特征","其数据传输速率理论上显著高于第四代移动通信技术","可为工业互联网、车联网等应用提供网络支撑"],"answer":0,"explain":"5G具有高速率、低时延、大连接的特点，传输速率远高于4G，能够支撑工业互联网、车联网等应用。5G可采用中低频段与毫米波频段协同组网，毫米波并非唯一选择，故称只能依靠毫米波频段实现覆盖的表述不正确。"},{"id":"sy-2025-15","stem":"“二十四节气”是我国古人通过观察太阳周年运动、认知时令与气候规律而形成的知识体系。关于它，下列说法正确的是（　）","options":["属于我国特有的现代气象观测标准","已被列入联合国教科文组织人类非物质文化遗产代表作名录","以月球绕地球运行的周期为划分依据","仅在长江流域一带适用，其他地区不采用"],"answer":1,"explain":"二十四节气是我国古人依据太阳周年运动总结出的时间知识体系，2016年被列入联合国教科文组织人类非物质文化遗产代表作名录。它并非现代气象观测标准，也不以月球运行周期为划分依据，而是在全国各地农业生产中被广泛参考。"},{"id":"sy-2025-16","stem":"关于《史记》，下列说法正确的是（　）","options":["是我国第一部诗歌总集，收录西周至春秋的诗歌","是东汉班固所著的断代史，以记载西汉历史为主","是我国第一部纪传体通史，作者为西汉司马迁","是编年体史书，按年月顺序记载春秋时期历史"],"answer":2,"explain":"《史记》为西汉司马迁所著，是我国第一部纪传体通史，记述了从黄帝到汉武帝时期的历史。选项中关于诗歌总集和班固断代史的表述分别对应《诗经》与《汉书》，按年月记事者则是《春秋》一类编年体史书，均与《史记》不符。"},{"id":"sy-2025-17","stem":"下列诗人中，被称为“诗圣”、其诗作被誉为“诗史”的唐代诗人是（　）","options":["杜甫","李白","白居易","王维"],"answer":0,"explain":"杜甫是唐代伟大的现实主义诗人，其诗作真实反映了唐代由盛转衰时期的社会现实，因而被称为“诗史”，他本人被后世尊称为“诗圣”。李白被称为“诗仙”，白居易主张“文章合为时而著”，王维则以山水田园诗著称。"}]},{"name":"广东省情","material":null,"questions":[{"id":"sy-2025-18","stem":"关于粤港澳大湾区，下列说法正确的是（　）","options":["由香港、澳门和广东省全部二十一个地级市共同组成","由香港、澳门两个特别行政区和广东省广州、深圳、珠海等九个城市组成","是单一关税区内的区域合作平台，不存在制度差异","其建设无需与“一带一路”建设相衔接"],"answer":1,"explain":"粤港澳大湾区包括香港、澳门两个特别行政区和广东省广州、深圳、珠海、佛山、惠州、东莞、中山、江门、肇庆九个城市，合计十一个城市。该区域涉及三种货币、三个关税区，制度差异明显，建设还要与“一带一路”建设等国家战略相衔接。"},{"id":"sy-2025-19","stem":"我国最早设立的四个经济特区中，位于广东省的是（　）","options":["深圳、珠海、厦门","深圳、珠海、汕头","深圳、汕头、海南","珠海、汕头、厦门"],"answer":1,"explain":"我国最早设立的经济特区为深圳、珠海、汕头、厦门，其中深圳、珠海、汕头三个位于广东省，厦门位于福建省。海南于1988年才建省并设立经济特区，时间晚于首批经济特区，故其余选项均不符合要求。"},{"id":"sy-2025-20","stem":"位于广东省江门市、以中西合璧的乡村建筑群为特色，并被列入《世界遗产名录》的文化遗产是（　）","options":["福建土楼","皖南古村落","开平碉楼与村落","丽江古城"],"answer":2,"explain":"开平碉楼与村落位于广东省江门市开平市，融汇中西建筑艺术与华侨文化，2007年被列入《世界遗产名录》，是广东省目前唯一的世界文化遗产。福建土楼在福建，皖南古村落在安徽，丽江古城在云南，均不在广东。"}]},{"name":"多项选择题","material":null,"questions":[{"id":"sy-2025-21","type":"multi","stem":"根据我国宪法的规定，下列属于全国人民代表大会职权的有（　）","options":["修改宪法，监督宪法的实施","制定和修改刑事、民事、国家机构的和其他的基本法律","解释宪法，监督宪法的实施","领导和管理国防建设事业"],"answer":[0,1],"explain":"宪法规定，全国人民代表大会行使修改宪法、监督宪法实施的职权，并有权制定和修改刑事、民事、国家机构的和其他的基本法律，故①②当选。解释宪法、监督宪法实施是全国人大常委会的职权；领导和管理国防建设事业属于国务院职权，故③④不选。"},{"id":"sy-2025-22","type":"multi","stem":"根据《中华人民共和国劳动法》和《中华人民共和国劳动争议调解仲裁法》，下列说法正确的有（　）","options":["用人单位应当以货币形式按月支付劳动者工资，不得克扣或者无故拖欠","劳动争议仲裁一律实行一裁终局，当事人对仲裁裁决不服的，不得向人民法院提起诉讼","经调解组织调解达成的调解协议，当事人一方在约定期限内不履行的，另一方可以依法申请仲裁","用人单位安排劳动者在工作日延长工作时间的，应当支付不低于工资的百分之一百五十的工资报酬"],"answer":[0,2,3],"explain":"《劳动法》规定工资应当以货币形式按月支付给劳动者本人，不得克扣或无故拖欠；安排工作日延长工作时间应支付不低于150%的工资报酬。《劳动争议调解仲裁法》规定，经调解组织调解达成的调解协议，一方在约定期限内不履行的，另一方可依法申请仲裁。该法只对特定情形规定一裁终局，其余案件当事人对仲裁裁决不服的，可自收到裁决书之日起十五日内向人民法院起诉，故B项“一律一裁终局、不得起诉”表述错误。综上A、C、D正确。"},{"id":"sy-2025-23","type":"multi","stem":"根据《党政机关公文格式》的规定，下列说法正确的有（　）","options":["发文字号由发文机关代字、年份和发文顺序号组成，年份应标全称并用六角括号括入","所有公文都应当在版头标注签发人姓名，以示负责","附件说明应标注在正文之后、发文机关署名之前","抄送机关应当编排在印发机关和印发日期之后"],"answer":[0,2],"explain":"公文格式规范要求：发文字号由发文机关代字、年份、发文顺序号组成，年份标全称并用六角括号括入；附件说明位于正文之后、发文机关署名之前。签发人只在向上级机关行文时标注；抄送机关编排在印发机关和印发日期之前，故①③正确。"}]},{"name":"判断题","material":null,"questions":[{"id":"sy-2025-24","type":"judge","stem":"我国宪法规定，宪法的修改由全国人民代表大会常务委员会或者五分之一以上的全国人民代表大会代表提议，并由全国人民代表大会以全体代表的三分之二以上的多数通过。","options":["正确","错误"],"answer":0,"explain":"我国宪法明确规定，宪法的修改由全国人大常委会或者五分之一以上的全国人大代表提议，并由全国人民代表大会以全体代表的三分之二以上的多数通过。题干表述与宪法条文一致，故判断为正确。"},{"id":"sy-2025-25","type":"judge","stem":"根据《民法典》，诉讼时效期间届满后，当事人之间的债权债务关系即行消灭。","options":["正确","错误"],"answer":1,"explain":"《民法典》规定，诉讼时效期间届满的，义务人可以提出不履行义务的抗辩，但权利人实体权利和债权债务关系本身并不消灭。诉讼时效届满只是使义务人取得抗辩权，并非使债权债务关系归于消灭，故本题表述错误。"},{"id":"sy-2025-26","type":"judge","stem":"根据《党政机关公文处理工作条例》，公文标题一般由发文机关名称、事由和文种组成，其中文种是公文标题不可缺少的要素。","options":["正确","错误"],"answer":0,"explain":"《党政机关公文处理工作条例》规定，公文标题由发文机关名称、事由和文种组成。发文机关名称和事由可以根据需要省略，但文种是表明公文性质、用途和行文方向的必备要素，不能省略，故本题表述正确。"}]}]}];
